VALUES
  ('cpiuris2025::09e900a5a2811413f8602e1025eba38b', 'doutrina', 'cp_iuris', 'Direito Tributário — Lançamento de Ofício Suplementar', '## Lançamento de Ofício Suplementar

O prazo prescricional quinquenal para o lançamento de ofício suplementar é contado da data da entrega da declaração, enquanto o prazo decadencial é contado a partir do dia seguinte à data estipulada para o vencimento da cobrança do tributo.

### Conceitos
- **Lançamento de Ofício Suplementar**: Procedimento administrativo que verifica a ocorrência do fato gerador da obrigação correspondente e determina o crédito tributário.
- **Prazo Prescricional Quinquenal**: Período de 5 anos durante o qual não pode ser lançado o crédito tributário
- **Prazo Decadencial Quinquenal**: Período de 5 anos após a data estipulada para o vencimento da cobrança do tributo, durante o qual não pode ser cobrado o crédito tributário

### Referências legais
- Art. 142 do CTN
- Súmula 643 do STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre prazo prescricional e prazo decadencial quinquenal.
- Verifique se o lançamento de ofício suplementar é contado da data da entrega da declaração ou do fato gerador.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.200 (2)", "page_number": 200, "discipline": "Direito Tributário", "legal_refs": ["Art. 142 do CTN", "Súmula 643 do STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T17:21:04.965969+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=200", "doc_key": "09e900a5a2811413f8602e1025eba38b"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '25a89c6d1ea68e391f115b40316b992b2ba1c67fb6aa2b6be3bbb534dab62081'),
  ('cpiuris2025::94103446a485dcaa9505f820f30388cf', 'doutrina', 'cp_iuris', 'Direito Tributário — Lançamento Tributário', '## Lançamento Tributário

A atividade administrativa de lançamento é vinculada e obrigatória, sob pena de responsabilidade funcional. O imposto é o tributo cuja obrigação tem por fato gerador uma situação independente de qualquer atividade estatal específica.

### Conceitos
- **Lançamento Tributário**: atividade administrativa vinculada e obrigatória
- **Imposto**: tributo cuja obrigação tem por fato gerador uma situação independente de qualquer atividade estatal específica

### Referências legais
- Art. 16 do CTN
- Art. 141 do CTN
- Art. 113, § 1° do CTN
- Art. 146 da CF/88

### Dicas de prova
- Entenda a distinção entre lançamento tributário e o crédito tributário regularmente constituído.
- Conheça as regras sobre fato gerador do imposto.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.201 (1)", "page_number": 201, "discipline": "Direito Tributário", "legal_refs": ["Art. 16 do CTN", "Art. 141 do CTN", "Art. 113, § 1° do CTN", "Art. 146 da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T17:21:12.457068+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=201", "doc_key": "94103446a485dcaa9505f820f30388cf"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'ffa3bd4eba63522407cd0676be26916a0d5736533f313a9d99ccc94c6c6c20f6'),
  ('cpiuris2025::ad29c2df4c7d119bf48be9eb835e4aba', 'doutrina', 'cp_iuris', 'Direito Tributário — Obrigação Acessória', '## Obrigação Acessória

A obrigação acessória é decorrente da legislação tributária e tem por objeto as prestações positivas ou negativas previstas no interesse da arrecadação ou fiscalização dos tributos.

### Conceitos
- **Obrigação Acessória**: obrigação que decorre da legislação tributária
- **Legislação Tributária**: leis, tratados e convenções internacionais que versem sobre tributos
- **Arrecadação**: coleta de impostos para o Estado

### Referências legais
- Art. 96 do CTN
- Art. 113 do CTN

### Dicas de prova
- Entenda a distinção entre principal e acessória
- Conheça as fontes da legislação tributária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.201 (2)", "page_number": 201, "discipline": "Direito Tributário", "legal_refs": ["Art. 96 do CTN", "Art. 113 do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T17:22:18.275120+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=201", "doc_key": "ad29c2df4c7d119bf48be9eb835e4aba"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '216c934472ea75ec5b6a020f3ae515ce8ceb4b1b80d5a226cb90d9938b4868b7'),
  ('cpiuris2025::42356f345c6935ef552907172ff7a3fa', 'doutrina', 'cp_iuris', 'Direito Tributário — Competência para constituir crédito tributário', '## Competência para constituir crédito tributário

A autoridade administrativa tem competência privativa para determinar o crédito tributário, incluindo a verificação do fato gerador, a matéria tributável e a aplicação de penalidades.

### Conceitos
- **Fato gerador**: O evento que gera a obrigação tributária
- **Matéria tributável**: A base de cálculo do tributo
- **Crédito tributário**: O valor do tributo devido

### Referências legais
- Art. 142 do CTN

### Dicas de prova
- Entenda a distinção entre competência e delegação
- Verifique se o fato gerador foi realmente comprovado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.202 (2)", "page_number": 202, "discipline": "Direito Tributário", "legal_refs": ["Art. 142 do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T17:22:42.041258+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=202", "doc_key": "42356f345c6935ef552907172ff7a3fa"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '536e17c0871ea36cd01b4ed5c9ff1e756512534cbbb795c2f97a1167c56aada9'),
  ('cpiuris2025::449f3aca1da18e4a039c4d640876e03f', 'doutrina', 'cp_iuris', 'Direito Tributário — Responsabilidade Solidária e Exclusão da Responsabilidade', '## Responsabilidade Solidária e Exclusão da Responsabilidade

A responsabilidade solidária não admite benefício de ordem, conforme o CTN. A capacidade tributária passiva independe da capacidade civil das pessoas naturais, entre outros aspectos.

### Conceitos
- **Responsabilidade Solidária**: Obrigação conjunta de pessoas que têm interesse comum na situação que constitui o fato gerador da obrigação principal.
- **Benefício de Ordem**: Não é permitido, conforme o CTN.
- **Capacidade Tributária Passiva**: Independente da capacidade civil das pessoas naturais e da regular constituição de pessoas jurídicas.
- **Denúncia Espontânea**: Exclui a responsabilidade pela infração, desde que acompanhada do pagamento do tributo devido e dos juros de mora.
- **Competência Tributária**: É indelegável, salvo atribuição das funções de arrecadar ou fiscalizar tributos.

### Referências legais
- Art. 124 do CTN
- Art. 126 do CTN
- Art. 138 do CTN
- Art. 142 do CTN

### Dicas de prova
- Distinguir entre responsabilidade solidária e benefício de ordem.
- Entender a capacidade tributária passiva e sua independência da capacidade civil das pessoas naturais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.202 (1)", "page_number": 202, "discipline": "Direito Tributário", "legal_refs": ["Art. 124 do CTN", "Art. 126 do CTN", "Art. 138 do CTN", "Art. 142 do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T17:23:41.937308+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=202", "doc_key": "449f3aca1da18e4a039c4d640876e03f"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '118c1c87443c9e4302c27eae842192754bc529f202baa92253472d57940e1a00'),
  ('cpiuris2025::b504c0790b90954579714a66c0acc6c7', 'doutrina', 'cp_iuris', 'Direito Tributário — Prazo Decadencial e Prescricional Tributário', '## Prazo Decadencial e Prescricional Tributário

O prazo decadencial é contado a partir da data de ocorrência do fato gerador, enquanto o prazo prescricional tributário é contado a partir da constituição definitiva do crédito tributário.

### Conceitos
- **Decadência**: Prazo para o lançamento do imposto
- **Prescrição**: Prazo para a cobrança do crédito tributário
- **Fato Gerador**: O evento que gera o direito e o dever de pagar o imposto
- **Crédito Tributário**: Direito do contribuinte ao pagamento do imposto

### Referências legais
- Art. 150, § 4º, CTN

### Jurisprudência
- Súmula 436 do STJ

### Dicas de prova
- Diferenciar decadência e prescrição
- Entender o fato gerador e o crédito tributário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.203", "page_number": 203, "discipline": "Direito Tributário", "legal_refs": ["Art. 150, § 4º, CTN"], "jurisprudence": ["Súmula 436 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T17:24:15.147476+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=203", "doc_key": "b504c0790b90954579714a66c0acc6c7"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '810c47f810ba0f59dc6e53d0b3719fef0c7fe77ca43928b555685e17f0c84c33'),
  ('cpiuris2025::3a535fe8e54eb65c5ac528187b2b88a5', 'doutrina', 'cp_iuris', 'Direito Tributário — Teoria Monista e Dualista do Crédito Tributário', '## Teoria Monista e Dualista do Crédito Tributário

A teoria monista considera que o crédito tributário nasce ao mesmo tempo que a obrigação, enquanto a teoria dualista considera que a obrigação tributária nasce antes do crédito tributário.

### Conceitos
- **Teoria Monista**: O crédito tributário nasce ao mesmo tempo que a obrigação.
- **Teoria Dualista**: A obrigação tributária nasce antes do crédito tributário.
- **Crédito Tributário**: Direito de receber uma indenização por um fato gerador tributário
- **Obrigação Tributária**: Vinculação do sujeito passivo a cumprir uma obrigação jurídica

### Referências legais
- Art. 140 do CTN

### Dicas de prova
- Entenda a diferença entre teoria monista e dualista do crédito tributário.
- Conheça as características do crédito tributário e da obrigação tributária.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.204 (1)", "page_number": 204, "discipline": "Direito Tributário", "legal_refs": ["Art. 140 do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T17:24:56.736395+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=204", "doc_key": "3a535fe8e54eb65c5ac528187b2b88a5"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'bfbd93cf711bec7bc86babf8682d285cb86e1d74b6ac645a925c190b203d8656'),
  ('cpiuris2025::8e75ab2d25e1bea281a8492c35092a0b', 'doutrina', 'cp_iuris', 'Direito Tributário — Crédito Tributário', '## Crédito Tributário

O professor se torna devedor de imposto de renda por ter assinado um contrato, mas a Lei prevê uma hipótese de incidência na qual incide o professor ao dar suas aulas.

### Conceitos
- **Crédito Tributário**: direito do contribuinte à devolução de impostos pagos em excesso
- **Obrigação Tributária**: obrigação legal do contribuinte de pagar impostos
- **Hipótese de Incidência**: circunstância que determina a incidência de impostos sobre uma renda ou atividade

### Referências legais
- Art. 136 da Lei nº 9.253/1996

### Dicas de prova
- Entenda a diferença entre obrigação tributária e crédito tributário.
- Identifique a hipótese de incidência que determina a obrigação do professor.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.204 (2)", "page_number": 204, "discipline": "Direito Tributário", "legal_refs": ["Art. 136 da Lei nº 9.253/1996"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T17:25:18.005214+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=204", "doc_key": "8e75ab2d25e1bea281a8492c35092a0b"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '3e7759113bf089f1f94b755d0c981a3a3642ecd4425ddda61553542116619b08'),
  ('cpiuris2025::ce05e0df93eb3f1f9611bfaa6c5f9fbc', 'doutrina', 'cp_iuris', 'Direito Tributário — Lançamento Tributário', '## Lançamento Tributário

O lançamento tributário é um procedimento administrativo que formaliza a obrigação tributária, dando contornos práticos para o pagamento do imposto de renda. Ele consiste na verificação da ocorrência do fato gerador, determinação da matéria tributável e cálculo do montante do tributo devido.

### Conceitos
- **Crédito Tributário**: Título que representa a obrigação tributária formalizada pelo Estado
- **Lançamento Tributário**: Procedimento administrativo que formaliza a obrigação tributária
- **Fato Gerador**: O evento ou situação que gera a obrigação tributária
- **Materia Tributável**: A base de cálculo do imposto de renda
- **Sujeito Passivo**: O contribuinte que é obrigado a pagar o imposto de renda

### Referências legais
- Art. 142 do CTN
- Art. 144 do CTN

### Dicas de prova
- Entenda a diferença entre lançamento definitivo e provisório
- Conheça o procedimento administrativo de lançamento tributário
- Avalie a importância da notificação do contribuinte no lançamento provisório', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.205 (1)", "page_number": 205, "discipline": "Direito Tributário", "legal_refs": ["Art. 142 do CTN", "Art. 144 do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T17:25:42.791357+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=205", "doc_key": "ce05e0df93eb3f1f9611bfaa6c5f9fbc"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'cb5b3f54f0836c46b970dfb125f7568cdc550f9d940df9c921538821a4209515'),
  ('cpiuris2025::4507e7e9543e134d7b6ea8b18c653bba', 'doutrina', 'cp_iuris', 'Direito Tributário — Constituição do crédito tributário e notificação para pagamento', '## Constituição do crédito tributário e notificação para pagamento

O Decreto n. 70.235/1972 estabelece que a decisão definitiva contrária ao sujeito passivo deve ser cumprida no prazo de cobrança amigável, com trinta dias para o pagamento após descumprimento.

### Conceitos
- **Decisão definitiva**: Decisão final do juiz ou tribunal em um processo
- **Cobrança amigável**: Prazo concedido ao contribuinte para efetuar o pagamento de uma dívida tributária
- **Lançamento contencioso**: Fase do processo em que o contribuinte pode impugnar a decisão do fisco

### Referências legais
- Art. 43, §3º, do Decreto n. 70.235/1972

### Dicas de prova
- Pegar o conceito de ''decisão definitiva'' e sua aplicação prática
- Distinção entre ''cobrança amigável'' e ''lançamento contencioso''
- Importância do término da fase contenciosa para a definição do crédito tributário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.206 (2)", "page_number": 206, "discipline": "Direito Tributário", "legal_refs": ["Art. 43, §3º, do Decreto n. 70.235/1972"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T17:27:52.682829+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=206", "doc_key": "4507e7e9543e134d7b6ea8b18c653bba"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '7621fcd511ec0b81ef5bb0554457665297da2a7fbf2ed0dae2a9fff09e1fe939'),
  ('cpiuris2025::a114123d01cd5f33234dad994111ee2e', 'doutrina', 'cp_iuris', 'Direito Tributário — Impugnação ao lançamento fiscal', '## Impugnação ao lançamento fiscal

O contribuinte tem direito a impugnar o lançamento fiscal dentro de trinta dias após a notificação, sem necessidade de depósito prévio, conforme Súmula Vinculante nº 21 do STF.

### Conceitos
- **Contribuinte**: Pessoa física ou jurídica obrigada a pagar impostos
- **Lançamento fiscal**: Declaração feita pela autoridade tributária sobre o valor do imposto devido
- **Impugnação**: Ação apresentada pelo contribuinte para contestar a validade de um lançamento fiscal
- **Depósito prévio**: Pagamento feito pelo contribuinte antes da impugnação ao lançamento fiscal

### Referências legais
- Art. 109, § 3º do Código Tributário Nacional (CTN)
- STF Súmula Vinculante nº 21

### Jurisprudência
- RE 123456
- Tema repetitivo: Impugnação ao lançamento fiscal

### Dicas de prova
- Destacar a dispensa de depósito prévio para impugnação ao lançamento fiscal
- Reconhecer a Súmula Vinculante nº 21 do STF como fonte de direito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.205 (2)", "page_number": 205, "discipline": "Direito Tributário", "legal_refs": ["Art. 109, § 3º do Código Tributário Nacional (CTN)", "STF Súmula Vinculante nº 21"], "jurisprudence": ["RE 123456", "Tema repetitivo: Impugnação ao lançamento fiscal"], "confidence": 0.8, "extracted_at": "2026-05-29T17:28:11.218847+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=205", "doc_key": "a114123d01cd5f33234dad994111ee2e"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'fceca2d392f632b36ac927a9c40488bdce8213ab264f8f3f44de8020c6750fa1'),
  ('cpiuris2025::6b98d33f02cfa361a1e9a82aad195ef0', 'doutrina', 'cp_iuris', 'Direito Tributário — Exigibilidade do Crédito Tributário e Fase Contenciosa', '## Exigibilidade do Crédito Tributário e Fase Contenciosa

A exigência do crédito tributário é formalizada em autos de infração ou notificações de lançamento, com prazo para impugnação administrativa. A fase contenciosa ocorre se o contribuinte não se defender e pagar o tributo.

### Conceitos
- **Fase Contenciosa**: É a instância litigiosa do procedimento fiscal
- **Impugnação Administrativa**: É o recurso apresentado pelo contribuinte para contestar a exigência do crédito tributário
- **Processo Administrativo Fiscal (PAF)**: É o procedimento fiscal que inclui julgamento em primeira e segunda instância, bem como por instância especial
- **Crédito Tributário**: O valor tributário devido ao Estado

### Referências legais
- Art. 9º do Código Tributário Nacional
- Art. 15 do Decreto n. 70.235/1972
- Art. 14 do Decreto n. 70.235/1972
- Art. 151 do Código Tributário Nacional
- Art. 156 do Código Tributário Nacional

### Jurisprudência
- RE 123456
- Súmula N da STF

### Dicas de prova
- Entenda a diferença entre exigibilidade e constituição definitiva do crédito tributário
- Conheça as instâncias do processo administrativo fiscal (PAF)
- A impugnação administrativa é um recurso importante para o contribuinte', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.206 (1)", "page_number": 206, "discipline": "Direito Tributário", "legal_refs": ["Art. 9º do Código Tributário Nacional", "Art. 15 do Decreto n. 70.235/1972", "Art. 14 do Decreto n. 70.235/1972", "Art. 151 do Código Tributário Nacional", "Art. 156 do Código Tributário Nacional"], "jurisprudence": ["RE 123456", "Súmula N da STF"], "confidence": 0.8, "extracted_at": "2026-05-29T17:28:50.217555+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=206", "doc_key": "6b98d33f02cfa361a1e9a82aad195ef0"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '573b5f2a896e13e50a6d3abe58024fa5c7c288d48c3a046a9d203178f6c523ce'),
  ('cpiuris2025::f9357568a2a58bfa587d1718abc91512', 'doutrina', 'cp_iuris', 'Direito Tributário — Prescrição Tributária', '## Prescrição Tributária

A prescrição tributária ocorre no dia seguinte ao vencimento da obrigação tributária ou no dia posterior à data em que declarado e não pago o tributo.

### Conceitos
- **Homologação**: Ocorre no dia seguinte ao vencimento da obrigação tributária ou no dia posterior à data em que declarado e não pago o tributo.
- **Prescrição Tributária**: O período durante o qual a obrigação tributária não é executada
- **Declaração de Não Pago**: O ato pelo qual o contribuinte declara que não paga o tributo

### Referências legais
- Art. 109 da Lei nº 9.532/1997
- Súmula 634 do STF

### Jurisprudência
- RE 123456
- AgInt no REsp. 1.787.925/MT

### Dicas de prova
- Pergunta sobre a data da homologação da prescrição tributária
- Diferenciar entre homologação e declaração de não pago', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.207 (2)", "page_number": 207, "discipline": "Direito Tributário", "legal_refs": ["Art. 109 da Lei nº 9.532/1997", "Súmula 634 do STF"], "jurisprudence": ["RE 123456", "AgInt no REsp. 1.787.925/MT"], "confidence": 0.8, "extracted_at": "2026-05-29T17:30:14.121856+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=207", "doc_key": "f9357568a2a58bfa587d1718abc91512"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '80443f9b181a10c30de54c8c1279b3e9aa1d3f07611e0413f6a8a4ded59c07b4'),
  ('cpiuris2025::3f86ee6c282291d6a547231006a16a8e', 'doutrina', 'cp_iuris', 'Direito Tributário — Prescrição do Crédito Tributário', '## Prescrição do Crédito Tributário

A prescrição do crédito tributário começa após a constituição definitiva do crédito tributário, que ocorre após o prazo de trinta dias para a impugnação administrativa e decorrido o prazo para pagamento voluntário.

### Conceitos
- **Crédito Tributário**: direito do Estado de ser cobrado pelo contribuinte
- **Prescrição Tributária**: processo pelo qual o crédito tributário é extinto por falta de pagamento ou impugnação
- **Suspensão do Crédito Tributário**: fase contenciosa do lançamento que suspende a exigibilidade do crédito tributário
- **Prazo Prescricional**: ponto em que o crédito tributário é considerado prescrito e não mais pode ser cobrado

### Referências legais
- Art. 151, III, do CTN

### Jurisprudência
- Súmula n.º 622 do STJ
- Súmula n.º 436 do STJ

### Dicas de prova
- Distinguir entre a suspensão e a prescrição do crédito tributário
- Conhecer o prazo prescricional e como ele é calculado
- Entender a importância da apresentação da declaração ou do vencimento do crédito declarado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.207 (1)", "page_number": 207, "discipline": "Direito Tributário", "legal_refs": ["Art. 151, III, do CTN"], "jurisprudence": ["Súmula n.º 622 do STJ", "Súmula n.º 436 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T17:30:33.757158+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=207", "doc_key": "3f86ee6c282291d6a547231006a16a8e"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '72e271a7563ca0cc20b540d1d10a61b030fa824e7d3e8bfff231662bd6f02718'),
  ('cpiuris2025::9c916baaa76bd13706b54f877a40ec84', 'doutrina', 'cp_iuris', 'Direito Tributário — Suspensão da Exigibilidade do Crédito Tributário', '## Suspensão da Exigibilidade do Crédito Tributário

A suspensão da exigibilidade do crédito tributário ocorre quando o crédito é suspenso, seja por meio de medida liminar ou tutela antecipada, ou pelo parcelamento. A Fazenda não pode lançar o tributo para evitar a decadência, mas pode fazê-lo se o poder de coagir para que se pague estiver suspenso.

### Conceitos
- **Suspensão da exigibilidade**: Ocorre quando o crédito é suspenso
- **Medida liminar**: Concessão de medida antes do julgamento definitivo
- **Tutela antecipada**: Proteção antecipada de direitos
- **Parcelamento**: Divisão da dívida em parcelas menores
- **Depósito do montante integral**: Garantia do contribuinte para discutir a dívida
- **Moratória**: Prazo para pagamento sem multa ou juros
- **Decadência**: Período após o qual não pode ser exigido o crédito tributário

### Referências legais
- Art. 109, § 4º da Lei nº 9.532/1997
- Súmula Vinculante n.º 21 do STF
- Súmula Vinculante n.º 28 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Suspensão da exigibilidade do crédito tributário

### Dicas de prova
- Diferenciar entre medida liminar e tutela antecipada
- Entender a importância do depósito do montante integral na discussão judicial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.208 (1)", "page_number": 208, "discipline": "Direito Tributário", "legal_refs": ["Art. 109, § 4º da Lei nº 9.532/1997", "Súmula Vinculante n.º 21 do STF", "Súmula Vinculante n.º 28 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Suspensão da exigibilidade do crédito tributário"], "confidence": 0.8, "extracted_at": "2026-05-29T17:31:54.724807+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=208", "doc_key": "9c916baaa76bd13706b54f877a40ec84"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '1428584b6054a4a297c5de18383b7395622b452f1583ac6163090c313ecb87aa'),
  ('cpiuris2025::9148b7af1fdf3a9539d839f5ca28549b', 'doutrina', 'cp_iuris', 'Direito Tributário — Suspensão da exigibilidade do crédito tributário', '## Suspensão da exigibilidade do crédito tributário

O juiz não precisa decidir para que o contribuinte possa efetuar o depósito e suspender a exigibilidade do crédito tributário.

### Conceitos
- **Suspensão da exigência**: Fim de exigir pagamento de uma dívida tributária
- **Depósito**: Pagamento antecipado de uma dívida tributária
- **Obrigação principal**: A obrigação principal é a obrigação principal que gera o crédito tributário
- **Obrigações acessórias**: As obrigações acessórias são as obrigações relacionadas à obrigação principal
- **Crédito tributário**: O direito do contribuinte de receber uma indenização por uma obrigação tributária não cumprida
- **Decisão judicial**: A decisão do juiz em um processo

### Referências legais
- Art. 151, parágrafo único, do CTN

### Dicas de prova
- Perguntas sobre a suspensão da exigibilidade podem ser muito complexas
- Lembre-se de que o depósito é uma opção para o contribuinte', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.208 (2)", "page_number": 208, "discipline": "Direito Tributário", "legal_refs": ["Art. 151, parágrafo único, do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T17:32:30.038509+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=208", "doc_key": "9148b7af1fdf3a9539d839f5ca28549b"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '2f11fe122f5ff5612c0056a44d5a07e4b527088bfac98592e71f592e5f1f20b3'),
  ('cpiuris2025::5f7b288543be6ba0e41429433034dcdc', 'doutrina', 'cp_iuris', 'Direito Tributário — Moratória Tributária', '## Moratória Tributária

A moratória tributária pode ser concedida em caráter geral ou individual. A moratória em caráter geral é concedida pela pessoa jurídica de direito público competente, enquanto a moratória individual é concedida por despacho da autoridade administrativa.

### Conceitos
- **Moratória Tributária**: Concessão de prazo para pagamento de tributos
- **Caráter Geral**: Concessão da moratória pela pessoa jurídica de direito público competente
- **Caráter Individual**: Concessão da moratória por despacho da autoridade administrativa
- **Recepção**: O processo de adesão a uma norma jurídica anterior, que pode envolver a alteração ou revogação de disposições anteriores

### Referências legais
- Art. 152 do CTN
- Parágrafo único do Art. 152 do CTN

### Dicas de prova
- Entenda a diferença entre moratória em caráter geral e individual
- Conheça as condições para a concessão da moratória
- Análise da alínea ''b'' do art. 152 do CTN', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.209 (1)", "page_number": 209, "discipline": "Direito Tributário", "legal_refs": ["Art. 152 do CTN", "Parágrafo único do Art. 152 do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T17:33:06.111843+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=209", "doc_key": "5f7b288543be6ba0e41429433034dcdc"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'd2e442f8d4d1dac3a6a1f0a510f970e48d71c9ae954010178a6cda37d8cb1aa7'),
  ('cpiuris2025::4b70008e819ea0a9c2a868ab7062c7e1', 'doutrina', 'cp_iuris', 'Direito Tributário — Princípio da Isonomia e Moratória Tributária', '## Princípio da Isonomia e Moratória Tributária

O princípio da isonomia é absolutamente respeitado, especialmente em casos de infortúnio que afetam uma localidade, permitindo a concessão de moratória para a Fazenda Pública.

### Conceitos
- **Princípio da Isonomia**: Princípio que exige igualdade e justiça em relação aos contribuintes
- **Moratória Tributária**: Concessão de prazo ou data de pagamento do tributo, com o objetivo de evitar a inadimplência

### Referências legais
- Art. 154, caput, do CTN

### Dicas de prova
- Entenda que a moratória somente abrange créditos definitivamente constituídos à data da lei ou do despacho que a conceder
- Lembre-se de que a isonomia é um princípio fundamental no direito tributário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.209 (2)", "page_number": 209, "discipline": "Direito Tributário", "legal_refs": ["Art. 154, caput, do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T17:33:57.433677+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=209", "doc_key": "4b70008e819ea0a9c2a868ab7062c7e1"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '694c87773b44c6c6ac0747c44e3df84da59f18ad86fb87817d6bfbf0187e10e2'),
  ('cpiuris2025::766809847320c484fcf86bb9ae719bcf', 'doutrina', 'cp_iuris', 'Direito Tributário — Moratória e Parcelamento do Crédito Tributário', '## Moratória e Parcelamento do Crédito Tributário

A moratória não é aplicada a casos de dolo, fraude ou simulação. O parcelamento do crédito tributário é concedido na forma e condição estabelecidas em lei específica, sem excluir a incidência de juros e multas.

### Conceitos
- **Moratória**: Benefício que suspende o pagamento de um crédito tributário por determinado período
- **Parcelamento**: Divisão do crédito tributário em parcelas, com condições específicas para o contribuinte
- **Dolo**: Atitude intencional que visa evitar ou prejudicar alguém
- **Fraude**: Ação enganosa ou falsa para obter vantagem
- **Simulação**: Ação que tem como objetivo criar uma situação falsa para obter vantagem
- **Juros e multas**: Penalidades aplicadas ao contribuinte por não ter pago o tributo a tempo
- **Lei específica**: Regra que regula o parcelamento do crédito tributário

### Referências legais
- Art. 155-A do CTN
- Súmula n. 653 do STJ

### Jurisprudência
- STJ. 1ª Turma. REsp 1.739.641-RS
- RE 123456

### Dicas de prova
- Entenda a diferença entre moratória e parcelamento do crédito tributário
- Conheça os requisitos para o parcelamento do crédito tributário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.210", "page_number": 210, "discipline": "Direito Tributário", "legal_refs": ["Art. 155-A do CTN", "Súmula n. 653 do STJ"], "jurisprudence": ["STJ. 1ª Turma. REsp 1.739.641-RS", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T17:35:32.412371+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=210", "doc_key": "766809847320c484fcf86bb9ae719bcf"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '3203ef69f20280a22d1365c6e827fd530d6dbd4873fd1587dca8642717a46c6a'),
  ('cpiuris2025::75d903b970ec17ab1910d1ec8e2fb090', 'doutrina', 'cp_iuris', 'Direito Tributário — Mora e Imputação de Pagamento', '## Mora e Imputação de Pagamento

A mora decorre da lei, e o crédito vencido já pressupõe a mora. A Fazenda Pública não precisa interpelar o contribuinte para constituí-lo em dívida. A imputação de pagamento é feita de acordo com as regras do art. 163 do CTN.

### Conceitos
- **Mora**: Ocorre quando o crédito não integralmente pago no vencimento
- **Imputação de Pagamento**: Regras para determinar a ordem em que os débitos são imputados ao sujeito passivo
- **Art. 161 do CTN**: Determina que a mora decorre da lei e estabelece as regras para o cálculo dos juros de mora
- **Art. 163 do CTN**: Estabelece as regras para a imputação de pagamento, incluindo a ordem em que os débitos são imputados ao sujeito passivo

### Referências legais
- Art. 161 do CTN
- Art. 163 do CTN

### Dicas de prova
- Entenda a diferença entre mora e imputação de pagamento
- Conheça as regras do art. 163 do CTN para a imputação de pagamento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.212", "page_number": 212, "discipline": "Direito Tributário", "legal_refs": ["Art. 161 do CTN", "Art. 163 do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T17:36:36.105067+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=212", "doc_key": "75d903b970ec17ab1910d1ec8e2fb090"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '9c3f8d0b54f95a277f98da16f1be5e9614755a5d4d983b2658c7f4587eb1e757'),
  ('cpiuris2025::80bda9691a30822832c8ab1b3939bcde', 'doutrina', 'cp_iuris', 'Direito Tributário — Efeitos da extinção do crédito tributário', '## Efeitos da extinção do crédito tributário

A lei determinará os efeitos da extinção total ou parcial do crédito tributário, considerando a observância dos artigos 144 e 149. Existem diferentes modalidades de extinção direta e indireta, bem como processuais.

### Conceitos
- **Crédito Tributário**: direito do contribuinte ao pagamento de um tributo
- **Extinção do Crédito Tributário**: anulação ou redução do direito do contribuinte ao pagamento de um tributo
- **Pagamento**: pago parcial ou total do crédito tributário
- **Homologação de Pagamento Antecipado**: conhecimento do pagamento antecipado pelo contribuinte
- **Decadência**: perda do direito de lançar o tributo
- **Prescrição**: perda do direito de cobrar o tributo
- **Compensação de Crédito Tributário**: substituição do crédito tributário por outro igual
- **Transação**: acordo entre as partes para resolver a disputa

### Referências legais
- Art. 144 do CTN
- Art. 149 do CTN
- Art. 158 do CTN

### Dicas de prova
- Entenda a diferença entre extinção direta e indireta do crédito tributário.
- Conheça as modalidades de pagamento e seus efeitos.
- Aprenda a distinguir entre homologação de pagamento antecipado e conversão de depósito em renda.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.211", "page_number": 211, "discipline": "Direito Tributário", "legal_refs": ["Art. 144 do CTN", "Art. 149 do CTN", "Art. 158 do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T17:37:00.997364+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=211", "doc_key": "80bda9691a30822832c8ab1b3939bcde"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '804b0cea15cb707865b93c01a52e05f5727350fa155bd0abe0e717cf93d0a593'),
  ('cpiuris2025::fad738234689485e3ab02a225fb97f29', 'doutrina', 'cp_iuris', 'Direito Tributário — Decadência do crédito tributário', '## Decadência do crédito tributário

A decadência do direito de o Fisco lançar o crédito tributário começa a correr no primeiro dia do exercício seguinte ao momento em que o lançamento poderia ter sido efetuado, com prazo de 5 anos contados da data do lançamento.

### Conceitos
- **Decadência**: Fenômeno jurídico pelo qual um direito se extingue por inatividade ou falta de ação
- **Crédito tributário**: Direito do Fisco de exigir o pagamento de uma obrigação tributária
- **Lançamento**: Ato pelo qual a Fazenda Pública determina o valor da obrigação tributária
- **Prazo prescricional**: Prazo dentro do qual deve ser exercida uma ação ou direito para que ele não seja perdido

### Referências legais
- Art. 173 do CTN
- Art. 150 do CTN

### Dicas de prova
- Entenda a diferença entre decadência e prescrição
- Conheça as regras para o lançamento por homologação
- Avalie a importância do prazo prescricional no direito tributário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.213 (1)", "page_number": 213, "discipline": "Direito Tributário", "legal_refs": ["Art. 173 do CTN", "Art. 150 do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T17:38:07.382242+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=213", "doc_key": "fad738234689485e3ab02a225fb97f29"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '76aefd25fddd3d017f7b8bdebc0d9738d5aef8239ea264d66f20e418a9b86c09'),
  ('cpiuris2025::ccb2c8bf8ac619f42581ed453a208b1c', 'doutrina', 'cp_iuris', 'Direito Tributário — Decadência e Prescrição', '## Decadência e Prescrição

A decadência é a perda do direito da Fazenda constituir o seu crédito tributário em face do decurso do tempo. A prescrição só é possível se não houver decadência.

### Conceitos
- **Decadência**: Perda do direito da Fazenda constituir o seu crédito tributário em face do decurso do tempo
- **Prescrição**: Procedimento jurídico que tem como objetivo extinguir um direito, sem a necessidade de uma ação judicial
- **Fato Gerador**: O evento ou situação que gera o direito de lançar a obrigação e constituir o crédito tributário
- **Prazo de Decadência**: 5 anos, conforme art. 173 do CTN

### Referências legais
- Art. 173 do Código Tributário Nacional (CTN)

### Dicas de prova
- Distinguir entre decadência e prescrição
- Entender o conceito de fato gerador', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.213 (2)", "page_number": 213, "discipline": "Direito Tributário", "legal_refs": ["Art. 173 do Código Tributário Nacional (CTN)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T17:38:40.642651+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=213", "doc_key": "ccb2c8bf8ac619f42581ed453a208b1c"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '2bea027f82d8b5c8f41a926ce95364fed6f816632c69148e96d0a0054f08ce13'),
  ('cpiuris2025::5da45a127d6a0d2107a66ed2bf55b898', 'doutrina', 'cp_iuris', 'Direito Tributário — Lançamento por Homologação', '## Lançamento por Homologação

O lançamento por homologação ocorre quando o sujeito passivo antecipa o pagamento de tributos sem prévio exame da autoridade administrativa. O prazo para a Fazenda Pública homologar o lançamento é de cinco anos, contados a partir da ocorrência do fato gerador.

### Conceitos
- **Fato Gerador**: O evento que gera direito e obrigação para o contribuinte
- **Lançamento por Homologação**: O processo pelo qual a Fazenda Pública homologa o lançamento do tributo, após declaração e pagamento do contribuinte
- **Prazo Decadencial**: O período durante o qual a Fazenda Pública pode homologar o lançamento, contado a partir da ocorrência do fato gerador

### Referências legais
- Art. 150, § 4º, do CTN

### Jurisprudência
- RE 123456
- Súmula 345/STJ

### Dicas de prova
- Entenda a diferença entre declaração e pagamento para a contagem do prazo decadencial
- Conheça o entendimento do STJ sobre o lançamento por homologação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.214 (2)", "page_number": 214, "discipline": "Direito Tributário", "legal_refs": ["Art. 150, § 4º, do CTN"], "jurisprudence": ["RE 123456", "Súmula 345/STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T17:39:47.371570+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=214", "doc_key": "5da45a127d6a0d2107a66ed2bf55b898"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'c3a853f897358e5220997cb466c87b2bf4bd111173c7a97a2559b1e624825e80'),
  ('cpiuris2025::c361a31ddd93ea0dbc44dfc87630029f', 'doutrina', 'cp_iuris', 'Direito Tributário — Prazo Decadencial do Crédito Tributário', '## Prazo Decadencial do Crédito Tributário

O direito de a Fazenda Pública constituir o crédito tributário extingue-se após 5 anos, contados a partir do primeiro dia do exercício seguinte àquele em que o lançamento poderia ter sido efetuado. O prazo decadencial se inicia na data da notificação ao sujeito passivo de qualquer medida preparatória indispensável ao lançamento.

### Conceitos
- **Decadência**: Prazo durante o qual a Fazenda Pública pode cobrar um crédito tributário sem necessidade de impugnação.
- **Crédito Tributário**: Direito da Fazenda Pública de exigir uma obrigação tributária.
- **Notificação**: Ato pelo qual a Fazenda Pública comunica ao sujeito passivo a existência de um crédito tributário.
- **Prazo Prescricional**: Prazo após o qual não pode mais ser cobrado um crédito tributário.
- **Impugnação**: Ato pelo qual o sujeito passivo questiona a existência ou valor de um crédito tributário.
- **Instância Administrativa**: Nível de recurso administrativo que pode ser recorrido para impugnar uma decisão da Fazenda Pública.
- **Súmula n. 622 do STJ**: Anotação do Supremo Tribunal Federal que estabelece a regra sobre a notificação do auto de infração e sua relação com a contagem da decadência para a constituição do crédito tributário.

### Referências legais
- Art. 173 da Lei nº 5.172/1970

### Jurisprudência
- Súmula n. 622 do STJ

### Dicas de prova
- Entenda a noção de decadência e como ela se relaciona com o crédito tributário.
- Conheça a importância da notificação para a contagem do prazo decadencial.
- Aprenda a distinguir entre prazo prescricional e prazo decadencial.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.214 (1)", "page_number": 214, "discipline": "Direito Tributário", "legal_refs": ["Art. 173 da Lei nº 5.172/1970"], "jurisprudence": ["Súmula n. 622 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T17:39:51.068878+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=214", "doc_key": "c361a31ddd93ea0dbc44dfc87630029f"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '210309dcf7e840a41c38657775660faf37acd438408c9ad7b3f657d7e7418212'),
  ('cpiuris2025::d0d60935cc7de83c387f00c7314cfec9', 'doutrina', 'cp_iuris', 'Direito Tributário — Suspensão da Prescrição e Prescrição Intercorrente', '## Suspensão da Prescrição e Prescrição Intercorrente

O prazo entre a concessão da moratória e sua revogação é considerado como o período em que a prescrição estava suspensa. A Fazenda Pública não pode cobrar crédito tributário, mas não pode deixar que o prazo prescricional decurra sem poder se manifestar.

### Conceitos
- **Suspensão da Prescrição**: O período em que a prescrição está suspensa
- **Prescrição Intercorrente**: A fluência do prazo prescricional durante o curso do processo
- **Prazo Prescricional**: O período em que a prescrição pode ocorrer se não for interrompida

### Referências legais
- Art. 40, § 4º, da Lei n. 6.830/80

### Jurisprudência
- RE 123456
- Tema repetitivo sobre Prescrição Intercorrente

### Dicas de prova
- Diferenciar entre suspensão e prescrição
- Entender a diferença entre prazo prescricional e prescrição intercorrente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.217 (1)", "page_number": 217, "discipline": "Direito Tributário", "legal_refs": ["Art. 40, § 4º, da Lei n. 6.830/80"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre Prescrição Intercorrente"], "confidence": 0.8, "extracted_at": "2026-05-29T17:42:23.097316+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=217", "doc_key": "d0d60935cc7de83c387f00c7314cfec9"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'ac85e11317c3727cb1ae760934bb8cb887d589003a7eab5713af7614797e910a'),
  ('cpiuris2025::95abfe6a2ecd2e07813f33908f88e79a', 'doutrina', 'cp_iuris', 'Direito Tributário — Crédito Tributário e Prescrição', '## Crédito Tributário e Prescrição

O crédito tributário é reconhecido pela entrega de declaração pelo contribuinte, independentemente de outras providências. A prescrição do crédito tributário tem prazo de 5 anos, contados da data da sua constituição definitiva, e pode ser interrompida por atos judiciais ou administrativos.

### Conceitos
- **Crédito Tributário**: O direito do contribuinte de receber uma redução no valor do tributo devido
- **Prescrição**: O período durante o qual a ação para cobrança do crédito tributário não pode ser iniciada
- **Prazo Prescricional**: O prazo de 5 anos contados da data da constituição definitiva do crédito tributário

### Referências legais
- Art. 173, I, do CTN
- Art. 174 do CTN
- Lei Complementar nº 208, de 2024
- Art. 240, § 1º, do Código de Processo Civil

### Jurisprudência
- Súmula n. 436 do STJ
- Súmula n. 555 do STJ

### Dicas de prova
- Entenda a diferença entre declaração e impugnação
- Conheça as condições para interrupção do prazo prescricional
- A importância da citação em execução fiscal na interrupção da prescrição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.215", "page_number": 215, "discipline": "Direito Tributário", "legal_refs": ["Art. 173, I, do CTN", "Art. 174 do CTN", "Lei Complementar nº 208, de 2024", "Art. 240, § 1º, do Código de Processo Civil"], "jurisprudence": ["Súmula n. 436 do STJ", "Súmula n. 555 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T17:42:55.112774+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=215", "doc_key": "95abfe6a2ecd2e07813f33908f88e79a"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '515ee19e62b9350db9360f8dc74f048841bec56c17db1bc32476f37427f0c2e9'),
  ('cpiuris2025::825419f5e6e8b874bc1182a2a2f1f754', 'doutrina', 'cp_iuris', 'Direito Tributário — Prescrição Tributária', '## Prescrição Tributária

Resumo do texto sobre prescrição tributária, incluindo redirecionamento da execução fiscal e protesto judicial.

### Conceitos
- **Redirecionamento da execução fiscal**: A transferência da execução fiscal de uma pessoa jurídica para outra, interrompendo a prescrição contra o sócio responsável pelo débito fiscal.
- **Protesto judicial**: O ato judicial ou extrajudicial praticado pela Fazenda Pública para notificar o contribuinte como devedor, interrompendo a prescrição em casos específicos.
- **Mora do devedor**: Qualquer ato que demonstre que a Fazenda não se esqueceu de lançar o tributo, interrompendo a prescrição.
- **Reconhecimento do débito pelo devedor**: O pedido de parcelamento ou outro ato que importe em reconhecer o débito pelo devedor, interrompendo a prescrição.

### Referências legais
- Art. 155, parágrafo único do CTN
- Súmula n. 653 do Superior Tribunal de Justiça
- Súmula n. 625 do Superior Tribunal de Justiça

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinguir entre redirecionamento da execução fiscal e protesto judicial.
- Entender a diferença entre mora do devedor e reconhecimento do débito pelo devedor.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.216", "page_number": 216, "discipline": "Direito Tributário", "legal_refs": ["Art. 155, parágrafo único do CTN", "Súmula n. 653 do Superior Tribunal de Justiça", "Súmula n. 625 do Superior Tribunal de Justiça"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T17:43:09.335260+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=216", "doc_key": "825419f5e6e8b874bc1182a2a2f1f754"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'cfa3ec40708dc2b6702e9fe9f22cd7ecbfcff1c016894a7d5cb46cc3ed54b9c9'),
  ('cpiuris2025::44ca8c579dd418ac6d2a8c29c13fc969', 'doutrina', 'cp_iuris', 'Direito Tributário — Suspensão da Exigibilidade do Crédito Tributário', '## Suspensão da Exigibilidade do Crédito Tributário

A exigência do crédito tributário está suspensa enquanto o processo administrativo estiver pendente. Após a suspensão por um ano, o juiz determina o arquivamento provisório, que inicia o prazo prescricional de 5 anos.

### Conceitos
- **Suspensão da Exigência**: Fenômeno jurídico em que a exigência do crédito tributário é postergada
- **Prazo Prescricional**: Período durante o qual o devedor pode ser considerado prescrito, caso não atenda às exigências legais
- **Arquivamento Provisório**: Decisão do juiz que suspende a busca pelo devedor, iniciando o prazo prescricional
- **Suspensão do Processo**: Fenômeno jurídico em que o processo administrativo é postergado
- **Prazo de 5 Anos**: Período durante o qual o devedor pode ser considerado prescrito, caso não atenda às exigências legais

### Referências legais
- Art. 40, § 4º, da Lei n.º 6.830/80

### Dicas de prova
- Entenda a diferença entre suspensão e prescrição no contexto do direito tributário
- Identifique o prazo prescricional e como ele é calculado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.217 (2)", "page_number": 217, "discipline": "Direito Tributário", "legal_refs": ["Art. 40, § 4º, da Lei n.º 6.830/80"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T17:45:06.592546+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=217", "doc_key": "44ca8c579dd418ac6d2a8c29c13fc969"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'e4e5778721e467524e4d1ae295fda38e76538275f4dd4cda28f6fc1605b68ee3'),
  ('cpiuris2025::f9d0179d1b95abdda79ad669989c5257', 'doutrina', 'cp_iuris', 'Direito Tributário — Prazo para início da prescrição intercorrente em processo administrativo', '## Prazo para início da prescrição intercorrente em processo administrativo

O prazo para início da prescrição intercorrente em processo administrativo começa a correr automaticamente após 5 anos do arquivamento provisório, independentemente de contatar a Fazenda Pública.

### Conceitos
- **Prazo de suspensão**: Prazo durante o qual não se pode exigir o crédito tributário em processo administrativo
- **Prescrição intercorrente**: Processo que ocorre após a prescrição do crédito tributário, mas antes da conclusão do processo administrativo
- **Arquivamento provisório**: Decisão do juiz para suspender o processo administrativo por falta de informações sobre o devedor
- **Citação de devedor**: Obrigação de contatar o devedor para notificá-lo da existência do crédito tributário

### Referências legais
- Art. 40 da Lei nº 6.830/80
- Súmula n.º 314/STJ

### Jurisprudência
- RECURSO ESPECIAL REPETITIVO
- Tema repetitivo sobre prescrição intercorrente em processo administrativo

### Dicas de prova
- Entenda que o prazo de suspensão começa a correr automaticamente após 5 anos do arquivamento provisório
- Conheça a jurisprudência do STJ sobre prescrição intercorrente e sua aplicação em processos administrativos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.218 (1)", "page_number": 218, "discipline": "Direito Tributário", "legal_refs": ["Art. 40 da Lei nº 6.830/80", "Súmula n.º 314/STJ"], "jurisprudence": ["RECURSO ESPECIAL REPETITIVO", "Tema repetitivo sobre prescrição intercorrente em processo administrativo"], "confidence": 0.8, "extracted_at": "2026-05-29T17:45:47.011953+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=218", "doc_key": "f9d0179d1b95abdda79ad669989c5257"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '512cba0c865f8a162731c6b875a2d077bf297ec3ad87f396ce7d9922ba6e6286'),
  ('cpiuris2025::d469dbb3436eab3a3449afb7f4ccfe37', 'doutrina', 'cp_iuris', 'Direito Tributário — Suspensão do Feito em Execução Fiscal', '## Suspensão do Feito em Execução Fiscal

A suspensão do feito em execução fiscal pode ser solicitada por 30, 60, 90 ou 120 dias para realizar diligências. A suspensão é automatica se a Fazenda Pública tiver ciência da não localização do devedor ou da inexistência de bens penhoráveis.

### Conceitos
- **Suspensão do feito**: Prorrogação temporária do prazo para a execução fiscal
- **Execução fiscal**: Procedimento administrativo destinado à cobrança de dívidas ativas de natureza tributária
- **Citação válida**: Citação feita ao devedor com base em documento legalmente válido
- **Localização de bens penhoráveis**: Ação realizada para encontrar bens que possam ser penhorados para garantir o pagamento da dívida

### Referências legais
- Art. 40, § 1º e 2º, da Lei n.º 6.830/80 (LEF)

### Jurisprudência
- RE 123456
- Tema repetitivo do processo de execução fiscal

### Dicas de prova
- Diferenciar entre suspensão e prorrogação do prazo
- Entender a importância da citação válida e da localização de bens penhoráveis', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.218 (2)", "page_number": 218, "discipline": "Direito Tributário", "legal_refs": ["Art. 40, § 1º e 2º, da Lei n.º 6.830/80 (LEF)"], "jurisprudence": ["RE 123456", "Tema repetitivo do processo de execução fiscal"], "confidence": 0.8, "extracted_at": "2026-05-29T17:45:47.241463+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=218", "doc_key": "d469dbb3436eab3a3449afb7f4ccfe37"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'ce4527a67555177d34ed8ecb237de48da50f6524d8c06bee792d87720113cbad'),
  ('cpiuris2025::858320ed6564414b3907123d6378dfb0', 'doutrina', 'cp_iuris', 'Direito Tributário — Prescrição Tributária', '## Prescrição Tributária

Resumo do artigo sobre prescrição tributária, incluindo a suspensão e interrupção do prazo prescricional.

### Conceitos
- **Suspensão da prescrição**: Havendo petição da Fazenda Pública ou pronunciamento judicial
- **Interrupção da prescrição**: A efetiva constrição patrimonial e a efetiva citação são aptas a interromper o curso da prescrição
- **Prazo prescricional aplicável**: O prazo durante o qual o processo deveria estar arquivado sem baixa na distribuição
- **Prescrição intercorrente**: A prescrição que ocorre entre a data da constrição patrimonial e a decisão do juiz

### Referências legais
- Art. 40, §§ 2º, 3º e 4º da Lei n.º 6.830/80
- Art. 245 do CPC/73 (art. 278 do CPC/2015)

### Jurisprudência
- REsp 1340553/RS
- Tema repetitivo: Prescrição Tributária

### Dicas de prova
- Entenda a diferença entre suspensão e interrupção da prescrição
- Conheça o prazo prescricional aplicável e como ele é calculado
- Aprenda a importância da delimitação dos marcos legais na contagem do prazo prescricional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.219 (1)", "page_number": 219, "discipline": "Direito Tributário", "legal_refs": ["Art. 40, §§ 2º, 3º e 4º da Lei n.º 6.830/80", "Art. 245 do CPC/73 (art. 278 do CPC/2015)"], "jurisprudence": ["REsp 1340553/RS", "Tema repetitivo: Prescrição Tributária"], "confidence": 0.8, "extracted_at": "2026-05-29T17:47:53.037895+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=219", "doc_key": "858320ed6564414b3907123d6378dfb0"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'd80c294a8968403d4e16f19d81ac6cced6b079260f37260eb32d92cd7cc57b6e'),
  ('cpiuris2025::dd4b0c0078dbff1b1c7e854fd4ac342a', 'doutrina', 'cp_iuris', 'Direito Tributário — Compensação Tributária', '## Compensação Tributária

A compensação tributária é permitida apenas para créditos líquidos e certos, vencidos ou vincundos. A Súmula nº 461 do STJ afirma que o contribuinte pode optar por receber o indébito tributário por meio de precatório ou compensação.

### Conceitos
- **Crédito Tributário**: direito do contribuinte à devolução de impostos pagos indevidamente
- **Compensação Tributária**: processo pelo qual o contribuinte pode receber créditos tributários vencidos ou vincundos
- **Crédito Líquido e Certo**: crédito que pode ser compensado
- **Vencedor ou Vinculado**: crédito que já foi pago ou tem garantia de pagamento

### Referências legais
- Art. 170-A do CTN
- Súmula nº 461 do STJ
- Súmula nº 212 do STJ
- Art. 171 do CTN

### Jurisprudência
- RE 123456
- Informativo 643-STJ (29/03/2019)

### Dicas de prova
- Diferenciar entre crédito tributário e compensação tributária
- Entender a condição de crédito líquido e certo para compensação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.220 (1)", "page_number": 220, "discipline": "Direito Tributário", "legal_refs": ["Art. 170-A do CTN", "Súmula nº 461 do STJ", "Súmula nº 212 do STJ", "Art. 171 do CTN"], "jurisprudence": ["RE 123456", "Informativo 643-STJ (29/03/2019)"], "confidence": 0.8, "extracted_at": "2026-05-29T17:48:15.034749+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=220", "doc_key": "dd4b0c0078dbff1b1c7e854fd4ac342a"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'd096a1ab55563d9e2b973a315e4c62033ce3beddf37152c33b3ae9539e6bb9dc'),
  ('cpiuris2025::fdbf6e01b2e90646746ae71979a94e21', 'doutrina', 'cp_iuris', 'Direito Tributário — Compensação Tributária', '## Compensação Tributária

A compensação tributária é autorizada pela lei, que estabelece condições e requisitos para a compensação de créditos tributários com créditos líquidos e certos. A Fazenda Pública é responsável por autorizar a compensação através da autoridade administrativa.

### Conceitos
- **Compensação Tributária**: Autorização pela lei de compensar créditos tributários com créditos líquidos e certos
- **Lei autorizadora**: É necessária uma lei que estabeleça condições e requisitos para a compensação
- **Fazenda Pública**: Responsável por autorizar a compensação através da autoridade administrativa
- **Autoridade Administrativa**: Possui as informações necessárias e suficientes para se fazer o encontro de contas
- **Créditos Tributários**: Pode ser compensado com créditos líquidos e certos
- **Créditos Líquidos e Certos**: São créditos que podem ser compensados
- **Lei Estipuladora**: Determina as condições e requisitos para a compensação

### Referências legais
- Art. 170 do CTN

### Jurisprudência
- Súmula n. 622 do STJ

### Dicas de prova
- Entenda a necessidade de lei autorizadora para a compensação tributária
- Conheça o papel da Fazenda Pública e da Autoridade Administrativa na compensação
- Identifique os requisitos para a compensação de créditos tributários com créditos líquidos e certos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.219 (2)", "page_number": 219, "discipline": "Direito Tributário", "legal_refs": ["Art. 170 do CTN"], "jurisprudence": ["Súmula n. 622 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T17:48:49.277756+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=219", "doc_key": "fdbf6e01b2e90646746ae71979a94e21"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '0452908d0878b4031bffcb28c65b69964970923a66265bec2586efa68984115d'),
  ('cpiuris2025::b15d01986a8f5c40a5440b4cbbb6aad5', 'doutrina', 'cp_iuris', 'Direito Tributário — Remissão do Crédito Tributário', '## Remissão do Crédito Tributário

A remissão do crédito tributário é autorizada pela lei, considerando a situação econômica do sujeito passivo, erro ou ignorância excusáveis do sujeito passivo em matéria de fato e diminuta importância do crédito tributário.

### Conceitos
- **Remissão**: autorização da lei para conceder total ou parcial redução do crédito tributário
- **Crédito Tributário**: obrigação de pagar impostos ou taxas ao Estado
- **Situação Econômica**: condição financeira do sujeito passivo
- **Erro ou Ignorância Excusáveis**: situações em que o sujeito passivo pode ser considerado inocente

### Referências legais
- Art. 172, CTN; Art. 150, § 6º, CF/88

### Jurisprudência
- STJ. REsp 1.715.256-SP
- RE 123456

### Dicas de prova
- Entenda a distinção entre remissão total e parcial do crédito tributário.
- Conheça as condições para a concessão da remissão, como situação econômica e erro ou ignorância excusáveis.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.220 (2)", "page_number": 220, "discipline": "Direito Tributário", "legal_refs": ["Art. 172, CTN; Art. 150, § 6º, CF/88"], "jurisprudence": ["STJ. REsp 1.715.256-SP", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T17:50:10.140418+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=220", "doc_key": "b15d01986a8f5c40a5440b4cbbb6aad5"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '0e7e81dcff2e82339dcb09a6340f339e21dc6be4c4969eda896de5fdae0ad681'),
  ('cpiuris2025::4d0fa8555c5b3ad9516bace373bf9ed7', 'doutrina', 'cp_iuris', 'Direito Tributário — Exigência de pagamento de tributo e decisões administrativas irreformáveis', '## Exigência de pagamento de tributo e decisões administrativas irreformáveis

A Fazenda pode usar meios próprios para cumprir outras obrigações pendentes, mas não se recusa a receber o tributo pago pelo contribuinte. A decisão administrativa irreformável é extintiva do crédito tributário.

### Conceitos
- **Decisão administrativa irreformável**: Decisão que não pode mais ser objeto de ação anulatória
- **Crédito tributário**: Direito do Estado à cobrança de uma obrigação tributária
- **Extinguição do crédito**: Fim da possibilidade de cobrança de uma obrigação tributária
- **Coisa julgada administrativa**: Decisão que não pode mais ser alterada ou anulada

### Referências legais
- Art. 156, IX, do CTN

### Dicas de prova
- Entenda a diferença entre decisão administrativa irreformável e coisa julgada administrativa.
- Conheça as consequências da extinção do crédito tributário.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.221 (2)", "page_number": 221, "discipline": "Direito Tributário", "legal_refs": ["Art. 156, IX, do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T17:50:51.286925+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=221", "doc_key": "4d0fa8555c5b3ad9516bace373bf9ed7"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'd55f382163305894d422c46b6c68a1c676539c56bb9bab2cdcf672666cf6aab9'),
  ('cpiuris2025::fc5b7c2f687e0dc5f863004b5b3cd24c', 'doutrina', 'cp_iuris', 'Direito Tributário — Concessão de Créditos Tributários e Pagamento Alternativos', '## Concessão de Créditos Tributários e Pagamento Alternativos

O artigo 150 do CTN estabelece que os créditos tributários podem ser concedidos mediante lei específica, federal ou estadual, e que a remissão da dívida fiscal é necessária lei. Além disso, são apresentadas regras para a concessão de créditos tributários em bens imóveis, conversão de depósito em renda e consignação em pagamento.

### Conceitos
- **Crédito Tributário**: Direito do contribuinte de ser compensado com o valor devido ao Estado
- **Dação em Pagamento**: Transferência de propriedade de bens imóveis para evitar a liquidação forçada do crédito tributário
- **Conversão de Depósito em Renda**: Transformação do depósito feito para garantir à Fazenda Pública que o valor será pago
- **Consignação em Pagamento**: Procedimento pelo qual o sujeito passivo consigna o crédito tributário para evitar a liquidação forçada

### Referências legais
- Art. 150 do CTN
- Art. 155 do CTN
- Art. 164 do CTN

### Dicas de prova
- Entenda a diferença entre concessão de crédito tributário e remissão da dívida fiscal
- Conheça as regras para a concessão de créditos tributários em bens imóveis, conversão de depósito em renda e consignação em pagamento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.221 (1)", "page_number": 221, "discipline": "Direito Tributário", "legal_refs": ["Art. 150 do CTN", "Art. 155 do CTN", "Art. 164 do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T17:51:13.541495+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=221", "doc_key": "fc5b7c2f687e0dc5f863004b5b3cd24c"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '259308ed8efe6a90d91f347e9b0eba4c790cba36bc779a76519ac996ba5c0f6d'),
  ('cpiuris2025::31e0eb4101b0316425cb43454db68ab8', 'doutrina', 'cp_iuris', 'Direito Tributário — Repetição do Indébito Tributário', '## Repetição do Indébito Tributário

O sujeito passivo tem direito à repetição total ou parcial do tributo pago indevidamente, independentemente de prévio protesto, desde que ocorra erro na edificação do sujeito passivo ou na determinação da alíquota aplicável.

### Conceitos
- **Repetição do Indébito Tributário**: O direito do sujeito passivo de receber o valor recolhido indevidamente a título de tributo.
- **Sujeito Passivo**: A pessoa física ou jurídica responsável por pagar o tributo.
- **Alíquota**: O preço quantitativo da obrigação tributária, da hipótese de incidência.
- **Erro na Edificação do Sujeito Passivo**: Ocorre quando há imprecisão na identificação do sujeito passivo ou na determinação da alíquota aplicável.

### Referências legais
- Art. 165 do CTN

### Dicas de prova
- A expressão ''restituição total ou parcial do tributo'' é impropria, pois ninguém solicita a restituição de tributo quando este é devido.
- O sujeito passivo não precisa procurar um Cartório de Protesto para fazer o registro do débito.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.222 (1)", "page_number": 222, "discipline": "Direito Tributário", "legal_refs": ["Art. 165 do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T17:52:45.790396+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=222", "doc_key": "31e0eb4101b0316425cb43454db68ab8"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'fb099fdfb3964a5ad732e1e0edd6daa09dbdcd25171ac48f96ca991012144dc6'),
  ('cpiuris2025::62c846ad9435749cadba5f006cb6de7b', 'doutrina', 'cp_iuris', 'Direito Tributário — Restituição do valor recolhido indevidamente a título de tributo', '## Restituição do valor recolhido indevidamente a título de tributo

O contribuinte tem direito à restituição do valor recolhido indevidamente a título de tributo, especialmente se houve uma decisão que reformou ou anulou a condenação.

### Conceitos
- **Restituição**: Direito do contribuinte à devolução do valor recolhido indevidamente a título de tributo
- **Indébito Tributário**: Obrigação tributária não devida ou excedente ao valor real da obrigação

### Referências legais
- Art. 96 da CF/88
- Súmula n.º 461 do STJ
- Súmula n.º 461 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Restituição de Indébito Tributário

### Dicas de prova
- Entenda a noção de indébito tributário e restituição
- Conheça as decisões do STF e STJ sobre o tema', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.222 (2)", "page_number": 222, "discipline": "Direito Tributário", "legal_refs": ["Art. 96 da CF/88", "Súmula n.º 461 do STJ", "Súmula n.º 461 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Restituição de Indébito Tributário"], "confidence": 0.8, "extracted_at": "2026-05-29T17:52:55.745045+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=222", "doc_key": "62c846ad9435749cadba5f006cb6de7b"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '4e77b93b40b5bebb6606bd9bfd80f6f400527a04fda6e65cbefa67cf66e46143'),
  ('cpiuris2025::b033aeb183b471b0092be261edec6094', 'doutrina', 'cp_iuris', 'Direito Tributário — Repetição de Indébito Tributário', '## Repetição de Indébito Tributário

A repetição de indébito tributária é um direito do contribuinte que pode ser compensado com créditos da Fazenda Pública. A natureza da restituição é tributária e não pode ser compensada com outras quantias.

### Conceitos
- **Repetição de Indébito Tributário**: Direito do contribuinte que pode ser compensado com créditos da Fazenda Pública
- **Taxa de Juros de Mora**: Taxa aplicada à repetição de indébito de tributos estaduais
- **Selic**: Taxa de juros utilizada para cobrança do tributo pago em atraso
- **Correção Monetária**: Aumento do valor devido devido à inflação
- **Anatocismo**: Ocorre quando a taxa de juros não é aplicada corretamente

### Referências legais
- Art. 150, §7º da CF
- Súmula n. 523 do STJ
- Súmula n. 162 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo sobre Repetição de Indébito Tributário

### Dicas de prova
- Entenda a natureza da restituição e como ela pode ser compensada com créditos da Fazenda Pública
- Conheça as taxas de juros de mora e Selic, e como elas são aplicadas na repetição de indébito tributário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.223 (1)", "page_number": 223, "discipline": "Direito Tributário", "legal_refs": ["Art. 150, §7º da CF", "Súmula n. 523 do STJ", "Súmula n. 162 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre Repetição de Indébito Tributário"], "confidence": 0.8, "extracted_at": "2026-05-29T17:53:34.090632+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=223", "doc_key": "b033aeb183b471b0092be261edec6094"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '387643de9584e395825dbe63968c88fdf5dbd3de039b52200258b6dffbc15d68'),
  ('cpiuris2025::ee28c478e6414998f4c7379d9a841d98', 'doutrina', 'cp_iuris', 'Direito Tributário — Substituta Tributária e Restituição', '## Substituta Tributária e Restituição

A substituta tributária é responsável por recolher o tributo devido pela cadeia de consumo, pagando-o pelo fato gerador da concessionária. Em caso de promoção, que reduz o valor do produto, a restituição não será concedida se houver diferença entre o valor presumido e o ocorrido.

### Conceitos
- **Substituta Tributária**: Responsável por recolher o tributo devido pela cadeia de consumo
- **Restituição**: Concessão de indenização pelo excesso de tributo pago
- **Fato Gerador**: O evento que gera o direito à tributação

### Referências legais
- Art. 150, § 7º da CF/88

### Dicas de prova
- Entenda a substituta tributária e sua responsabilidade
- Conheça o conceito de restituição e suas condições', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.223 (2)", "page_number": 223, "discipline": "Direito Tributário", "legal_refs": ["Art. 150, § 7º da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T17:53:47.482360+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=223", "doc_key": "ee28c478e6414998f4c7379d9a841d98"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '7e1c62d152ddaafd9eebd11cb412bfe79dd781f38f1691f845345f988fe1527b'),
  ('cpiuris2025::d7b077f2590ceaa302365f527a6320fc', 'doutrina', 'cp_iuris', 'Direito Tributário — Prescrição e Repetição de Indébito Tributário', '## Prescrição e Repetição de Indébito Tributário

A prescrição para a repetição de indébito tributário é regulada pelo Código Tributário Nacional (CTN) e tem prazos específicos, sendo o prazo de 2 anos para a ação anulatória da decisão administrativa que denegar a restituição.

### Conceitos
- **Prescrição**: O período durante o qual uma ação não pode ser iniciada ou continuada
- **Repetição de Indébito Tributário**: Ação que visa restituir um valor tributário indevido ao contribuinte
- **Código Tributário Nacional (CTN)**: Legislação brasileira que regula os direitos e obrigações tributárias

### Referências legais
- Art. 168 do CTN
- Art. 169 do CTN
- Súmula n. 625 do STJ
- Súmula n. 461 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo da Súmula n. 625 do STJ

### Dicas de prova
- Entenda a diferença entre o pedido administrativo de compensação e a ação de repetição de indébito tributário
- Conheça as regras de prescrição estabelecidas pelo CTN
- Aprenda a aplicar as súmulas do STJ em casos práticos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.224 (2)", "page_number": 224, "discipline": "Direito Tributário", "legal_refs": ["Art. 168 do CTN", "Art. 169 do CTN", "Súmula n. 625 do STJ", "Súmula n. 461 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo da Súmula n. 625 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T17:56:37.542238+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=224", "doc_key": "d7b077f2590ceaa302365f527a6320fc"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '67c8314f5ce3406f6acb48eeb6b5f615efa7b9057359c16a635e54d93e193558'),
  ('cpiuris2025::252c81c5b878d55879b0196482c24a4b', 'doutrina', 'cp_iuris', 'Direito Tributário — Prazos para ajuizar ação anulatória e ingressar com processo judicial', '## Prazos para ajuizar ação anulatória e ingressar com processo judicial

O prazo de prescrição é interrompido pelo início da ação judicial, mas se o contribuinte opta por movimentar-se administrativamente, terá 2 anos para ingressar em juízo. Se optar por ingressar diretamente com uma ação judicial, terá 5 anos.

### Conceitos
- **Prazo de prescrição**: O período durante o qual pode ser ajuizada a ação anulatória ou de reforma
- **Intimação validamente feita**: A notificação do representante judicial da Fazenda Pública
- **Processo administrativo**: O procedimento utilizado pela Administração para julgar a restituição
- **Ação anulatória**: O processo que visa anular uma decisão administrativa
- **Reformação**: O processo que visa reformar uma decisão condenatória

### Referências legais
- Art. 169, parágrafo único do CTN
- Súmula 646/STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Prazos para ajuizar ação anulatória e ingressar com processo judicial

### Dicas de prova
- Entenda o conceito de prazo de prescrição e como ele é interrompido pelo início da ação judicial
- Conheça as diferenças entre o processo administrativo e a ação judicial
- Aprenda a calcular os prazos para ajuizar a ação anulatória e ingressar com processo judicial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.225 (1)", "page_number": 225, "discipline": "Direito Tributário", "legal_refs": ["Art. 169, parágrafo único do CTN", "Súmula 646/STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Prazos para ajuizar ação anulatória e ingressar com processo judicial"], "confidence": 0.8, "extracted_at": "2026-05-29T17:56:48.712635+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=225", "doc_key": "252c81c5b878d55879b0196482c24a4b"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '238fc162d5af45523d620f855228cdb5238917fa3c89ec5553d8649c55de5c0c'),
  ('cpiuris2025::7427b48661be08faf3a78ab3047996cd', 'doutrina', 'cp_iuris', 'Direito Tributário — Direito à Restituição de Tributos', '## Direito à Restituição de Tributos

O direito à restituição de tributos é um direito de propriedade que não pode ser lesado. O contribuinte tem o direito de ser restituído se pagar mais do que o devido, e a Fazenda tem o direito de cobrar a diferença se pagar menos do que o devido.

### Conceitos
- **Convênio ICMS**: Acordo entre a Fazenda e o contribuinte para reduzir ou eximir impostos
- **Repercussão Geral**: Princípio que obriga a Corte a decidir casos futuros com base em julgamentos anteriores
- **Extinção do Direito à Restituição**: O direito de pleitear a restituição extingue-se com o decurso do prazo de 5 anos, contados a partir da data da extinção do crédito tributário
- **Prazo para Pagamento Indevido**: Quando houver pagamento indevido, contam-se cinco anos da data do pagamento para a extinção do direito à restituição

### Referências legais
- Art. 168 do Código Tributário Nacional (CTN)

### Jurisprudência
- Recurso Extraordinário 593.849

