  ('cpiuris2025::8896e637f03b18f3396c33c16452c27a', 'doutrina', 'cp_iuris', 'Direito Tributário — Legitidade passiva na restituição do IR retido na fonte', '## Legitidade passiva na restituição do IR retido na fonte

A legitimidade passiva para figurar na demanda de restituição do IR retido na fonte é do Estado ou Município, conforme Súmula n. 447 do STJ.

### Conceitos
- **Legitidade passiva**: Direito de uma parte para propor ação contra outra
- **Restituição do IR retido na fonte**: Procedimento pelo qual o contribuinte pode recuperar o valor do imposto de renda retido na fonte

### Referências legais
- Art. 157, I, e 158, I, da CF/88
- Súmula n. 447 do STJ
- Súmula n. 523 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a Súmula n. 447 do STJ e sua aplicação prática
- Diferencie entre isenção e anistia no contexto do crédito tributário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.226", "page_number": 226, "discipline": "Direito Tributário", "legal_refs": ["Art. 157, I, e 158, I, da CF/88", "Súmula n. 447 do STJ", "Súmula n. 523 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-29T17:59:00.540514+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=226", "doc_key": "8896e637f03b18f3396c33c16452c27a"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '498f370bc073df9e9ca2f6807f972857de8e0b46444fe7fdfee4c85f96107cc8'),
  ('cpiuris2025::ce93880af12d6889a9fd4c6ef38cfd36', 'doutrina', 'cp_iuris', 'Direito Tributário — Extinção do Crédito Tributário', '## Extinção do Crédito Tributário

A extinção do crédito tributário depende da homologação, seja pela autoridade fazendária ou pelo decurso do tempo. A tese do art. 168 é que o prazo só dispara com a extinção do crédito tributário.

### Conceitos
- **Lançamento por Homologação**: O processo pelo qual o contribuinte declara e paga o valor do tributo, mas não há homologação da autoridade fazendária.
- **Homologação Tácita**: A ação da autoridade fazendária para confirmar a regularidade do pagamento do tributo.
- **Crédito Tributário**: O direito do Estado de receber o valor do tributo devido.
- **Extinção do Crédito Tributário**: A perda do direito do Estado de receber o valor do tributo devido.
- **Momento de Extinção**: O momento em que o crédito tributário é considerado extinto.
- **Recolhimento de Tributo**: A ação do contribuinte de pagar o valor do tributo.

### Referências legais
- Art. 168 da Lei Tributária
- Súmula 456/STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre homologação tácita e extinção do crédito tributário.
- Conheça a tese do art. 168 e como ela foi modificada pela interpretação do STJ.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.225 (2)", "page_number": 225, "discipline": "Direito Tributário", "legal_refs": ["Art. 168 da Lei Tributária", "Súmula 456/STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T17:59:45.022139+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=225", "doc_key": "ce93880af12d6889a9fd4c6ef38cfd36"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'edc446d79ce853b123b8dea1ee421dc084755518f2e9bb75878594d6328de6aa'),
  ('cpiuris2025::91892c1645dabd7c00c33a42f903b0e2', 'doutrina', 'cp_iuris', 'Direito Tributário — Isenção Tributária', '## Isenção Tributária

A isenção tributária é a dispensa legal de pagamento de tributo, prevista em lei e contrato. Pode ser concedida por prazo certo e condicionada ao cumprimento de requisitos pelo contribuinte.

### Conceitos
- **Isenção Tributária**: Dispensa legal de pagamento de tributo
- **Lei**: Especifica as condições e requisitos para a concessão da isenção
- **Contrato**: Impõe um ônus ao contribuinte e gera direito subjetivo
- **Direito Subjetivo**: Dereito do contribuinte de gozar da isenção no prazo determinado
- **Requisitos**: Condições e requisitos previstos em lei ou contrato para a concessão da isenção
- **Prazo Determinado**: Prazo estabelecido pela lei para a concessão da isenção
- **Condicionamento**: Requisitos e condições impostos ao contribuinte para gozar da isenção

### Referências legais
- Art. 176 do CTN
- Art. 177 do CTN
- Art. 178 do CTN
- Art. 179 do CTN

### Dicas de prova
- Entenda a diferença entre isenção onerosa e isenção não onerosa
- Conheça as condições e requisitos para a concessão da isenção
- Avalie o impacto do prazo determinado na concessão da isenção', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.227", "page_number": 227, "discipline": "Direito Tributário", "legal_refs": ["Art. 176 do CTN", "Art. 177 do CTN", "Art. 178 do CTN", "Art. 179 do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T18:00:02.583717+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=227", "doc_key": "91892c1645dabd7c00c33a42f903b0e2"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '3180c73df5d1d02749eb102aa69536e45c534dfe721d3c5b0ccfe722e2577239'),
  ('cpiuris2025::ea859e637ec95f0632a0a110424c1d23', 'doutrina', 'cp_iuris', 'Direito Tributário — Garantias e preferências do crédito tributário', '## Garantias e preferências do crédito tributário

O artigo 183 do CTN estabelece que as garantias atribuídas ao crédito tributário não excluem outras previstas em lei, e que a natureza das garantias não altera a natureza do crédito ou da obrigação tributária.

### Conceitos
- **Garantia**: instrumento que assegura determinados direitos
- **Habeas corpus**: garantia para assegurar a liberdade de locomoção
- **Crédito tributário**: direito do contribuinte à anulação ou redução do valor da obrigação tributária

### Referências legais
- Art. 183 do CTN

### Dicas de prova
- Entenda a diferença entre garantias e preferências no contexto do crédito tributário
- Conheça as hipóteses em que o juiz pode determinar a indisponibilidade de bens e direitos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.229 (1)", "page_number": 229, "discipline": "Direito Tributário", "legal_refs": ["Art. 183 do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T18:01:35.988599+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=229", "doc_key": "ea859e637ec95f0632a0a110424c1d23"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'e3c5058fe22398870e4358829fc540ae4a2d422c07f6ef1be8d657a0f206d5de'),
  ('cpiuris2025::fad265bf54aef7b09a026c4099d1623d', 'doutrina', 'cp_iuris', 'Direito Tributário — Indisponibilidade de Bens Imóveis', '## Indisponibilidade de Bens Imóveis

A indisponibilidade de bens imóveis é limitada ao valor total exigível e deve ser comunicada aos órgãos e entidades que promovem registros de transferência de bens, especialmente ao registro público de imóveis.

### Conceitos
- **Indisponibilidade**: Medida provisória que limita a disposição de bens para pagamento de tributos
- **Bens Imóveis**: Propriedade que não pode ser facilmente transferida ou alienada
- **Valor Total Exigível**: Quantidade total de tributos exigíveis

### Referências legais
- Art. 115 da Lei 9.532/1997

### Dicas de prova
- Entenda a diferença entre indisponibilidade e suspensão de direitos
- Conheça as partes que devem ser comunicadas sobre a indisponibilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.229 (2)", "page_number": 229, "discipline": "Direito Tributário", "legal_refs": ["Art. 115 da Lei 9.532/1997"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T18:01:47.727603+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=229", "doc_key": "fad265bf54aef7b09a026c4099d1623d"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'ad4facf922da88e07fdca6b038002c9f9e24f2b483a51c02fa46a6fc75e0e1a7'),
  ('cpiuris2025::9abad77d479c355d7aa726c8a7c9577c', 'doutrina', 'cp_iuris', 'Direito Tributário — Isonenção e Anistia', '## Isonenção e Anistia

A isenção simples é concedida pela Fazenda sem condicionamento do contribuinte, podendo ser revogada a qualquer tempo. A anistia abrange exclusivamente as infrações cometidas anteriormente à vigência da lei que a concede.

### Conceitos
- **Isonença**: Concessão de isenção pela Fazenda sem condicionamento do contribuinte
- **Anistia**: Concessão de anistia para infrações cometidas anteriormente à vigência da lei que a concede
- **Art. 177 do CTN**: Estabelece o caráter não extensivo da isenção, excluindo taxas e contribuições de melhoria e tributos instituídos posteriormente à sua concessão
- **Art. 180 do CTN**: Define a anistia como abrangente apenas as infrações cometidas anteriormente à vigência da lei que a concede, excluindo crimes e contravenções
- **Anistia em caráter geral**: Concessão de anistia para todas as infrações cometidas anteriormente à vigência da lei que a concede
- **Anistia limitada**: Concessão de anistia apenas para certas infrações ou regiões do território da entidade tributante

### Referências legais
- Art. 177 do CTN
- Art. 180 do CTN

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o caráter não extensivo da isenção e a limitação da anistia.
- Conheça as condições para a concessão de anistia em caráter geral e limitada.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.228", "page_number": 228, "discipline": "Direito Tributário", "legal_refs": ["Art. 177 do CTN", "Art. 180 do CTN"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T18:02:25.366870+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=228", "doc_key": "9abad77d479c355d7aa726c8a7c9577c"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'ff3b25d4b8525823cfc2ca48a2a993f3734227ad7c736717d1d16ea8305d51b9'),
  ('cpiuris2025::ed511376ff6f7a4aa76037ab05e45ac9', 'doutrina', 'cp_iuris', 'Direito Tributário — Participantes obrigados ao imposto de renda', '## Participantes obrigados ao imposto de renda

Os participantes obrigados ao imposto de renda são a União, os Estados, o Distrito Federal e os territórios, conjuntamente e pro-rata; e os Municípios, conjuntamente e pro-rata.

### Conceitos
- **Participantes obrigados**: União, Estados, DF e territórios
- **Conjunto e pro-rata**: Municípios e suas autarquias

### Referências legais
- Art. 29, parágrafo único da LEF
- Art. 187 do CTN

### Jurisprudência
- ADPF N. 357
- Súmula 563 do STF
- Súmula 497 do STJ

### Dicas de prova
- Entenda a distinção entre União e Estados
- Conheça as autarquias e suas relações com os participantes obrigados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.231", "page_number": 231, "discipline": "Direito Tributário", "legal_refs": ["Art. 29, parágrafo único da LEF", "Art. 187 do CTN"], "jurisprudence": ["ADPF N. 357", "Súmula 563 do STF", "Súmula 497 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T18:03:34.006379+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=231", "doc_key": "ed511376ff6f7a4aa76037ab05e45ac9"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '1b76dd2a8028d58816d6d4c8809285bede1b559243b2f55e66695309dae08fdd'),
  ('cpiuris2025::dad1878e39e6f27239de072b9ddd5a91', 'doutrina', 'cp_iuris', 'Direito Tributário — Preferências e Concurso de Preferença', '## Preferências e Concurso de Preferença

A Fazenda Pública tem prioridade de ser solvida, pois são receitas que custearão o Estado. O crédito tributário prefere a qualquer outro, exceto os créditos trabalhistas ou decorrentes de acidente do trabalho.

### Conceitos
- **Indisponibilidade de bens e direitos**: Pressupõe exaurimento das diligências na busca por bens penhoráveis
- **Art. 185-A do CTN**: Regula a indisponibilidade de bens e direitos
- **Crédito tributário**: Prefere a qualquer outro, seja qual for sua natureza ou tempo de constituição
- **Legislação do trabalho**: Exceção à preferência do crédito tributário
- **Falência**: Ordem de prioridade dos créditos
- **Concurso de preferências**: Não se aplica a cobrança judicial do crédito tributário

### Referências legais
- Art. 185-A do CTN
- Art. 186 do CTN

### Jurisprudência
- Súmula n. 560 do STJ

### Dicas de prova
- Distinção entre indisponibilidade de bens e direitos e exaurimento das diligências
- Ordem de prioridade dos créditos em falência
- Concurso de preferências somente se aplica a pessoas jurídicas de direito público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.230", "page_number": 230, "discipline": "Direito Tributário", "legal_refs": ["Art. 185-A do CTN", "Art. 186 do CTN"], "jurisprudence": ["Súmula n. 560 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T18:04:28.053571+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=230", "doc_key": "dad1878e39e6f27239de072b9ddd5a91"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '12b37a87d4684adf95e17ce7b1d00b553649f2abcc1c782a917c63681191974c'),
  ('cpiuris2025::bc6e577fe73c371e21366b60175a4825', 'doutrina', 'cp_iuris', 'Direito Tributário — Fiscalização Tributária', '## Fiscalização Tributária

A legislação tributária regula a competência e os poderes das autoridades administrativas em matéria de fiscalização e aplicação da legislação tributária. O contribuinte deve se sujeitar à fiscalização, cumprindo os deveres de colaboração previstos em obrigações acessórias.

### Conceitos
- **Fiscalização Tributária**: A aplicação da legislação tributária pelas autoridades administrativas
- **Competência e Poderes das Autoridades Administrativas**: Regulada pela legislação tributária em caráter geral ou específico
- **Legislação Tributária**: Normativa que estabelece os parâmetros básicos da aplicação da lei
- **Obrigações Acessórias**: Deveres de colaboração do contribuinte com as autoridades administrativas
- **Privacidade do Contribuinte**: Direito protegido pela legislação tributária

### Referências legais
- Art. 194 do CTN
- Art. 195 do CTN
- Súmula n.º 439 do STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a competência e os poderes das autoridades administrativas em matéria de fiscalização tributária
- Conheça as obrigações acessórias do contribuinte com as autoridades administrativas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.233", "page_number": 233, "discipline": "Direito Tributário", "legal_refs": ["Art. 194 do CTN", "Art. 195 do CTN", "Súmula n.º 439 do STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T18:05:24.482911+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=233", "doc_key": "bc6e577fe73c371e21366b60175a4825"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '53b1dd90c2114bf9d39f8e9d0c9f40981d5690f604a2d2a5442b8236dc04603a'),
  ('cpiuris2025::82d45ac0e1128665e2e75539424a2e6d', 'doutrina', 'cp_iuris', 'Direito Tributário — Constrição Oblíqua para Pagamento de Tributos e Sanções Políticas', '## Constrição Oblíqua para Pagamento de Tributos e Sanções Políticas

A constrição oblíqua é vedada, exceto na apreensão de documentário fiscal lícita, mas não após ingresso ilícito no domicílio. A fiscalização precisa ter um prazo certo com termos inicial e final bem delimitados.

### Conceitos
- **Constrição Oblíqua**: Procedimento que visa obter a prestação de uma obrigação sem o consentimento do devedor
- **Sanções Políticas**: Medidas adotadas pela Fazenda Pública para cobrar tributos, que podem incluir a constrição oblíqua
- **Apreensão de Documentário Fiscal**: Procedimento lícito que envolve a apreensão de documentos fiscais para comprovar o ilícito tributário
- **Domicílio**: Local onde a pessoa jurídica exerce suas atividades econômicas sem autorização
- **Fiscalização**: Procedimento realizado pela Fazenda Pública para cobrar tributos

### Referências legais
- Art. 196 do CTN
- Súmula 773 STJ

### Jurisprudência
- RE 123456
- Tema repetitivo da STF e STJ

### Dicas de prova
- Entenda a diferença entre constrição oblíqua e apreensão de documentário fiscal
- Conheça o conceito de domicílio e sua relação com a fiscalização tributária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.234", "page_number": 234, "discipline": "Direito Tributário", "legal_refs": ["Art. 196 do CTN", "Súmula 773 STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo da STF e STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T18:06:20.496286+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=234", "doc_key": "82d45ac0e1128665e2e75539424a2e6d"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'cf2037b4347dcadad20a46ea00034c23dd99a693af5b1e2016d83540db8f629a'),
  ('cpiuris2025::85596cdbf8d228091274d0f78f5fed51', 'doutrina', 'cp_iuris', 'Direito Tributário — Denúncia espontânea e sigilo tributário', '## Denúncia espontânea e sigilo tributário

A denúncia espontânea impede o contribuinte de exercer sua confissão, tornando-se responsável pelo que a Fazenda lhe cobrar. Além disso, o art. 198 do CTN protege o sigilo tributário, excetuando-se casos específicos.

### Conceitos
- **Denúncia espontânea**: Ação do contribuinte que reconhece seu débito tributário
- **Confissão**: Exercício da responsabilidade pelo débito tributário por parte do contribuinte
- **Sigilo tributário**: Proteção das informações sigilosas sobre a situação econômica ou financeira de um sujeito passivo

### Referências legais
- Art. 198 do CTN
- Súmula n. 555 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo sobre sigilo tributário

### Dicas de prova
- Entenda a noção de denúncia espontânea e sua implications
- Conheça as exceções ao art. 198 do CTN, especialmente os casos previstos em art. 199', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.235 (1)", "page_number": 235, "discipline": "Direito Tributário", "legal_refs": ["Art. 198 do CTN", "Súmula n. 555 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre sigilo tributário"], "confidence": 0.8, "extracted_at": "2026-05-29T18:06:47.625240+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=235", "doc_key": "85596cdbf8d228091274d0f78f5fed51"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'a4f2a383d0902c458e49eb17a9cc2c113062f0005f2fa0ace27582e6e78d7946'),
  ('cpiuris2025::b9f01de8781e8648750885308e5d2668', 'doutrina', 'cp_iuris', 'Direito Tributário — Colaboração entre administração pública e tributária', '## Colaboração entre administração pública e tributária

A administração pública colabora com a tributária para compartilhar bases de dados, enquanto o auditor fiscal tem acesso a informações privadas e deve manter sigilo.

### Conceitos
- **Colaboração**: Cooperação entre órgãos da administração pública e tributária
- **Sigilo funcional**: Dereito do auditor fiscal de manter a confidencialidade das informações privadas

### Referências legais
- Art. 325 do Código Penal

### Dicas de prova
- Pegar a colaboração entre administração pública e tributária
- Distinção entre sigilo funcional e confidencialidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.235 (2)", "page_number": 235, "discipline": "Direito Tributário", "legal_refs": ["Art. 325 do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T18:06:51.470221+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=235", "doc_key": "b9f01de8781e8648750885308e5d2668"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '811c585d8600358b0f37a30e90ee7c514b3e97366849de9f913da9e05f19fb7b'),
  ('cpiuris2025::9baeba690867bccc3d5a40cfff15eb20', 'doutrina', 'cp_iuris', 'Direito Tributário — Revelar fato de que tem ciência em razão do cargo e que deva permanecer em segredo, ou facilitar-lhe a revelação', '## Revelar fato de que tem ciência em razão do cargo e que deva permanecer em segredo, ou facilitar-lhe a revelação

Art. 325 - Pena para servidor público que revelar fato sigiloso ou facilitar sua revelação, entre seis meses e dois anos de detenção ou multa.

### Conceitos
- **Revelar fato**: divulgar informação sigilosa
- **Sigilo tributário**: obrigação do servidor público de manter a privacidade das informações
- **Multa**: penalidade para não cumprimento da obrigação
- **Detenção**: penalidade para não cumprimento da obrigação

### Referências legais
- Art. 325 do CTN

### Jurisprudência
- Súmula 398/STF

### Dicas de prova
- Distinção entre revelar fato e facilitar sua revelação
- Importância do dever de guarda do sigilo das informações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.236", "page_number": 236, "discipline": "Direito Tributário", "legal_refs": ["Art. 325 do CTN"], "jurisprudence": ["Súmula 398/STF"], "confidence": 0.8, "extracted_at": "2026-05-29T18:07:17.336619+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=236", "doc_key": "9baeba690867bccc3d5a40cfff15eb20"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'afa3a087e461afaff9517dbc9ae110a497b96d2ac1bac789c582bac0ebd98d7f'),
  ('cpiuris2025::a704ee1fb6e4a566671bee2c0f940b56', 'doutrina', 'cp_iuris', 'Direito Tributário — Certidão Negativa de Débito', '## Certidão Negativa de Débito

A certidão negativa de débito assegura que o contribuinte está quite com a Fazenda Pública no momento de sua expedição, mas não significa que ele esteja sem dever a longo prazo.

### Conceitos
- **Certidão Negativa de Débito**: Documento que assegura o contribuinte está quite com a Fazenda Pública no momento de sua expedição
- **Prazo de Validade**: Geralmente 30 dias
- **Dívida Ativa**: Situação em que o contribuinte é inscrito após ser lançado crédito tributário

### Referências legais
- Art. 135, § 4º da Lei nº 9.532/1997

### Jurisprudência
- RE 123456
- Súmula 434 do STF

### Dicas de prova
- Entenda a diferença entre certidão negativa e certidão de débito
- Conheça o prazo de validade da certidão negativa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.238 (2)", "page_number": 238, "discipline": "Direito Tributário", "legal_refs": ["Art. 135, § 4º da Lei nº 9.532/1997"], "jurisprudence": ["RE 123456", "Súmula 434 do STF"], "confidence": 0.8, "extracted_at": "2026-05-29T18:09:24.116513+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=238", "doc_key": "a704ee1fb6e4a566671bee2c0f940b56"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '7ca2812c0e04ec09348e37c1950e01103fd872bbf6ce367eb99db5251e064f13'),
  ('cpiuris2025::03e6f0016c69bad9bd1b8802bdfdbb14', 'doutrina', 'cp_iuris', 'Direito Tributário — Reconhecimento da Inexigibilidade Parcial de Crédito', '## Reconhecimento da Inexigibilidade Parcial de Crédito

O reconhecimento da inexigibilidade parcial de crédito não exige a emenda ou substituição do título para prosseguir a execução fiscal, desde que a quantia indevida possa ser abatida por cálculos aritméticos.

### Conceitos
- **Inexigibilidade Parcial de Crédito**: O direito do contribuinte de não pagar uma parte do crédito tributário
- **Execução Fiscal**: O processo pelo qual a Fazenda Pública busca obter a satisfação de um crédito tributário
- **Redirecionamento de Execução Fiscal**: A mudança do sujeito passivo da execução fiscal para outro responsável tributário

### Referências legais
- Art. 2º, § 3º, Lei de Execuções Fiscais
- Súmula n.º 392, STJ

### Jurisprudência
- RE 123456
- Redirecionamento de Execução Fiscal

### Dicas de prova
- Entenda a diferença entre redirecionamento e modificação do sujeito passivo
- Conheça o entendimento da Corte Especial do STJ sobre a Lei de Execuções Fiscais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.238 (1)", "page_number": 238, "discipline": "Direito Tributário", "legal_refs": ["Art. 2º, § 3º, Lei de Execuções Fiscais", "Súmula n.º 392, STJ"], "jurisprudence": ["RE 123456", "Redirecionamento de Execução Fiscal"], "confidence": 0.8, "extracted_at": "2026-05-29T18:09:56.578349+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=238", "doc_key": "03e6f0016c69bad9bd1b8802bdfdbb14"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'e081b958cffa6d120d2d7da666abb0464b1e96ca2b2b34af76741a7dfa4fffc0'),
  ('cpiuris2025::a361366337e9b46b203d2067ae92b71d', 'doutrina', 'cp_iuris', 'Direito Tributário — Autoridade Fiscal e Dívida Ativa', '## Autoridade Fiscal e Dívida Ativa

A autoridade fiscal pode solicitar força policial para cumprir suas funções, mas precisa de ordem judicial para invadir a propriedade. A dívida ativa é o crédito do Estado credor, regularmente inscrito na repartição administrativa competente.

### Conceitos
- **Dívida Ativa**: Crédito do Estado credor, regularmente inscrito na repartição administrativa competente
- **Crédito Tributário**: Crédito de tributos + multas + adicionais (juros e correção monetária)
- **Força Policial**: Auxílio da força pública federal, estadual ou municipal para cumprir funções

### Referências legais
- Art. 200 do CTN
- Art. 201 do CTN
- CF/88

### Jurisprudência
- RE 123456
- Súmula N STJ
- Tema repetitivo sobre Certidão de Dívida Ativa

### Dicas de prova
- Entenda a diferença entre força policial e ordem judicial para invadir propriedade
- Conheça as condições para a inscrição em dívida ativa e seus efeitos
- Aprenda sobre o crédito tributário e sua composição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.237", "page_number": 237, "discipline": "Direito Tributário", "legal_refs": ["Art. 200 do CTN", "Art. 201 do CTN", "CF/88"], "jurisprudence": ["RE 123456", "Súmula N STJ", "Tema repetitivo sobre Certidão de Dívida Ativa"], "confidence": 0.8, "extracted_at": "2026-05-29T18:10:03.680669+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=237", "doc_key": "a361366337e9b46b203d2067ae92b71d"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'edd2d1d167d191f3caf6acc4034333207275e57631ab55bf3dcc50ec8cf1f9f3'),
  ('cpiuris2025::da24ea21c924b602c1d695110060ef3a', 'doutrina', 'cp_iuris', 'Direito Tributário — Responsabilidade Tributária', '## Responsabilidade Tributária

A certidão negativa expedida com dolo ou fraude responsabiliza pessoalmente o funcionário que a expedir pelo crédito tributário e juros de mora.

### Conceitos
- **Dolo**: intenção de enganar ou prejudicar alguém
- **Fraude**: falta de veracidade ou honestidade em uma ação ou documento
- **Responsabilidade Tributária**: obrigação do contribuinte de pagar tributos e juros
- **Certidão Negativa**: documento que nega a existência de um crédito tributário

### Referências legais
- Art. 208 da Lei Tributária
- Parágrafo único do Art. 208

### Dicas de prova
- Entenda o conceito de dolo e fraude para responder à questão
- Lembre-se de que a responsabilidade tributária é pessoal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.239 (2)", "page_number": 239, "discipline": "Direito Tributário", "legal_refs": ["Art. 208 da Lei Tributária", "Parágrafo único do Art. 208"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T18:11:44.664666+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=239", "doc_key": "da24ea21c924b602c1d695110060ef3a"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'd46099af25238c74841981dfe42df9a9ac120eeae5a1b31d5304323010d394b8'),
  ('cpiuris2025::24c74cfd64860090d92c848890e5bbba', 'doutrina', 'cp_iuris', 'Direito Tributário — Prazo para a expedição de certidão negativa e positiva', '## Prazo para a expedição de certidão negativa e positiva

O prazo para a expedição da certidão negativa é de 10 dias, conforme art. 205, e o contribuinte não tem direito à certidão se não decorrer o prazo. A certidão positiva com efeito de negativa é expedida quando o crédito tributário está constituído ou a exigibilidade está suspensa.

### Conceitos
- **Certidão Negativa**: Atesta a quitação do tributo, mas não confirma a inexistência de crédito tributário
- **Certidão Positiva**: Atesta a existência de crédito tributário ou a suspensão da exigibilidade
- **Prazo para expedição**: 10 dias, conforme art. 205

### Referências legais
- Art. 205 do CTN
- Súmula n. 446 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo da certidão negativa e positiva

### Dicas de prova
- Entenda a diferença entre certidão negativa e positiva
- Conheça o prazo para expedição da certidão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.239 (1)", "page_number": 239, "discipline": "Direito Tributário", "legal_refs": ["Art. 205 do CTN", "Súmula n. 446 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo da certidão negativa e positiva"], "confidence": 0.8, "extracted_at": "2026-05-29T18:11:51.406257+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=239", "doc_key": "24c74cfd64860090d92c848890e5bbba"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '957034299eab42fdd3cc03df7d6d21e180531875dd1a328e18daea28049b1a92'),
  ('cpiuris2025::72d41d46bc224b42dfbf082fc12ec77f', 'doutrina', 'cp_iuris', 'Direito Tributário — Prazos e Decadência', '## Prazos e Decadência

Os prazos fixados pela lei são contínuos, excluindo-se o dia de início e incluindo-se o de vencimento. Os prazos do artigo acima são prescricionais, decadenciais e de vencimento.

### Conceitos
- **Prazo contínuo**: Prazo que começa no dia seguinte ao de início e termina no dia anterior ao de vencimento
- **Decadência**: Forma de extinção do crédito tributário
- **Prescrição**: Prazo dentro do qual o Estado deve agir para exigir o pagamento de um débito tributário

### Referências legais
- Art. 210 da Lei Tributária
- Art. 156, V, do CTN

### Dicas de prova
- Entenda a diferença entre prescrição e decadência
- Conheça as regras de contagem dos prazos tributários', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.240 (1)", "page_number": 240, "discipline": "Direito Tributário", "legal_refs": ["Art. 210 da Lei Tributária", "Art. 156, V, do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T18:12:11.112825+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=240", "doc_key": "72d41d46bc224b42dfbf082fc12ec77f"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '8599564e9317f296a886a0409d3f27ba9dfa71a3330d722e197d1bd7fd03053a'),
  ('cpiuris2025::b84375710d595eeadce80eebfd1aa919', 'doutrina', 'cp_iuris', 'Direito Tributário — Crédito Tributário e Pagamento de Tributos', '## Crédito Tributário e Pagamento de Tributos

Resumo sobre as regras de crédito tributário e pagamento de tributos, incluindo hipóteses de suspensão do crédito.

### Conceitos
- **Crédito Tributário**: direito ao pagamento de um tributo deferido pelo Estado
- **Pagamento de Tributos**: obrigação de pagar um tributo estabelecido pela lei
- **Suspensão do Crédito Tributário**: hipótese que impede o crédito tributário ser deferido

### Referências legais
- Art. 129, § 4º, Código Tributário Nacional

### Dicas de prova
- Entenda a diferença entre moratória, parcelamento e remissão.
- Conheça as hipóteses de suspensão do crédito tributário.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.240 (2)", "page_number": 240, "discipline": "Direito Tributário", "legal_refs": ["Art. 129, § 4º, Código Tributário Nacional"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T18:13:36.351633+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=240", "doc_key": "b84375710d595eeadce80eebfd1aa919"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '0ad1fc07138812a0c12cd53e84b9e98144588bc12eeaabb5ab2e1b0485276646'),
  ('cpiuris2025::16183b70767b77d0d640726323e6a5b6', 'doutrina', 'cp_iuris', 'Direito Tributário — Conceitos de prescrição, decadência e parcelamento', '## Conceitos de prescrição, decadência e parcelamento

O texto discute conceitos relacionados à prescrição, decadência e parcelamento em direito tributário.

### Conceitos
- **Prescrição**: Processo pelo qual o Estado perde o direito de exigir a satisfação de uma obrigação
- **Decadência**: O processo pelo qual o direito do Estado se transforma em direito do sujeito passivo
- **Parcelamento**: Divisão da dívida tributária em parcelas menores e mais acessíveis

### Referências legais
- Art. 109, § 3º, do Código Tributário Nacional

### Dicas de prova
- Entenda a diferença entre prescrição e decadência
- Conheça o conceito de parcelamento e como ele se relaciona com a fiscalização tributária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.241", "page_number": 241, "discipline": "Direito Tributário", "legal_refs": ["Art. 109, § 3º, do Código Tributário Nacional"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T18:13:48.336139+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=241", "doc_key": "16183b70767b77d0d640726323e6a5b6"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '23bf5d49fe9d2682bef5e4ee364fe6dc153bedf0aaa0e9f7e7ed2b7d0ca4e11a'),
  ('cpiuris2025::e2f0734050fd90c73275fd586a7b7cb8', 'doutrina', 'cp_iuris', 'Direito Tributário — Proteção à Intimidade Fiscal dos Contribuintes', '## Proteção à Intimidade Fiscal dos Contribuintes

As fazendas públicas não podem permutar informações de qualquer natureza entre si, sob pena de lesão ao dever de proteção à intimidade fiscal dos contribuintes.

### Conceitos
- **Proteção à Intimidade Fiscal**: Derecho que visa proteger a privacidade e a confidencialidade das informações fiscais dos contribuintes.
- **Permutação de Informações**: Ações de troca ou compartilhamento de informações entre as fazendas públicas

### Referências legais
- Art. 165 do CTN
- ...

### Jurisprudência
- Súmula n.º 446 do STJ
- Informativo nº 522 do STJ

### Dicas de prova
- Entenda a proteção à intimidade fiscal dos contribuintes e as consequências da permutação de informações.
- Conheça as regras sobre o crédito tributário e a decadência.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.242 (1)", "page_number": 242, "discipline": "Direito Tributário", "legal_refs": ["Art. 165 do CTN", "..."], "jurisprudence": ["Súmula n.º 446 do STJ", "Informativo nº 522 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T18:14:08.708129+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=242", "doc_key": "e2f0734050fd90c73275fd586a7b7cb8"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '421405ab2e8f9b4d3c9d2799cbe95843c598db03c80fd0a83313c4a0d0043125'),
  ('cpiuris2025::f70e917804a4a61725aef9b9b88ac20e', 'doutrina', 'cp_iuris', 'Direito Tributário — Suspensão da exigibilidade do crédito tributário', '## Suspensão da exigibilidade do crédito tributário

A suspensão do crédito tributário é permitida por meio de mecanismos específicos, como a moratória, o depósito integral, reclamações e recursos, medidas liminares em mandado de segurança.

### Conceitos
- **Moratória**: Mecanismo que suspende a exigibilidade do crédito tributário
- **Depósito integral**: O depósito do valor do crédito tributário suspende sua exigibilidade
- **Reclamações e recursos**: São mecanismos que permitem a revisão da decisão administrativa
- **Medidas liminares em mandado de segurança**: Mecanismo que suspende a exigibilidade do crédito tributário por meio de medida liminar

### Referências legais
- Art. 151 do CTN

### Dicas de prova
- Entenda a diferença entre moratória e depósito integral
- Conheça os mecanismos que permitem a revisão da decisão administrativa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.242 (2)", "page_number": 242, "discipline": "Direito Tributário", "legal_refs": ["Art. 151 do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T18:15:41.791298+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=242", "doc_key": "f70e917804a4a61725aef9b9b88ac20e"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'd6a72c9c93000c07c7e01e739879da8a073dc039b0695f76b47961754c4b9d5d'),
  ('cpiuris2025::142d99f6ac5ea053cdf8fae6cc645b55', 'doutrina', 'cp_iuris', 'Direito Tributário — Transação Tributária e Divulgação de Informações', '## Transação Tributária e Divulgação de Informações

Resumo do artigo 171 a 198 do CTN, relacionando transação tributária, divulgação de informações e assistência mútua entre as autoridades fiscais.

### Conceitos
- **Transação Tributária**: Acordo entre o sujeito ativo e passivo da obrigação tributária para determinar litígio e extinção de crédito tributário.
- **Divulgação de Informações**: Revelação de informações relativas a procedimentos fiscais, inscrições na Dívida Ativa da Fazenda Pública, parcelamento ou moratória, incentivos, renúncias, benefícios ou imunidades tributárias.
- **Assistência Mútua**: Cooperação entre as autoridades fiscais para a fiscalização dos tributos respectivos e permuta de informações.

### Referências legais
- Art. 171 do CTN
- Art. 196 do CTN
- Art. 198 do CTN
- Art. 199 do CTN

### Dicas de prova
- Entenda a diferença entre transação tributária e divulgação de informações.
- Conheça as condições para a assistência mútua entre as autoridades fiscais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.243", "page_number": 243, "discipline": "Direito Tributário", "legal_refs": ["Art. 171 do CTN", "Art. 196 do CTN", "Art. 198 do CTN", "Art. 199 do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T18:16:24.419282+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=243", "doc_key": "142d99f6ac5ea053cdf8fae6cc645b55"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '67cee923f48d76ad6bfe77dff0adc9e04a4190ca4378139cd9eb89d1a4c57f03'),
  ('cpiuris2025::457dade03eae9d8b607c8015f34c0417', 'doutrina', 'cp_iuris', 'Direito Tributário — Direito Tributário Penal e Direito Penal Tributário', '## Direito Tributário Penal e Direito Penal Tributário

O Direito Tributário Penal é o direito tributário propriamente dito, que impõe penalidades ao descumprimento de normas tributárias. É diferente do Direito Penal Tributário, que é a aplicação do Direito Penal às infrações administrativas.

### Conceitos
- **Delito**: crime relacionado ao Direito Penal
- **Infração**: falta administrativa
- **Direito Tributário Penal**: direito tributário que impõe penalidades ao descumprimento de normas tributárias
- **Direito Penal Tributário**: aplicação do Direito Penal às infrações administrativas
- **Obrigação Tributária Acessória**: obrigação principal que se torna obrigação principal ao descumprimento de uma norma penal
- **Responsabilidade Objetiva**: responsabilidade do contribuinte/responsável pela obrigação tributária acessória

### Referências legais
- Art. 112 do CTN

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre Delito e Infração
- Entender a diferença entre Direito Tributário Penal e Direito Penal Tributário
- Conhecer a responsabilidade objetiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.245", "page_number": 245, "discipline": "Direito Tributário", "legal_refs": ["Art. 112 do CTN"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T18:16:46.170725+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=245", "doc_key": "457dade03eae9d8b607c8015f34c0417"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '2880460ab3a84cca3909dd9df98b4cdc26bf430bfbc297d2172bf0702df23c70'),
  ('cpiuris2025::cf66f8628bae254e22ccb1a75ca246db', 'doutrina', 'cp_iuris', 'Direito Tributário — Denúncia Espontânea', '## Denúncia Espontânea

A denúncia espontânea é uma impropriedade terminológica, pois a denúncia está relacionada a terceiros. É um instituto que visa recompor o valor do tributo devido, oferecendo ao contribuinte mais uma chance para se colocar na legalidade.

### Conceitos
- **Denúncia Espontânea**: Instituto que visa recompor o valor do tributo devido
- **Confissão**: Termo mais apropriado para se referir à apresentação da denúncia
- **Juros de Mora**: Não exclui a multa
- **Multas**: Moratória: excluída; Punitiva: não aplicada

### Referências legais
- Art. 138 do CTN
- Súmula n.º 360 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo da Súmula n.º 360 do STJ

### Dicas de prova
- Pegar a diferença entre denúncia e confessão
- Entender que juros de mora não excluem a multa
- Conhecer as regras sobre multas (moratória e punitiva)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.246", "page_number": 246, "discipline": "Direito Tributário", "legal_refs": ["Art. 138 do CTN", "Súmula n.º 360 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo da Súmula n.º 360 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T18:18:10.385167+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=246", "doc_key": "cf66f8628bae254e22ccb1a75ca246db"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '99f3e39e43d077ec3507ac9e66f08778e4555702a55ac4985e3d2caff6278fc9'),
  ('cpiuris2025::398f3f58de26bc7053f9f8a4df149d79', 'doutrina', 'cp_iuris', 'Direito Tributário — Execução Fiscal', '## Execução Fiscal

Resumo sobre execução fiscal, incluindo petição inicial, presunção de certeza e liquidez, penhora e embargos.

### Conceitos
- **Petição inicial**: Documento que inicia o processo de execução fiscal
- **Presunção de certeza e liquidez**: Conceito jurídico que considera a regularidade da inscrição como base para a presunção de certeza e liquidez da dívida ativa
- **Penhora**: Procedimento pelo qual os bens do executado são confiscados para satisfação da dívida tributária
- **Embargos**: Reclamação apresentada pelo executado contra a penhora, dentro de um prazo determinado

### Referências legais
- Art. 6º da Lei n.º 6.830/1980
- Súmula n. 558 do STF

### Jurisprudência
- RE 123456

### Dicas de prova
- A ordem de penhora é dada em dinheiro primeiro, seguida por outros bens
- O executado deve oferecer embargos dentro de 30 dias após o depósito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.248 (1)", "page_number": 248, "discipline": "Direito Tributário", "legal_refs": ["Art. 6º da Lei n.º 6.830/1980", "Súmula n. 558 do STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T18:18:53.415327+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=248", "doc_key": "398f3f58de26bc7053f9f8a4df149d79"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '7bc8408020d62e72b64e28358d80112c9fd09b42ef695d99721d359e195b9317'),
  ('cpiuris2025::d4297c4bf21c8a2642ebd9e68e1ec572', 'doutrina', 'cp_iuris', 'Direito Tributário — Lei nº 6.830/80 (LEF) e sua aplicação nos processos de execução fiscal', '## Lei nº 6.830/80 (LEF) e sua aplicação nos processos de execução fiscal

A Lei nº 6.830/80 (LEF) é uma lei ordinária que dispõe sobre a cobrança judicial da Dívida Ativa da Fazenda Pública, estabelecendo requisitos para a inscrição de dívidas ativas no Registro de Dívida Ativa.

### Conceitos
- **Dívida Ativa**: aquela definida como tributária ou não tributária na Lei nº 4.320, de 17 de março de 1964
- **Lei Geral (União, Estados, Distrito Federal e Municípios)**: aplica-se aos entes que podem cobrar dívidas ativas tributárias e não tributárias
- **Termo de Inscrição de Dívida Ativa**: deve conter informações específicas sobre a dívida, como nome do devedor, valor originário da dívida, etc.

### Referências legais
- Art. 2º da Lei nº 6.830/80
- Código de Processo Civil de 2015

### Jurisprudência
- Súmulas do STJ - Execução Fiscal

### Dicas de prova
- Entenda a distinção entre Dívida Ativa tributária e não tributária
- Conheça os requisitos para a inscrição de dívidas ativas no Registro de Dívida Ativa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.247", "page_number": 247, "discipline": "Direito Tributário", "legal_refs": ["Art. 2º da Lei nº 6.830/80", "Código de Processo Civil de 2015"], "jurisprudence": ["Súmulas do STJ - Execução Fiscal"], "confidence": 0.8, "extracted_at": "2026-05-29T18:19:04.704634+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=247", "doc_key": "d4297c4bf21c8a2642ebd9e68e1ec572"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '607800575b0dcaffbbdbffdf262679c9651105d79da8083da4ab6402cb7caee8'),
  ('cpiuris2025::106f7204bec1c3b16ddf0c9ee79654d3', 'doutrina', 'cp_iuris', 'Direito Tributário — Reconvenção e compensação em processos tributários', '## Reconvenção e compensação em processos tributários

Não será admitida reconvenção ou compensação, exceto em casos de suspeição, incompetência ou impedimentos, que serão arguidas como matéria preliminar.

### Conceitos
- **Reconvenção**: Ação apresentada por um contribente contra o Estado por alegar que o tributo não foi devido
- **Compensação**: Procedimento que permite ao Estado cobrar mais de um crédito tributário de uma única pessoa

### Referências legais
- Art. 29 da Lei de Execução Fiscal

### Dicas de prova
- Entenda a diferença entre reconvenção e compensação
- Conheça as exceções que permitem a arguição de matéria preliminar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.248 (2)", "page_number": 248, "discipline": "Direito Tributário", "legal_refs": ["Art. 29 da Lei de Execução Fiscal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T18:19:12.751238+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=248", "doc_key": "106f7204bec1c3b16ddf0c9ee79654d3"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '13b10cba95274cb8da3d62a963afac51ef5fe9d5d18140df969270b8684e4744'),
  ('cpiuris2025::d7792dd41ae5619e35ad38285a1ed646', 'doutrina', 'cp_iuris', 'Direito Tributário — Aplicação da causa de suspensão aos créditos da natureza tributária', '## Aplicação da causa de suspensão aos créditos da natureza tributária

A aplicação da suspensão da prescrição aos créditos tributários está com repercussão geral e está pendente de julgamento no STF, aguardando o resultado do RE n. 636562.

### Conceitos
- **Prescrição**: Processo pelo qual a ação é extinta por falta de tempo
- **Decadência**: O processo pela qual a ação é extinta por falta de procedimento
- **Suspensão da prescrição**: Mudança temporária do prazo de prescrição para um novo período

### Referências legais
- Art. 40, § 3º da CF/88
- Súmula 390 do STF

### Jurisprudência
- RE 636562

### Dicas de prova
- Diferenciar entre prescrição e decadência
- Entender a importância da suspensão da prescrição nos créditos tributários', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.249 (2)", "page_number": 249, "discipline": "Direito Tributário", "legal_refs": ["Art. 40, § 3º da CF/88", "Súmula 390 do STF"], "jurisprudence": ["RE 636562"], "confidence": 0.8, "extracted_at": "2026-05-29T18:21:08.417769+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=249", "doc_key": "d7792dd41ae5619e35ad38285a1ed646"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'c93c5fb2bee94fa3dab5a3c66f16b43b5848637a6edcd6767b399fe53e311c39'),
  ('cpiuris2025::6c55efa62ab998a125aeddf56805bb55', 'doutrina', 'cp_iuris', 'Direito Tributário — Prescrição da Execução Fiscal', '## Prescrição da Execução Fiscal

Após o prazo de suspensão provisória, a prescrição começa a contar automaticamente e não requer declaração judicial. O STJ entende que após 5 anos, o juiz deve intimar a Fazenda Pública e declarar a prescrição se não apresentar elementos novos.

### Conceitos
- **Prescrição**: Fim da possibilidade de ação judicial
- **Execução Fiscal**: Procedimento administrativo para cobrança de tributos
- **Prazo Prescricional**: Período durante o qual a prescrição pode ocorrer

### Referências legais
- Art. 109, § 3º da Lei nº 9.532/1997
- Súmula 634 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Prescrição em Execução Fiscal

### Dicas de prova
- Entenda a diferença entre suspensão provisória e prescrição.
- Conheça o prazo prescricional e como ele é calculado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.250", "page_number": 250, "discipline": "Direito Tributário", "legal_refs": ["Art. 109, § 3º da Lei nº 9.532/1997", "Súmula 634 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Prescrição em Execução Fiscal"], "confidence": 0.8, "extracted_at": "2026-05-29T18:21:24.327310+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=250", "doc_key": "6c55efa62ab998a125aeddf56805bb55"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'e479a2a66959e9d02d5bb918d571800d8df3129f7350ee4d35ce259c51772194'),
  ('cpiuris2025::2e1c90767cc574eded52026627a913a6', 'doutrina', 'cp_iuris', 'Direito Tributário — Recurso em Execução Fiscal', '## Recurso em Execução Fiscal

O artigo 34 da Lei 6.830/80 estabelece que não cabe apelação em execuções de valor inferior a R$ 50,00, sendo os embargos infringentes e de declaração as únicas possibilidades. Além disso, o artigo 40 estabelece regras para a suspensão e prescrição da execução fiscal.

### Conceitos
- **Recurso em Execução Fiscal**: Processo que visa revisar uma decisão de execução fiscal
- **Embargos Infringentes**: Recurso que busca anular uma decisão de execução fiscal
- **Declaração**: Ação que busca confirmar uma decisão de execução fiscal
- **Suspensão da Execução Fiscal**: Mudança temporária do curso da execução fiscal para localizar o devedor ou os bens penhoráveis
- **Prescrição Intercorrente**: Fim do prazo para a execução fiscal após a suspensão
- **Arquivamento dos Autos**: Encerramento da execução fiscal sem localização do devedor ou bens penhoráveis
- **Reconhecimento de Prescrição**: Decisão do juiz que considera a prescrição intercorrente como extinta

### Referências legais
- Art. 34 da Lei 6.830/80

### Dicas de prova
- Entenda a diferença entre embargos infringentes e declaração
- Conheça as regras para a suspensão e prescrição da execução fiscal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.249 (1)", "page_number": 249, "discipline": "Direito Tributário", "legal_refs": ["Art. 34 da Lei 6.830/80"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T18:22:21.435277+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=249", "doc_key": "2e1c90767cc574eded52026627a913a6"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '97893770c3e3093ccc288a5a9825cb3458d75dc79ba7d17b86cabc2015e58e51'),
  ('cpiuris2025::c6d92217e1b63e1d080ade2a039a0d19', 'doutrina', 'cp_iuris', 'Direito Tributário — Imposto de Importação e Imposto de Exportação', '## Imposto de Importação e Imposto de Exportação

Descreve as alíquotas, lançamento do imposto de importação e tributação exclusiva.

### Conceitos
- **Alíquota específica**: Tarifa aplicada a uma quantidade de mercadoria utilizando uma unidade de medida que indique esta tarifa
- **Alíquota ad valorem**: Tarifa aplicada à base de cálculo que não leva em conta o tipo de mercadoria
- **Fato gerador**: Ocorrencia do fato gerador é a data do registro da declaração de importação
- **Tributação exclusiva**: Exceção ao princípio da anterioridade e da anterioridade nonagesimal, aplicada a certos impostos

### Referências legais
- Art. 23 do DL n. 37/66
- Art. 1º, inciso III, § 4o do Código Tributário Nacional

### Dicas de prova
- Entenda a diferença entre alíquota específica e ad valorem
- Conheça o momento da ocorrência do fato gerador para lançamento do imposto de importação
- Atribua-se a legislação vigente à época do registro da importação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.252", "page_number": 252, "discipline": "Direito Tributário", "legal_refs": ["Art. 23 do DL n. 37/66", "Art. 1º, inciso III, § 4o do Código Tributário Nacional"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T18:23:54.147703+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=252", "doc_key": "c6d92217e1b63e1d080ade2a039a0d19"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '4d21668a2768f211626145730a818b721e1f497643962cbad22194bc585958c2'),
  ('cpiuris2025::dc2ab607eaaf5c58e9e2a04c8e7f0d70', 'doutrina', 'cp_iuris', 'Direito Tributário — Imposto de Importação', '## Imposto de Importação

O Imposto de Importação incide sobre mercadoria estrangeira e tem como fato gerador sua entrada no Território Nacional. O contribuinte é o importador, destinatário de remessa postal internacional ou adquirente de mercadoria entrepostada.

### Conceitos
- **Contribuinte**: Pessoa que deve pagar o Imposto de Importação
- **Importador**: Pessoa que promove a entrada de mercadoria estrangeira no Território Nacional
- **Destinatário de remessa postal internacional**: Pessoa indicada pelo remetente para receber a mercadoria importada
- **Adquirente de mercadoria entrepostada**: Pessoa que compra mercadoria retida na alfândega
- **Transportador**: Pessoa responsável pela transportação de mercadoria procedente do exterior ou sob controle aduaneiro
- **Depositário**: Pessoa incumbida da custódia de mercadoria sob controle aduaneiro
- **Base de cálculo**: Valor utilizado para calcular o tributo devido

### Referências legais
- Art. 19 do CTN
- Art. 1º do DL n. 37/66
- Art. 31 do DL n. 37/66
- Art. 32 do DL n. 37/66

### Dicas de prova
- Entenda a definição de contribuinte e os responsáveis pelo Imposto de Importação
- Conheça as diferentes formas de entrada de mercadoria estrangeira no Território Nacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.251", "page_number": 251, "discipline": "Direito Tributário", "legal_refs": ["Art. 19 do CTN", "Art. 1º do DL n. 37/66", "Art. 31 do DL n. 37/66", "Art. 32 do DL n. 37/66"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T18:24:29.257526+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=251", "doc_key": "dc2ab607eaaf5c58e9e2a04c8e7f0d70"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'b4932703eaaa107b63c3c91fa24b82f6ba41f6576474a51c7059c50681f49fda'),
  ('cpiuris2025::683802613b4c1c00e52c4aaeef0dd457', 'doutrina', 'cp_iuris', 'Direito Tributário — Imposto de Exportação e Imposto de Renda', '## Imposto de Exportação e Imposto de Renda

O imposto de exportação é calculado com base na saída da mercadoria do território nacional, considerando o registro da exportação no SISCOMEX. Já o imposto de renda é calculado com base na aquisição de disponibilidade econômica ou jurídica de renda.

### Conceitos
- **Fato gerador**: O evento que gera a obrigação tributária
- **Contribuinte**: Pessoa física ou jurídica responsável pelo pagamento do imposto
- **Base de cálculo**: Valor utilizado para calcular o valor do imposto
- **Alíquota**: Taxa percentual aplicada à base de cálculo para calcular o valor do imposto
- **Sistema Integrado do Comércio Exterior (SISCOMEX)**: Sistema que registra as exportações e importações

### Referências legais
- Art. 24 da Lei Tributária
- Decreto-Lei n. 1.578/77
- DL n. 6.759/09
- Art. 43 do Código Tributário Nacional (CTN)

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre fato gerador e contribuinte
- Conheça as bases de cálculo e alíquotas do imposto de exportação
- Aprenda a aplicar o sistema SISCOMEX para calcular o imposto de exportação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.253", "page_number": 253, "discipline": "Direito Tributário", "legal_refs": ["Art. 24 da Lei Tributária", "Decreto-Lei n. 1.578/77", "DL n. 6.759/09", "Art. 43 do Código Tributário Nacional (CTN)"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T18:25:16.214159+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=253", "doc_key": "683802613b4c1c00e52c4aaeef0dd457"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'e1393e0ed16f6a7ee134768cb5b81de42b19fb4f6d7141d9ccdc312c3194ab33'),
  ('cpiuris2025::2cc3afc6506671425e6cd285a37588d0', 'doutrina', 'cp_iuris', 'Direito Tributário — Imposto de Renda e Disponibilidade Jurídica e Econômica', '## Imposto de Renda e Disponibilidade Jurídica e Econômica

O Imposto de Renda incide sobre o resultado das aplicações financeiras realizadas por cooperativas, mas não sobre a isenção do ganho de capital nas operações de alienação de imóvel. A disponibilidade jurídica é o direito de usufruir de renda ou provento, enquanto a disponibilidade econômica é qualquer fato que implique acréscimo patrimonial.

### Conceitos
- **Disponibilidade Jurídica**: Direito de usufruir de renda ou provento
- **Disponibilidade Econômica**: Acrescimo patrimonial, mesmo que irregular ou ilícito

### Referências legais
- Art. 39 da Lei n. 11.196/05
- Súmula n. 262 do STJ
- Súmula n. 125 do STJ

### Jurisprudência
- RE 123456
- Súmula n. 215 do STJ
- Súmula n. 215 do STJ

### Dicas de prova
- Entenda a diferença entre disponibilidade jurídica e econômica
- Conheça as regras de isenção do Imposto de Renda sobre o ganho de capital', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.254 (1)", "page_number": 254, "discipline": "Direito Tributário", "legal_refs": ["Art. 39 da Lei n. 11.196/05", "Súmula n. 262 do STJ", "Súmula n. 125 do STJ"], "jurisprudence": ["RE 123456", "Súmula n. 215 do STJ", "Súmula n. 215 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T18:26:17.868306+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=254", "doc_key": "2cc3afc6506671425e6cd285a37588d0"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '24b8552035c9cb5428e9044369cd2722cc8b55282580dbe13809163e5574e84d'),
  ('cpiuris2025::cee62d104ebba1c71ddf3ec983605572', 'doutrina', 'cp_iuris', 'Direito Tributário — Incidência de IR sobre valores percebidos a título de indenização por horas extraordinárias trabalhadas', '## Incidência de IR sobre valores percebidos a título de indenização por horas extraordinárias trabalhadas

A incidência de IR sobre valores percebidos a título de indenização por horas extraordinárias trabalhadas é permitida, pois a hora extra é considerada salário. No entanto, a Súmula n. 498 do STJ afirma que não incide Imposto de Renda sobre indenização por danos morais, pois é indenização e não acréscimo patrimonial.

### Conceitos
- **Imposto de Renda**: tributo federal sobre a renda das pessoas físicas
- **Indenização**: pagamento feito por uma parte para compensar um dano ou prejuízo sofrido
- **Acrescimo patrimonial**: valor adicionado ao patrimônio de uma pessoa
- **Súmula n. 498 do STJ**: decisão da Suprema Corte do Brasil que afirma que não incide IR sobre indenização por danos morais

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- Súmula n. 498 do STJ
- ...

### Dicas de prova
- Entenda a noção de acréscimo patrimonial e sua relação com o Imposto de Renda
- Conheça as exceções à incidência de IR, como indenização por danos morais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.254 (2)", "page_number": 254, "discipline": "Direito Tributário", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["Súmula n. 498 do STJ", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T18:27:04.449655+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=254", "doc_key": "cee62d104ebba1c71ddf3ec983605572"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'aa642a5ceb01a7416be8d507e80849cc82d9495653d131b1ef7046f4dcf96f24'),
  ('cpiuris2025::e6ba3a570b0f3ae47342d8eb4cc38532', 'doutrina', 'cp_iuris', 'Direito Tributário — Impostos Federais e IR', '## Impostos Federais e IR

O IR é um imposto federal que incide sobre a renda ou proventos, com base na capacidade contributiva, universalidade e progressividade. O contribuinte é o titular da disponibilidade jurídica ou econômica.

### Conceitos
- **Generalidade**: Todos estão sujeitos à tributação
- **Universalidade**: Toda renda será tributada, independentemente da denominação jurídica do rendimento ou provento
- **Progressividade**: Quanto maior for a capacidade contributiva, maior será a alíquota
- **Princípio da Anterioridade**: O IR deve observar o princípio da anterioridade, mas não o Princípio da Anterioridade Nonagesimal
- **Contribuinte**: O titular da disponibilidade jurídica ou econômica

### Referências legais
- Art. 44 do CTN
- Art. X da Lei Y

### Dicas de prova
- Diferenciar entre IR e outros impostos federais
- Entender a noção de capacidade contributiva e sua relação com a alíquota do IR
- Conhecer o princípio da anterioridade e suas exceções', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.255", "page_number": 255, "discipline": "Direito Tributário", "legal_refs": ["Art. 44 do CTN", "Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T18:27:53.409829+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=255", "doc_key": "e6ba3a570b0f3ae47342d8eb4cc38532"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '94ccb4a106f9fb04eca8ba9d3c15e2509968fe33e0d854f7e4d2e12419f9b78b'),
  ('cpiuris2025::81dc1cdd3eb3b27af6a668a36ff2dbc3', 'doutrina', 'cp_iuris', 'Direito Tributário — Isenção de Imposto de Renda', '## Isenção de Imposto de Renda

Súmulas do STF que estabelecem regras de isenção de imposto de renda para microempresas, indenizações de demissão voluntária e outras situações.

### Conceitos
- **Microempresa**: Empreendimento com capital social limitado
- **Isenção de Imposto de Renda**: Exceção do pagamento do imposto de renda
- **Indenização de Demissão Voluntária**: Pagamento feito pela empresa a funcionário que se demite
- **Cooperativa**: Empreendimento social com objetivo econômico

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- Súmula 184
- Súmula 215
- Súmula 262
- Súmula 386

### Dicas de prova
- Reconheça as regras de isenção de imposto de renda estabelecidas pelas súmulas do STF.
- Entenda a distinção entre microempresa e cooperativa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.256 (2)", "page_number": 256, "discipline": "Direito Tributário", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["Súmula 184", "Súmula 215", "Súmula 262", "Súmula 386"], "confidence": 0.8, "extracted_at": "2026-05-29T18:29:06.955804+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=256", "doc_key": "81dc1cdd3eb3b27af6a668a36ff2dbc3"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'bdcd5725a5cce3a11ce6be5bdc836264193ca1f167302c7d1791f06d3068706e'),
  ('cpiuris2025::4baf529fc57ce0a5868165e3c3317a82', 'doutrina', 'cp_iuris', 'Direito Tributário — Saída do Estabelecimento e Arrematação', '## Saída do Estabelecimento e Arrematação

Define quem é considerado industrializado e quando não pode haver nova cobrança de tributo na saída do estabelecimento do importador.

### Conceitos
- **Arrematação**: Levantamento de produtos apreendidos ou abandonados
- **Industrializado**: Produto submetido a operações que modifiquem sua natureza ou finalidade
- **IPI**: Imposto sobre o Produto Interno

### Referências legais
- Art. 46, parágrafo único, do CTN

### Dicas de prova
- Distinção entre saída do estabelecimento e arrematação
- Conhecimento de quando um produto é considerado industrializado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.257 (2)", "page_number": 257, "discipline": "Direito Tributário", "legal_refs": ["Art. 46, parágrafo único, do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T18:30:31.194585+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=257", "doc_key": "4baf529fc57ce0a5868165e3c3317a82"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '3026071e37d85aa95712eb500a50f84d1eae68db64d0ae477e7d844f17f623d8'),
  ('cpiuris2025::289a23d392e6d782f0e6c50cebdf2290', 'doutrina', 'cp_iuris', 'Direito Tributário — Súmulas do STF - Imposto de Renda', '## Súmulas do STF - Imposto de Renda

Resumo das súmulas relacionadas ao imposto de renda, destacando os principais pontos sobre a incidência e isenção do imposto.

### Conceitos
- **Súmula 447**: Os Estados e o Distrito Federal são partes legítimas na ação de restituição de imposto de renda retido na fonte proposta por seus servidores.
- **Súmula 463**: Incide imposto de renda sobre os valores percebidos a título de indenização por horas extraordinárias trabalhadas, ainda que decorrentes de acordo coletivo.
- **Súmula 498**: Não incide imposto de renda sobre a indenização por danos morais.
- **Súmula 556**: É indevida a incidência de imposto de renda sobre o valor da complementação de aposentadoria pago por entidade de previdência privada e em relação ao resgate de contribuições recolhidas para referidas entidades patrocinadoras.
- **Súmula 590**: Constitui acréscimo patrimonial a atrair a incidência do imposto de renda, em caso de liquidação de entidade de previdência privada, a quantia que couber a cada participante, por rateio do patrimônio.
- **Súmula 598**: É desnecessária a apresentação de laudo médico oficial para o reconhecimento judicial da isenção do imposto de renda, desde que o magistrado entenda suficientemente demonstrada a doença grave por outros meios de prova.
- **Súmula 627**: O contribuinte faz jus à concessão ou à manutenção da isenção do imposto de renda, não se lhe exigindo a demonstração da contemporaneidade dos sintomas da doença nem da recidiva da enfermidade.

### Referências legais
- Art. 6º, VII, b, da Lei n. 7.713/1988
- Lei n. 9.250/1995

### Jurisprudência
- RE 123456
- Tema repetitivo do STF

### Dicas de prova
- Entenda a noção de fato gerador e sua incidência no IPI
- Conheça as hipóteses de isenção do imposto de renda previstas nas súmulas do STF', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.257 (1)", "page_number": 257, "discipline": "Direito Tributário", "legal_refs": ["Art. 6º, VII, b, da Lei n. 7.713/1988", "Lei n. 9.250/1995"], "jurisprudence": ["RE 123456", "Tema repetitivo do STF"], "confidence": 0.8, "extracted_at": "2026-05-29T18:32:08.205133+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=257", "doc_key": "289a23d392e6d782f0e6c50cebdf2290"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'd91fecefb5afb9addb4568124d73cda9c3a511de28a708b7e973b14f5823cb25'),
  ('cpiuris2025::ef43cd95b053456f3d4131c8f8328a89', 'doutrina', 'cp_iuris', 'Direito Tributário — Contribuinte e responsáveis do IPI', '## Contribuinte e responsáveis do IPI

O contribuinte do IPI são o importador, industrial, comerciante que fornece ao importador ou ao industrial, arrematante em casos de bens apreendidos e levados à leilão. Os responsáveis pelo IPI são transportador, possuidor e estabelecimento de produtos cuja origem é desconhecida.

### Conceitos
- **Contribuinte**: Pessoa física ou jurídica que deve pagar o IPI
- **Responsável**: Pessoa física ou jurídica que paga o IPI em nome do contribuinte
- **Importador**: Pessoa física ou jurídica que importa produtos para o mercado brasileiro
- **Industrial**: Pessoa física ou jurídica que transforma produtos para produzir outros produtos
- **Comerciante**: Pessoa física ou jurídica que compra e vende produtos

### Referências legais
- Art. 51 do CTN

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a distinção entre contribuinte e responsável do IPI
- Conheça as situações em que o importador, industrial ou comerciante são considerados contribuintes do IPI', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.258", "page_number": 258, "discipline": "Direito Tributário", "legal_refs": ["Art. 51 do CTN"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-29T18:32:56.942817+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=258", "doc_key": "ef43cd95b053456f3d4131c8f8328a89"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '2f0545494c424db8db23ebafd29305304b8c41e2160803f1f8a0cc849f6fd59a'),
  ('cpiuris2025::05f2dded565479a312327572e72346ef', 'doutrina', 'cp_iuris', 'Direito Tributário — Aplicação da Lei Vigente no Imposto de Renda', '## Aplicação da Lei Vigente no Imposto de Renda

A Súmula n.º 584 do STF foi cancelada, mas ainda é aplicada a lei vigente no exercício financeiro em que deve ser apresentada a declaração.

### Conceitos
- **Súmula n.º 584**: Decisão do STF sobre a aplicação da lei vigente no imposto de renda
- **Lei vigente**: A lei que regula o imposto de renda em vigor no exercício financeiro
- **Aplicação retroativa**: A aplicação de uma lei mais nova a situações passadas
- **Isenção do imposto de renda**: Exceção do pagamento do imposto de renda em determinadas situações

### Referências legais
- Art. 96 da CF/88
- Súmula n.º 584 do STF

### Jurisprudência
- RE 159180
- RE 592.396
- Tema 168 do STF

### Dicas de prova
- Entenda a aplicação da lei vigente no imposto de renda e as implicações da cancelamento da Súmula n.º 584
- Diferencie entre aplicação retroativa e isenção do imposto de renda', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.256 (1)", "page_number": 256, "discipline": "Direito Tributário", "legal_refs": ["Art. 96 da CF/88", "Súmula n.º 584 do STF"], "jurisprudence": ["RE 159180", "RE 592.396", "Tema 168 do STF"], "confidence": 0.8, "extracted_at": "2026-05-29T18:33:46.707307+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=256", "doc_key": "05f2dded565479a312327572e72346ef"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '5438f5ce4935f2456915fe535291d54a63dc2d4dc2ea2357a13dafd03d831cf2'),
  ('cpiuris2025::2c968e12e06aae57c89197258061d95e', 'doutrina', 'cp_iuris', 'Direito Tributário — Lançamento do IPI e não cumulatividade', '## Lançamento do IPI e não cumulatividade

O lançamento do IPI é feito por homologação. O IPI está sujeito a não cumulatividade, com compensação do imposto devido em cada operação.

### Conceitos
- **IPI**: Imposto sobre o valor agregado (IVA) dos produtos industrializados
- **não cumulatividade**: A não acumulação de IPI em diferentes operações
- **compensação**: O desconto do IPI pago na operação anterior

### Referências legais
- Art. 15 da Lei nº 10.865/2004

### Jurisprudência
- Súmula 411/STJ
- Súmula 495/STJ

### Dicas de prova
- Entenda a não cumulatividade do IPI e como ela é aplicada em diferentes operações
- Conheça a compensação do IPI e sua importância na evitação de enriquecimento sem causa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.259 (1)", "page_number": 259, "discipline": "Direito Tributário", "legal_refs": ["Art. 15 da Lei nº 10.865/2004"], "jurisprudence": ["Súmula 411/STJ", "Súmula 495/STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T18:33:54.853453+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=259", "doc_key": "2c968e12e06aae57c89197258061d95e"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'aa4f730d107d1d058f836af4b10de3909b2b0848a897b929d3f62c1b83158391'),
  ('cpiuris2025::9201b234bf4fa2cceb3e6c88706ef4a6', 'doutrina', 'cp_iuris', 'Direito Tributário — Cessão de crédito de título judicial e compensação tributária', '## Cessão de crédito de título judicial e compensação tributária

Acessão de crédito de título judicial para compensar a cessionária em relação ao crédito-prêmio de IPI, com base na decisão do STJ (1ª Seção) no RE 1.390.228-RS/RS de 26/09/2018.

### Conceitos
- **Cessão de crédito**: Acesso ao crédito de título judicial para compensar a cessionária
- **Compensação tributária**: Oportunizar a compensação do crédito tributário pela cessionária
- **IPI**: Imposto sobre o Produto Interno Bruto
- **Selo do IPI**: Selos cobrados para controle de recolhimento de IPI

### Referências legais
- Art. 150, I, da CF/88
- Decreto-Lei n.º 1.437/75

### Jurisprudência
- STJ (1ª Seção) - RE 1.390.228-RS/RS de 26/09/2018

### Dicas de prova
- Distinção entre a cessão de crédito e a compensação tributária
- Reconhecimento do princípio da legalidade tributária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.259 (2)", "page_number": 259, "discipline": "Direito Tributário", "legal_refs": ["Art. 150, I, da CF/88", "Decreto-Lei n.º 1.437/75"], "jurisprudence": ["STJ (1ª Seção) - RE 1.390.228-RS/RS de 26/09/2018"], "confidence": 0.9, "extracted_at": "2026-05-29T18:34:15.441916+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=259", "doc_key": "9201b234bf4fa2cceb3e6c88706ef4a6"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'f62bc653a66af525cea9ca1097c0faec1c2d0415cb5b09b04bfd45fa536f698d'),
  ('cpiuris2025::cfed90aac321fd38227d420466f0fa8e', 'doutrina', 'cp_iuris', 'Direito Tributário — Operações de crédito e fato gerador', '## Operações de crédito e fato gerador

A operação de crédito envolve o empréstimo de dinheiro, com o fato gerador ocorrendo na entrega ou colocação à disposição do tomador.

### Conceitos
- **Fato gerador**: O evento que gera a obrigação tributária
- **Operações de crédito**: Emprestimo de dinheiro
- **Entrega ou colocação à disposição**: Ocorre quando o tomador recebe o empréstimo

### Referências legais
- Art. 29 da Lei nº 9.532/1997

### Dicas de prova
- Entenda a noção de fato gerador e como ele se relaciona com as operações de crédito
- Diferencie entre entrega e colocação à disposição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.260 (2)", "page_number": 260, "discipline": "Direito Tributário", "legal_refs": ["Art. 29 da Lei nº 9.532/1997"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T18:36:01.787698+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=260", "doc_key": "cfed90aac321fd38227d420466f0fa8e"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '278d8efb752918dfae870dfabc899fdd3e61bc73edee63e782df53cf0400278a'),
  ('cpiuris2025::4000d76ae8d9bca57f5a68f10af5f958', 'doutrina', 'cp_iuris', 'Direito Tributário — Ressarcimento de custos e demais encargos relativos ao selo especial', '## Ressarcimento de custos e demais encargos relativos ao selo especial

O ressarcimento de custos e demais encargos pelo fornecimento de selos de controle de IPI é inexigível, pois o tributo é da espécie Taxa de Poder de Polícia e há vício de forma na sua instituição.

### Conceitos
- **Fato gerador**: Elemento que gera a obrigação de pagar um imposto
- **Taxa de Poder de Polícia**: Tipo de tributo instituído por norma infralegal
- **Ressarcimento prévio**: Conceito utilizado para descrever o ressarcimento de custos e demais encargos

### Referências legais
- Art. 3º do Decreto-Lei nº 1.437/75
- STF. Plenário. RE 662113/PR, Rel. Min. Marco Aurélio, julgado em 12/2/2014

### Jurisprudência
- RE 662113/PR
- RE 596614/SP
- STJ. 1ª Seção. REsp 734.403-RS, Rel. Min. Napoleão Nunes Maia Filho, julgado em 14/11/2018

### Dicas de prova
- Entenda a distinção entre ressarcimento de custos e demais encargos e Taxa de Poder de Polícia
- Conheça o conceito de fato gerador e sua importância na tributação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.260 (1)", "page_number": 260, "discipline": "Direito Tributário", "legal_refs": ["Art. 3º do Decreto-Lei nº 1.437/75", "STF. Plenário. RE 662113/PR, Rel. Min. Marco Aurélio, julgado em 12/2/2014"], "jurisprudence": ["RE 662113/PR", "RE 596614/SP", "STJ. 1ª Seção. REsp 734.403-RS, Rel. Min. Napoleão Nunes Maia Filho, julgado em 14/11/2018"], "confidence": 0.8, "extracted_at": "2026-05-29T18:37:15.694523+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=260", "doc_key": "4000d76ae8d9bca57f5a68f10af5f958"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '9261f8763eb7e392d2afa66619d3ceaeaf67a3d6c91c5adc995ec7d579b41e5a'),
  ('cpiuris2025::ecac203588fb63bb998e9e2b5ceea511', 'doutrina', 'cp_iuris', 'Direito Tributário — Fato gerador e base de cálculo do IOF e ITR', '## Fato gerador e base de cálculo do IOF e ITR

O fato gerador do IOF ocorre quando o prêmio é recebido, enquanto para o ITR é a propriedade ou posse de um imóvel rural. A base de cálculo varia conforme operação (crédito, câmbio, seguro, títulos e valores mobiliários).

### Conceitos
- **Fato gerador**: O evento que gera a obrigação tributária
- **Base de cálculo**: O valor utilizado para calcular o valor do imposto
- **IOF**: Imposto sobre operações financeiras
- **ITR**: Imposto sobre a propriedade territorial rural
- **Princípio da anterioridade anual**: O imposto deve ser pago no ano em que foi gerado o fato gerador
- **Princípio da anterioridade nonagesimal**: O imposto deve ser pago no ano em que foi gerado o fato gerador, considerando 30 anos de antecedência
- **Princípio da legalidade**: O imposto deve estar previsto em lei

### Referências legais
- Art. 15 da Lei nº 11.196/2005
- Súmula 646 do STF

### Dicas de prova
- Pergunte sobre a base de cálculo do IOF e ITR
- Entenda o fato gerador das operações financeiras e rurais
- Conheça os princípios da anterioridade anual e nonagesimal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.261", "page_number": 261, "discipline": "Direito Tributário", "legal_refs": ["Art. 15 da Lei nº 11.196/2005", "Súmula 646 do STF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T18:37:41.975831+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=261", "doc_key": "ecac203588fb63bb998e9e2b5ceea511"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'b24421a9f5586906ec60315e4c15a21e0691b9ed5f641f23ff66e540be8e6626'),
  ('cpiuris2025::7a0a2f0d64ee09fa1aa7d22db9a93fc9', 'doutrina', 'cp_iuris', 'Direito Tributário — Imposto sobre a Renda Rural (ITR)', '## Imposto sobre a Renda Rural (ITR)

O ITR é cobrado sobre imóveis utilizados para atividade rural, com destinação agropecuária. A União transfere a capacidade tributária ativa e pode fiscalizar e cobrar o imposto se optar.

### Conceitos
- **Destinação do imóvel**: Importante para a incidência do ITR
- **Competência tributária**: Indelegável, transferida para a União em caso de fiscalização e cobrança
- **Base de cálculo**: Valor fundiário, valor da terra nua tributável
- **Progressividade**: Desestimular propriedades improdutivas

### Referências legais
- Art. 153, III, da CF/88
- Súmula n. 185 do Superior Tribunal de Justiça

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Destinação do imóvel é mais importante que a localização
- Competência tributária é indelegável, mas pode ser transferida para a União', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.262", "page_number": 262, "discipline": "Direito Tributário", "legal_refs": ["Art. 153, III, da CF/88", "Súmula n. 185 do Superior Tribunal de Justiça"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T18:38:18.055678+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=262", "doc_key": "7a0a2f0d64ee09fa1aa7d22db9a93fc9"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '70a8b12ecb511fd009aff58801200cee1570226d31859f0f87d2d1b5846b713a'),
  ('cpiuris2025::005c20376dde2079d57afc67df4afed4', 'doutrina', 'cp_iuris', 'Direito Tributário — Imposto sobre produção, extração, comercialização ou importação de bens e serviços prejudiciais à saúde ou ao meio ambiente', '## Imposto sobre produção, extração, comercialização ou importação de bens e serviços prejudiciais à saúde ou ao meio ambiente

A União pode criar um imposto sobre a produção, extração, comercialização ou importação de bens e serviços prejudiciais à saúde ou ao meio ambiente. A base é larga e inclui produtos com embalagens que indicam alto teor de açúcar, sódio, etc.

### Conceitos
- **Imposto sobre produção**: Imposto incidente sobre a produção, extração, comercialização ou importação de bens e serviços
- **Bem prejudicial à saúde ou ao meio ambiente**: Produto ou serviço que cause danos à saúde ou ao meio ambiente
- **Base larga**: A base do imposto é ampla, pois inclui uma variedade de produtos e serviços
- **Exceções**: O imposto não incide sobre exportações, operações com energia elétrica e telecomunicações

### Referências legais
- Art. 153, §6º, V da Constituição Federal

### Dicas de prova
- Entenda a definição de ''bem prejudicial à saúde ou ao meio ambiente''
- Conheça as exceções do imposto
- Aprenda a calcular a base do imposto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.263", "page_number": 263, "discipline": "Direito Tributário", "legal_refs": ["Art. 153, §6º, V da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T18:39:44.465118+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=263", "doc_key": "005c20376dde2079d57afc67df4afed4"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '69c41235f8a4d947e63412705d84c68622d14c4618b88417dc61c56fc0284615'),
  ('cpiuris2025::fb00c994564f613d82317eda793389cb', 'doutrina', 'cp_iuris', 'Direito Tributário — Imposto sobre a Transmissão Causa Mortis e Doação (ITCMD)', '## Imposto sobre a Transmissão Causa Mortis e Doação (ITCMD)

O ITCMD é um imposto plurifásico, real, proporcional e fiscal que incide sobre o valor agregado de transmissão de bens e direitos em razão de sucessão causa mortis ou doação.

### Conceitos
- **Plurifásico**: incide sobre o valor agregado
- **Real**: as condições da pessoa são irrelevantes
- **Proporcional**: não é progressivo
- **Fiscal**: tem como função principal a arrecadação
- **Sucessão Causa Mortis**: transmissão de bens e direitos em razão de falecimento
- **Doação**: transmissão de bens e direitos em razão de doação
- **Competência**: regras específicas estabelecidas pela Constituição
- **Valor Venal**: base de cálculo do ITCMD

### Referências legais
- Art. 136 da CF/88
- Súmula 446/STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: ITCMD

### Dicas de prova
- Entenda a natureza plurifásica do ITCMD
- Conheça as regras de competência estabelecidas pela Constituição
- Leia o valor venal como base de cálculo do ITCMD', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.265", "page_number": 265, "discipline": "Direito Tributário", "legal_refs": ["Art. 136 da CF/88", "Súmula 446/STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: ITCMD"], "confidence": 0.8, "extracted_at": "2026-05-29T18:40:25.026495+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=265", "doc_key": "fb00c994564f613d82317eda793389cb"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '5a173d557068c7d46123c1efd7864174184ae16d52e90ff799a4da32786acbd0'),
  ('cpiuris2025::ee252e9837fd8f77735e42d1f7ee32ea', 'doutrina', 'cp_iuris', 'Direito Tributário — Competência do ITCMD em relação a bens móveis, títulos e créditos', '## Competência do ITCMD em relação a bens móveis, títulos e créditos

A Reforma Tributária (EC 132/2023) alterou a competência do ITCMD para os casos de bens móveis, títulos e créditos, estabelecendo que compete ao Estado onde era domiciliado o de cujus ou tiver domicílio o doador, ou ao Distrito Federal.

### Conceitos
- **ITCMD**: Imposto sobre Transmissões Móveis de Bens Imóveis e Direitos Relativos
- **Reforma Tributária**: EC 132/2023
- **Competência tributária**: A responsabilidade do Estado em tributar os contribuintes
- **Progressividade**: Variação do valor do imposto de acordo com o valor do quinhão, legado ou doação

### Referências legais
- Art. 155, § 1º, II da Constituição Federal
- Art. 17 da Reforma Tributária (EC 132/2023)

### Jurisprudência
- RE 123456
- Tema repetitivo sobre competência tributária

### Dicas de prova
- Entenda a alteração na competência do ITCMD e como ela afeta os contribuintes
- Identifique o princípio de progressividade e seu aplicação no regime do ITCMD', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.266 (1)", "page_number": 266, "discipline": "Direito Tributário", "legal_refs": ["Art. 155, § 1º, II da Constituição Federal", "Art. 17 da Reforma Tributária (EC 132/2023)"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre competência tributária"], "confidence": 0.8, "extracted_at": "2026-05-29T18:40:49.388185+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=266", "doc_key": "ee252e9837fd8f77735e42d1f7ee32ea"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'ce5335fbbbd266f4d753d284c1ca904f3425fe71f075e8aa68fc96184c117c8e'),
  ('cpiuris2025::dcbf6b35ed19d7b43e3f10e8145870d3', 'doutrina', 'cp_iuris', 'Direito Tributário — Capacidade Contributiva e Exigências do ITCMD', '## Capacidade Contributiva e Exigências do ITCMD

A capacidade contributiva é influenciada pela grandeza tributável, com progressividade semelhante ao imposto de renda. Além disso, há uma imunidade constitucional para instituições sem fins lucrativos com finalidade pública e social, e uma alteração no regime do ITCMD regulamentada pelo artigo 16 da Reforma Tributária.

### Conceitos
- **Capacidade Contributiva**: Influência da grandeza tributável na determinação do tributo
- **Progressividade Tributária**: Tendência de aumentar o tributo com a grandeza tributável
- **Imunidade Constitucional**: Exigência para instituições sem fins lucrativos com finalidade pública e social
- **ITCMD**: Imposto sobre a Propriedade Imóvel do Distrito Federal e Território

### Referências legais
- Art. 155, §1º, VII da Constituição
- EC 132/2023

### Dicas de prova
- Entenda a relação entre capacidade contributiva e grandeza tributável
- Identifique as instituições que gozam de imunidade constitucional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.266 (2)", "page_number": 266, "discipline": "Direito Tributário", "legal_refs": ["Art. 155, §1º, VII da Constituição", "EC 132/2023"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T18:42:01.396795+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=266", "doc_key": "dcbf6b35ed19d7b43e3f10e8145870d3"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '92ce9609b895ca7d98b170d093afa60e51026752d35f3a3a74e251173fc47f5b'),
  ('cpiuris2025::34f5a9f5e327ba101a8bcd8c73da6a20', 'doutrina', 'cp_iuris', 'Direito Tributário — Fato Gerador do ICMS', '## Fato Gerador do ICMS

O fato gerador do ICMS é a circulação de mercadoria, sendo considerado também o valor da operação para fins de cálculo do imposto.

### Conceitos
- **Fato Gerador**: ocorrência que gera direito tributário
- **Circulação de Mercadoria**: movimentação de bens ou mercadorias
- **Operação**: atividade econômica realizada por uma pessoa jurídica

### Referências legais
- Art. 155 da Lei nº 10.365/2001 - ICMS

### Dicas de prova
- Distinção entre fato gerador e objeto passivo do ICMS
- Importância de considerar o valor da operação para cálculo do imposto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.267 (2)", "page_number": 267, "discipline": "Direito Tributário", "legal_refs": ["Art. 155 da Lei nº 10.365/2001 - ICMS"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T18:42:26.518740+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=267", "doc_key": "34f5a9f5e327ba101a8bcd8c73da6a20"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '0c32d739876004950e2d26b76d17a8b60901a56706754f8dcf74b7d7c54bf241'),
  ('cpiuris2025::b2cdcf08e5a41ae5c68f33ae3d1c2f1a', 'doutrina', 'cp_iuris', 'Direito Tributário — Possibilidade de instituição do ITCMD', '## Possibilidade de instituição do ITCMD

A possibilidade de instituição do Imposto sobre Transmissão Causa Mortis ou Doação de quaisquer Bens ou Direitos (ITCMD) é discutida, com base na Constituição Federal e no ADCT, especialmente em relação às hipóteses previstas no art. 155, § 1º, III, a e b.

### Conceitos
- **Competência legislativa plena**: O direito dos Estados-membros de instituir impostos sem a necessidade de lei complementar
- **Lei complementar**: Um tipo de lei que completa e desenvolve a Constituição Federal
- **ITCMD**: Imposto sobre Transmissão Causa Mortis ou Doação de quaisquer Bens ou Direitos
- **Art. 155, § 1º, III, a e b**: Hipóteses em que os Estados-membros podem instituir o ITCMD sem lei complementar
- **Reforma Tributária**: Mudanças no sistema tributário brasileiro, incluindo a regulamentação do ITCMD

### Referências legais
- Art. 155, § 1º, III, da Constituição Federal
- Art. 24, § 3º, da Constituição Federal
- Art. 34, § 3º e § 4º, do ADCT

### Jurisprudência
- Tese de repercussão geral: É vedado aos estados e ao Distrito Federal instituir o ITCMD nas hipóteses referidas no art. 155, § 1º, III, da Constituição Federal sem a edição da lei complementar exigida pelo referido dispositivo constitucional

### Dicas de prova
- Entenda a competência legislativa plena e a regulamentação do ITCMD
- Conheça as hipóteses em que os Estados-membros podem instituir o ITCMD sem lei complementar
- Avalie a Reforma Tributária e sua relação com o ITCMD', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.267 (1)", "page_number": 267, "discipline": "Direito Tributário", "legal_refs": ["Art. 155, § 1º, III, da Constituição Federal", "Art. 24, § 3º, da Constituição Federal", "Art. 34, § 3º e § 4º, do ADCT"], "jurisprudence": ["Tese de repercussão geral: É vedado aos estados e ao Distrito Federal instituir o ITCMD nas hipóteses referidas no art. 155, § 1º, III, da Constituição Federal sem a edição da lei complementar exigida pelo referido dispositivo constitucional"], "confidence": 0.8, "extracted_at": "2026-05-29T18:44:10.358808+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=267", "doc_key": "b2cdcf08e5a41ae5c68f33ae3d1c2f1a"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'e094eaed19a3a011480cfac64a8d1c25272aa110759c6586961aa6fa7a267518'),
  ('cpiuris2025::e303384f8ab2e50bd260b5bdd3dd6643', 'doutrina', 'cp_iuris', 'Direito Tributário — Incidência de ICMS', '## Incidência de ICMS

O Imposto sobre Circulação de Mercadorias e Serviços (ICMS) incide sobre a prestação do serviço de transporte interestadual, intermunicipal e de comunicação. Além disso, o ICMS também incide sobre a importação de bens ou mercadorias do exterior, bem como sobre os serviços prestados no exterior.

### Conceitos
- **ICMS**: Imposto sobre Circulação de Mercadorias e Serviços
- **Entrada de bens ou mercadorias importadas**: Mercadorias ou serviços prestados no exterior, seja por pessoa física ou jurídica
- **Domicílio do contribuinte**: O Estado competente para instituir e receber o ICMS é o onde estiver domiciliada a pessoa que comprou a mercadoria ou quem teve o serviço prestado no exterior
- **Arrendamento mercantil**: Operação de compra com opção de compra ao final, sem circulação jurídica

### Referências legais
- Art. 155, § 3º da CF/88
- Art. 155, § 2º, IX, da CF/88
- Súmula Vinculante n. 48 do STF
- Súmula n. 649 do Superior Tribunal de Justiça

### Jurisprudência
- RE 123456
- Tema repetitivo sobre ICMS e importação de bens ou mercadorias do exterior

### Dicas de prova
- Diferenciar entre ICMS e ISS
- Entender a regra de incidência de ICMS sobre a entrada de bens ou mercadorias importadas
- Conhecer as exceções à regra de incidência de ICMS, como o arrendamento mercantil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.268", "page_number": 268, "discipline": "Direito Tributário", "legal_refs": ["Art. 155, § 3º da CF/88", "Art. 155, § 2º, IX, da CF/88", "Súmula Vinculante n. 48 do STF", "Súmula n. 649 do Superior Tribunal de Justiça"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre ICMS e importação de bens ou mercadorias do exterior"], "confidence": 0.8, "extracted_at": "2026-05-29T18:45:17.652324+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=268", "doc_key": "e303384f8ab2e50bd260b5bdd3dd6643"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '224e37495aa1106041b8f0fc6535ba50bcce840e8b8c7fda329fdb2a1a56454f'),
  ('cpiuris2025::c41d41d8864e70f37a2f1e3a051a9d8c', 'doutrina', 'cp_iuris', 'Direito Tributário — Fato gerador do ICMS e contribuintes', '## Fato gerador do ICMS e contribuintes

O fato gerador do ICMS é a circulação de mercadoria ou prestação de serviço que caracterize intuito comercial. A base de cálculo é o preço de venda ou da prestação de serviço. Não inclui-se valores não relacionados à operação.

### Conceitos
- **Fato gerador do ICMS**: Circulação de mercadoria ou prestação de serviço que caracterize intuito comercial
- **Contribuinte do ICMS**: Pessoa física ou jurídica que realize circulação de mercadoria, prestação de serviço de transporte interestadual, etc., com habitualidade ou volume comercial
- **Base de cálculo do ICMS**: Quantificação da operação mercantil, sendo o preço de venda ou da prestação de serviço

### Referências legais
- Súmula n.º 163 do STJ
- Súmula Vinculante n.º 32 do STF
- Súmula n. 573 do STF
- Súmula n. 166 do STJ
- Súmula n. 334 do STJ
- Súmula n. 350 do STJ
- Súmula n. 391 do STJ
- Súmula n. 432 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo sobre ICMS

### Dicas de prova
- Entenda a distinção entre fato gerador e contribuinte do ICMS.
- Conheça as Súmulas do STJ e STF relevantes para o tema.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.269 (1)", "page_number": 269, "discipline": "Direito Tributário", "legal_refs": ["Súmula n.º 163 do STJ", "Súmula Vinculante n.º 32 do STF", "Súmula n. 573 do STF", "Súmula n. 166 do STJ", "Súmula n. 334 do STJ", "Súmula n. 350 do STJ", "Súmula n. 391 do STJ", "Súmula n. 432 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre ICMS"], "confidence": 0.8, "extracted_at": "2026-05-29T18:45:28.294286+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=269", "doc_key": "c41d41d8864e70f37a2f1e3a051a9d8c"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '0188485500f17eb7eead4045114252609bb782a81378a99e4ba8088166598bba'),
  ('cpiuris2025::8ce6129536bc1251805c9cbb6b5a9123', 'doutrina', 'cp_iuris', 'Direito Tributário — Operação Mercantil Tributária e Base de Cálculo do ICMS', '## Operação Mercantil Tributária e Base de Cálculo do ICMS

A operação mercantil tributária não deve incluir juros no cálculo do ICMS. A Constituição Federal de 1988 estabelece que o ICMS não considerará o imposto sobre produtos industrializados na sua base de cálculo, exceto em casos específicos.

### Conceitos
- **Operação Mercantil Tributária**: Relacionamento entre contribuintes e produto destinado à industrialização ou comercialização
- **Base de Cálculo do ICMS**: Montante do imposto sobre produtos industrializados
- **Inclusão do Valor do ICMS na Base de Cálculo**: Constitucionalidade da inclusão do valor do ICMS na sua própria base de cálculo

### Referências legais
- Art. 155, § 2º, XI, CF/88

### Jurisprudência
- RE 123456
- Súmula 555/STF

### Dicas de prova
- Distinguir entre operação mercantil tributária e base de cálculo do ICMS
- Entender a constitucionalidade da inclusão do valor do ICMS na sua própria base de cálculo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.269 (2)", "page_number": 269, "discipline": "Direito Tributário", "legal_refs": ["Art. 155, § 2º, XI, CF/88"], "jurisprudence": ["RE 123456", "Súmula 555/STF"], "confidence": 0.8, "extracted_at": "2026-05-29T18:46:29.676821+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=269", "doc_key": "8ce6129536bc1251805c9cbb6b5a9123"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '650839cb606add65dc443f678dfb8b7247fad865a3e6a168e22c9b4507513552'),
  ('cpiuris2025::12a43ceef28439846a0f86c4686409ba', 'doutrina', 'cp_iuris', 'Direito Tributário — Cálculo e Base do ICMS', '## Cálculo e Base do ICMS

O artigo discute a base de cálculo do ICMS, destacando que o valor do ICMS não é considerado na sua própria base de cálculo, mas sim como um tributo separado. Além disso, aborda a não cumulatividade e as regras constitucionais para as alíquotas do ICMS.

### Conceitos
- **Base de cálculo**: O valor que serve de base para o cálculo do ICMS
- **Não cumulatividade**: A característica do ICMS que permite a compensação de créditos em operações subsequentes
- **Alíquotas**: Taxas aplicadas ao ICMS, estabelecidas por meio de Resolução do Senado Federal ou Lei

### Referências legais
- Art. 13, § 1º, I, da LC N.º 87/96

### Jurisprudência
- Inf. 585
- Inf. 576
- Inf. 574

### Dicas de prova
- Entenda a diferença entre o ''cálculo por dentro'' e a aplicação de alíquotas mínimas
- Conheça as regras constitucionais para as alíquotas do ICMS', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.270 (1)", "page_number": 270, "discipline": "Direito Tributário", "legal_refs": ["Art. 13, § 1º, I, da LC N.º 87/96"], "jurisprudence": ["Inf. 585", "Inf. 576", "Inf. 574"], "confidence": 0.8, "extracted_at": "2026-05-29T18:47:40.354891+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=270", "doc_key": "12a43ceef28439846a0f86c4686409ba"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'bca1c3f489e00bca5b39f86a8c8f3a39149c56e0f66427892fdab0b6f90d22b5'),
  ('cpiuris2025::ca7f4d2dbf98a3c95610db15d18e9914', 'doutrina', 'cp_iuris', 'Direito Tributário — Alíquotas Máximas e Conflitos entre Estados', '## Alíquotas Máximas e Conflitos entre Estados

O Senado Federal pode estabelecer alíquotas máximas para resolver conflitos entre interesses dos Estados, com iniciativa da maioria absoluta e aprovação por 2/3 de seus membros. As alíquotas internas não podem ser inferiores às interestaduais, salvo deliberação em contrário dos Estados e DF.

### Conceitos
- **Alíquota máxima**: Taxa máxima estabelecida pelo Senado Federal para resolver conflitos entre interesses dos Estados
- **Conflito de interesse**: Situação em que os interesses de diferentes Estados entram em conflito
- **Alíquota interna**: Taxa aplicada por um Estado sobre uma operação ou prestação
- **Alíquota interestadual**: Taxa aplicada por outro Estado sobre a mesma operação ou prestação, em caso de circulação interestadual

### Referências legais
- Art. 97 da CF/88

### Dicas de prova
- Entenda a diferença entre alíquota máxima e alíquota interna
- Conheça as regras para a circulação interestadual de mercadorias e prestações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.270 (2)", "page_number": 270, "discipline": "Direito Tributário", "legal_refs": ["Art. 97 da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T18:47:47.302935+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=270", "doc_key": "ca7f4d2dbf98a3c95610db15d18e9914"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '77e3e0b59ceef1e6ee3ee38709779078a2ee49c3bb4e45713fbb4521f5be98f6'),
  ('cpiuris2025::f3cebb60dfff6928d9e731488127e91a', 'doutrina', 'cp_iuris', 'Direito Tributário — Alíquota Interna e Interestadual do ICMS', '## Alíquota Interna e Interestadual do ICMS

O Estado de destino tem direito à diferença entre a alíquota interna e a alíquota interestadual. A alíquota máxima é fixada pela maioria absoluta, enquanto a alíquota mínima é fixada por iniciativa de 1/3 dos membros e aprovação por maioria absoluta.

### Conceitos
- **Alíquota Interna**: A alíquota aplicada ao produto dentro do Estado
- **Alíquota Interestadual**: A alíquota aplicada ao produto fora do Estado
- **ICMS**: Imposto sobre a Valorização dos Bens e Serviços
- **Seletividade**: O ICMS pode ser seletivo em função da essencialidade das mercadorias e dos serviços

### Referências legais
- Art. 155, § 3º, da CF/88
- Resolução n. 22 do Senado

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre alíquota interna e interestadual
- Entender a seletividade do ICMS', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.271", "page_number": 271, "discipline": "Direito Tributário", "legal_refs": ["Art. 155, § 3º, da CF/88", "Resolução n. 22 do Senado"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T18:48:02.244506+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=271", "doc_key": "f3cebb60dfff6928d9e731488127e91a"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '44d200a7bc1cf3add4c451477a96a2622e9fbf5fcd4b73ee223e944041cd0c77'),
  ('cpiuris2025::124ea136254c56f2276d42f133b2564b', 'doutrina', 'cp_iuris', 'Direito Tributário — Substituição tributária progressiva', '## Substituição tributária progressiva

A substituição tributária progressiva é uma técnica de arrecadação em que o tributo é recolhido antes do fato gerador, com a garantia de imediata e preferencial restituição da quantia paga caso não ocorra o fato gerador.

### Conceitos
- **Substituição tributária progressiva**: Técnica de arrecadação em que o tributo é recolhido antes do fato gerador
- **Fato gerador**: O evento ou situação que gera a obrigação tributária
- **Responsável pelo pagamento**: A pessoa jurídica ou física que assume a obrigação de pagar o imposto ou contribuição

### Referências legais
- Art. 150, § 7º, da CF/88

### Dicas de prova
- Entenda a diferença entre substituição tributária progressiva e subsequente
- Conheça o artigo 150, § 7º, da Constituição Federal de 1988', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.272 (2)", "page_number": 272, "discipline": "Direito Tributário", "legal_refs": ["Art. 150, § 7º, da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T18:50:08.956981+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=272", "doc_key": "124ea136254c56f2276d42f133b2564b"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '7b5d2aebf80e8c6fcebb74ed7bf980b2ef4c971286dd9a719723709090feb758'),
  ('cpiuris2025::9f5fd519cccf935f79a3db494cb8d0c1', 'doutrina', 'cp_iuris', 'Direito Tributário — Substituição Tributária', '## Substituição Tributária

A substituição tributária é um regime que permite ao contribuinte pagar o imposto sobre todo o valor da cadeia produtiva, em vez de apenas sobre o valor da operação ou prestação. O valor do imposto é calculado com base no regime de valor agregado estabelecido na LC n. 87/96.

### Conceitos
- **Substituição Tributária**: Regime que permite ao contribuinte pagar o imposto sobre todo o valor da cadeia produtiva
- **Valor Agregado**: Conceito utilizado para calcular o imposto, considerando o preço de venda e a margem de lucro
- **LC n. 87/96**: Lei que estabelece o regime de valor agregado para fins de substituição tributária
- **Cláusula Segunda do Convênio 76/94**: Regra que exige a utilização do Preço Máximo de venda ao Consumidor (PCM) como base para o cálculo do imposto

### Referências legais
- Art. 8º da LC n. 87/96
- Art. § 2º da LC n. 87/96
- Cláusula Segunda do Convênio 76/94

### Dicas de prova
- Entenda o conceito de substituição tributária e como ela é calculada com base no regime de valor agregado.
- Conheça a importância da Cláusula Segunda do Convênio 76/94 e como ela afeta a utilização do PCM como base para o cálculo do imposto.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.273 (1)", "page_number": 273, "discipline": "Direito Tributário", "legal_refs": ["Art. 8º da LC n. 87/96", "Art. § 2º da LC n. 87/96", "Cláusula Segunda do Convênio 76/94"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T18:51:07.048113+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=273", "doc_key": "9f5fd519cccf935f79a3db494cb8d0c1"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '0d062c90b6139ead4e86c1a97ec281967dd3220027a08584a3435bd4d64cfa24'),
  ('cpiuris2025::0886be012ff8be335f4eef6859847b56', 'doutrina', 'cp_iuris', 'Direito Tributário — Compensação dos Estados por conta das desonerações de ICMS sobre as exportações', '## Compensação dos Estados por conta das desonerações de ICMS sobre as exportações

A União deve transferir recursos aos Estados como compensação pelas desonerações de ICMS sobre as exportações. A regulamentação da matéria está prevista no art. 91 do ADCT, mas não foi editada uma lei complementar até o momento.

### Conceitos
- **Art. 91 do ADCT**: prevê os critérios para compensar os Estados por conta das desonerações de ICMS sobre as exportações
- **LC n. 87/96**: estabelece os critérios para a compensação dos Estados, que devem ser adotados até a edição da nova lei complementar
- **Anexo da LC n. 87/96**: contém os critérios estabelecidos pela LC n. 87/96 para a compensação dos Estados
- **CLT n. 115/02**: regulamenta a matéria da compensação dos Estados por conta das desonerações de ICMS sobre as exportações, até a edição da nova lei complementar

### Referências legais
- Art. 91 do ADCT
- LC n. 87/96
- CLT n. 115/02
- CF/88, art. 155, § 2º, XII, ''g''

### Jurisprudência
- RE 123456
- ADI 849

### Dicas de prova
- Entenda a importância da regulamentação da compensação dos Estados por conta das desonerações de ICMS sobre as exportações.
- Conheça os critérios estabelecidos pela LC n. 87/96 e como eles devem ser adotados até a edição da nova lei complementar.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.272 (1)", "page_number": 272, "discipline": "Direito Tributário", "legal_refs": ["Art. 91 do ADCT", "LC n. 87/96", "CLT n. 115/02", "CF/88, art. 155, § 2º, XII, ''g''"], "jurisprudence": ["RE 123456", "ADI 849"], "confidence": 0.8, "extracted_at": "2026-05-29T18:51:25.958546+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=272", "doc_key": "0886be012ff8be335f4eef6859847b56"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '76fefd17d864671797c69faf36e56cf3ae5586980b190c79e4d0870607e0a95a'),
  ('cpiuris2025::90c245197907534770f16f801ec46c22', 'doutrina', 'cp_iuris', 'Direito Tributário — Substituição Tributária e Base de Cálculo do Imposto', '## Substituição Tributária e Base de Cálculo do Imposto

A substituição tributária envolve a fixação da base de cálculo do imposto com base no preço máximo ao consumidor (PMC) sugerido pelo fabricante. No entanto, em determinadas hipóteses, como a venda de medicamentos exclusivamente para uso hospitalar, o PMC não se aplica.

### Conceitos
- **Substituição Tributária**: mecanismo que permite reduzir ou eximir a incidência do imposto sobre determinados produtos ou serviços
- **Base de Cálculo**: valor utilizado para calcular o valor do imposto
- **Preço Máximo ao Consumidor (PMC)**: preço sugerido pelo fabricante para a venda ao público, considerado como base de cálculo em substituição tributária

### Referências legais
- Art. 155 da Lei 10.865/2004
- Súmula 646 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Substituição Tributária e Base de Cálculo

### Dicas de prova
- Entenda a diferença entre substituição tributária e base de cálculo
- Conheça o conceito de Preço Máximo ao Consumidor (PMC) e sua aplicabilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.273 (2)", "page_number": 273, "discipline": "Direito Tributário", "legal_refs": ["Art. 155 da Lei 10.865/2004", "Súmula 646 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Substituição Tributária e Base de Cálculo"], "confidence": 0.8, "extracted_at": "2026-05-29T18:52:35.480527+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=273", "doc_key": "90c245197907534770f16f801ec46c22"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '93ce73f0404f3b4a1deb0b8e559637094cc15d473893e3247397a9cbd055409a'),
  ('cpiuris2025::4ea01bbc004ee893af703c7fedccbc25', 'doutrina', 'cp_iuris', 'Direito Tributário — Diferimento do recolhimento do valor devido a título de ICMS', '## Diferimento do recolhimento do valor devido a título de ICMS

A jurisprudência permite que o legislador estadual preveja diferimento do recolhimento do valor devido a título de ICMS, sem necessidade de prévia celebração de convênio, desde que não implique redução ou dispensa do valor devido.

### Conceitos
- **Diferimento**: retardamento do recolhimento do valor devido a título de ICMS
- **Convênio**: acordo entre o legislador estadual e a entidade tributária
- **ICMS**: Imposto sobre a Renda Municipal

### Referências legais
- Art. X da Lei Y
- ...

### Jurisprudência
- RE 123456
- Súmula 20 STF
- Súmula 49 STF
- Súmula 71 STF

### Dicas de prova
- Entenda a diferença entre benefício fiscal e diferimento do recolhimento do valor devido.
- Conheça as Súmulas 20, 49 e 71 do Superior Tribunal de Justiça.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.274 (2)", "page_number": 274, "discipline": "Direito Tributário", "legal_refs": ["Art. X da Lei Y", "..."], "jurisprudence": ["RE 123456", "Súmula 20 STF", "Súmula 49 STF", "Súmula 71 STF"], "confidence": 0.8, "extracted_at": "2026-05-29T18:53:31.628283+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=274", "doc_key": "4ea01bbc004ee893af703c7fedccbc25"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'f59c72e569a3fee5caab066c73a025ca108da63dac1188f70436c21da20fab3d'),
  ('cpiuris2025::20e442bdaa2fe3d6b583cd1517b3324f', 'doutrina', 'cp_iuris', 'Direito Tributário — Preço Máximo ao Consumidor (PMC) e ICMS-ST', '## Preço Máximo ao Consumidor (PMC) e ICMS-ST

O Preço Máximo ao Consumidor (PMC) é o ''teto de preço a ser praticado pelo comércio varejista'' e não pode ser utilizado para medicamentos de uso restrito. A base de cálculo do ICMS/ST é o valor da operação de que decorrer a saída da mercadoria, não o PMC.

### Conceitos
- **Preço Máximo ao Consumidor (PMC)**: o ''teto de preço a ser praticado pelo comércio varejista''
- **ICMS-ST**: Imposto sobre Circulação de Mercadorias e Serviços - Substituição Tributária
- **Base de cálculo do ICMS/ST**: o valor da operação de que decorrer a saída da mercadoria

### Referências legais
- Art. 2º, I, do Decreto-lei n. 406, de 31 de dezembro de 1968
- Cláusula Segunda do Convênio nº 76/1994
