  ('cpiuris2025::072f91101041a168a4ed7de363eb7007', 'doutrina', 'cp_iuris', 'Direito Tributário — Incidência de ICMS sobre vendas a prazo constante e mercadorias adquiridas como insumos', '## Incidência de ICMS sobre vendas a prazo constante e mercadorias adquiridas como insumos

