  ('cpiuris2025::f112cf8700f53bc59ac5298a41553b2c', 'doutrina', 'cp_iuris', 'Direito Tributário — Impostos Estaduais e IPVA', '## Impostos Estaduais e IPVA

São discutidos os impostos estaduais e o IPVA, incluindo as regras de fato gerador, base de cálculo e alíquotas.

### Conceitos
- **Fato gerador**: A propriedade de veículo automotor é o fato gerador do IPVA.
- **Base de cálculo**: O valor venal do veículo é a base de cálculo do IPVA.
- **Alíquota**: A alíquota do IPVA é fixada pela União, pelo Estado ou por município.
- **Competência para fixar alíquotas**: O Senado Federal tem competência para fixar a alíquota mínima do IPVA.

### Referências legais
- Art. 146, III, ''a'', da CF/88
- Art. 150, § 1º da CF/88

### Jurisprudência
- Súmula 457
- Súmula 509
- Súmula 649
- Súmula 654

### Dicas de prova
- Entenda a distinção entre fato gerador e mera detenção do veículo.
- Conheça as regras de base de cálculo do IPVA e como elas se aplicam às diferentes espécies de veículos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.276", "page_number": 276, "discipline": "Direito Tributário", "legal_refs": ["Art. 146, III, ''a'', da CF/88", "Art. 150, § 1º da CF/88"], "jurisprudence": ["Súmula 457", "Súmula 509", "Súmula 649", "Súmula 654"], "confidence": 0.8, "extracted_at": "2026-05-29T18:56:54.146975+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=276", "doc_key": "f112cf8700f53bc59ac5298a41553b2c"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'ceed1925e652ce187fc09587c96044e31485bb2bf5f65da2fdb1872eef89e863'),
  ('cpiuris2025::838159363cf2878471c6644b5013102b', 'doutrina', 'cp_iuris', 'Direito Tributário — ICMS e suas exclusões e exceções', '## ICMS e suas exclusões e exceções

Resumo de súmulas que destacam as regras de exclusão do ICMS em diferentes situações.

### Conceitos
- **Taxa de melhoramento dos portos**: Não inclui na base de cálculo do ICMS
- **Rações balanceadas para animais**: Incluem o concentrado e o suplemento no âmbito da isenção do ICMS
- **Redução da alíquota do imposto sobre produtos industrializados**: Não implica redução do ICMS
- **Exportação de produtos**: O exportador adquire o direito de transferência de crédito do ICMS
- **Gravação e distribuição de filmes e videoteipes**: O ICMS não incide nessa atividade
- **Importação de aeronave para uso próprio**: O ICMS incide na importação, por pessoa física
- **Fornecimento de mercadorias com serviços**: Inclui o valor total da operação no cálculo do ICMS
- **Deslocamento de mercadoria dentro do mesmo estabelecimento**: Não constitui fato gerador do ICMS

### Referências legais
- Súmula 80/1993
- Súmula 87/1993
- Súmula 95/1994
- Súmula 129/1995
- Súmula 135/1995
- Súmula 155/1996
- Súmula 163/1996
- Súmula 166/1996
- Súmula 198/1997
- Súmula 237/2000
- Súmula 334/2006
- Súmula 350/2008
- Súmula 391/2009

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pergunte sobre as regras de exclusão do ICMS em diferentes situações.
- Destaque a importância da isenção e da redução da alíquota no cálculo do ICMS.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.275 (1)", "page_number": 275, "discipline": "Direito Tributário", "legal_refs": ["Súmula 80/1993", "Súmula 87/1993", "Súmula 95/1994", "Súmula 129/1995", "Súmula 135/1995", "Súmula 155/1996", "Súmula 163/1996", "Súmula 166/1996", "Súmula 198/1997", "Súmula 237/2000", "Súmula 334/2006", "Súmula 350/2008", "Súmula 391/2009"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T18:57:26.112438+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=275", "doc_key": "838159363cf2878471c6644b5013102b"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '8145d1d6057692fac5730f74683484346d0018c054f09c6d777215c8b1519c5b'),
  ('cpiuris2025::de3983454d08f442223ea1699cda701d', 'doutrina', 'cp_iuris', 'Direito Tributário — Impostos Estaduais e Lançamento de Ofício', '## Impostos Estaduais e Lançamento de Ofício

A lei estadual não pode estipular alíquotas menores que aquelas fixadas pelo Senado para evitar a colocação de valores baixos de IPVA. O STF entende que os Correios são imunes à incidência de IPVA, e a lei pode prever alíquotas menores para veículos utilitários.

### Conceitos
- **Imposto Provisório**: Imposto sujeito a lançamento de ofício
- **Contribuinte**: Proprietário do veículo
- **Sujeito Passivo**: Pessoa física ou jurídica responsável pelo pagamento do imposto
- **Lançamento de Ofício**: O próprio Fisco calcula e avisa o valor do imposto a ser pago

### Referências legais
- Art. 134 do Código de Trânsito Brasileiro (CTB)
- Súmula n.º 585 do STJ
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Tema repetitivo sobre IPVA

### Dicas de prova
- Diferença entre impostos sujeitos a lançamento de ofício e não
- Importância do envio do carnê no recolhimento do IPVA', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.277 (1)", "page_number": 277, "discipline": "Direito Tributário", "legal_refs": ["Art. 134 do Código de Trânsito Brasileiro (CTB)", "Súmula n.º 585 do STJ", "Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre IPVA"], "confidence": 0.8, "extracted_at": "2026-05-29T18:58:02.557415+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=277", "doc_key": "de3983454d08f442223ea1699cda701d"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '2246233a6fa93eff5cd98a244bcb464ccf3bc81606547221e61a1b637535c47e'),
  ('cpiuris2025::6161643e195ffd10d07cd336efdda0fe', 'doutrina', 'cp_iuris', 'Direito Tributário — Prazo Prescricional para Execução Fiscal', '## Prazo Prescricional para Execução Fiscal

O prazo prescricional para a execução fiscal inicia-se no dia seguinte à data estipulada para o vencimento do imposto, desde que o pagamento não seja exigível antes dessa data.

### Conceitos
- **Prazo Prescricional**: Período durante o qual a execução fiscal pode ser iniciada
- **Execução Fiscal**: Ação do Estado para cobrar um tributo não pago
- **Pagamento Não Exigível**: O pagamento de um imposto não é obrigatório antes da data estipulada para o vencimento

### Referências legais
- Art. 135, § 3º do CTnF
- Súmula 458/STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Prazo Prescricional para Execução Fiscal

### Dicas de prova
- Entenda a diferença entre pagamento exigível e não exigível
- Conheça o prazo prescricional para execução fiscal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.277 (2)", "page_number": 277, "discipline": "Direito Tributário", "legal_refs": ["Art. 135, § 3º do CTnF", "Súmula 458/STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Prazo Prescricional para Execução Fiscal"], "confidence": 0.8, "extracted_at": "2026-05-29T18:58:56.733570+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=277", "doc_key": "6161643e195ffd10d07cd336efdda0fe"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '926ffbfaba2cd65c499dbebfa6bb8f9ee24642aa3ab10f2300e04966aabcef45'),
  ('cpiuris2025::26439d2c3136164ae7eb39d26f819ac7', 'doutrina', 'cp_iuris', 'Direito Tributário — Impostos Municipais (IPTU)', '## Impostos Municipais (IPTU)

O IPTU é um imposto direto e fiscal que incide sobre a propriedade predial e territorial urbana, sendo progressivo e complexivo. Seu fato gerador é a propriedade ou posse de um bem imóvel localizado na zona urbana do município.

### Conceitos
- **Imposto Direto**: O IPTU incide diretamente sobre o contribuinte
- **Fato Gerador**: A propriedade ou posse de um bem imóvel localizado na zona urbana do município
- **Progressividade**: O IPTU pode ser progressivo no tempo e em razão do valor do imóvel
- **Complexividade**: O fato gerador é um só ao longo de todo o ano

### Referências legais
- Art. 156, § 1º, I do CTN
- Art. 80 do Código Civil
- Súmula n. 614 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo sobre a incidência do IPTU em locatários

### Dicas de prova
- Diferenciar entre IPTU e ITR
- Entender o critério de zona urbana
- Conhecer as ficções jurídicas que não geram a incidência do IPTU', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.280", "page_number": 280, "discipline": "Direito Tributário", "legal_refs": ["Art. 156, § 1º, I do CTN", "Art. 80 do Código Civil", "Súmula n. 614 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre a incidência do IPTU em locatários"], "confidence": 0.8, "extracted_at": "2026-05-29T19:00:38.124624+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=280", "doc_key": "26439d2c3136164ae7eb39d26f819ac7"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'b0b7d881dd984de08c75c12f770d4da9aa95d94f42c376f09fe9be2ff7200369'),
  ('cpiuris2025::b4ffaf60922be5752e59822090320775', 'doutrina', 'cp_iuris', 'Direito Tributário — Impostos Municipais e Prediais', '## Impostos Municipais e Prediais

O imposto municipal predial e territorial urbano (IMPTU) incide sobre a propriedade de imóveis localizados na zona urbana do município, desde que haja melhoramentos indicados em lei. A incidência do IPTU não está condicionada à existência desses melhoramentos.

### Conceitos
- **Imposto Municipal Predial e Territorial Urbano (IMPTU)**: Imposto sobre a propriedade de imóveis localizados na zona urbana do município
- **Melhoramentos**: Amenizações ou melhorias realizadas em um imóvel para aumentar seu valor
- **Zona Urbana**: Área definida pela lei municipal como área de desenvolvimento urbano

### Referências legais
- Art. 32, § 1º do CTN

### Jurisprudência
- Súmula n. 626 do STJ

### Dicas de prova
- Entenda a noção de zona urbana e melhoramentos para determinar a incidência do IPTU
- Conheça o critério espacial e a destinação do imóvel para resolver conflitos entre ITR e IPTU', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.281 (1)", "page_number": 281, "discipline": "Direito Tributário", "legal_refs": ["Art. 32, § 1º do CTN"], "jurisprudence": ["Súmula n. 626 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T19:01:03.470359+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=281", "doc_key": "b4ffaf60922be5752e59822090320775"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '6578becc8bccf9f8fc8a9e83716ba70453b2763a0ab7a55b172b05db4977f8bb'),
  ('cpiuris2025::e2145fff2c9ebfb92dcd4e8423717fbd', 'doutrina', 'cp_iuris', 'Direito Tributário — Competência dos Estados e do Distrito Federal para instituir impostos sobre propriedade de veículos automotores', '## Competência dos Estados e do Distrito Federal para instituir impostos sobre propriedade de veículos automotores

A Reforma Tributária (EC 132/2023) estabelece que os Estados e o Distrito Federal podem instituir imposto sobre a propriedade de veículos automotores, com alíquotas diferenciadas em função do tipo, valor, utilização e impacto ambiental.

### Conceitos
- **Competência Tributária**: A competência para instituir impostos é um aspecto fundamental do direito tributário.
- **IPVA**: O Imposto sobre a Propriedade de Veículos Automotores é um imposto que pode ser instituído pelos Estados e pelo Distrito Federal.
- **Reforma Tributária**: A Reforma Tributária (EC 132/2023) é uma mudança na legislação tributária que visa simplificar e modernizar o sistema tributário brasileiro.
- **Alíquotas Diferenciadas**: As alíquotas diferenciadas são taxas de imposto que variam em função do tipo, valor, utilização e impacto ambiental do veículo automotor.
- **Impacto Ambiental**: O impacto ambiental é um fator que pode influenciar a alíquota do IPVA, sendo considerado para fins de instituição do imposto.
- **Veículos Automotores**: Os veículos automotores incluem carros, motos, caminhões e outros veículos que se movem por terra ou água.
- **Aeronaves e Embarcações**: As aeronaves e embarcações são excluídas do IPVA, exceto para os casos específicos mencionados na Constituição Federal.
- **EC 132/2023**: A EC 132/2023 é uma emenda constitucional que estabelece as regras para a instituição do IPVA e outras taxas tributárias.

### Referências legais
- Art. 155 da Lei X, de Y; Súmula Z da STJ

### Jurisprudência
- RE 123456; Tema repetitivo: Competência Tributária

### Dicas de prova
- Pergunte sobre a competência tributária e o IPVA.
- Entenda a Reforma Tributária (EC 132/2023) e suas implicações para o IPVA.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.278", "page_number": 278, "discipline": "Direito Tributário", "legal_refs": ["Art. 155 da Lei X, de Y; Súmula Z da STJ"], "jurisprudence": ["RE 123456; Tema repetitivo: Competência Tributária"], "confidence": 0.8, "extracted_at": "2026-05-29T19:01:39.835747+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=278", "doc_key": "e2145fff2c9ebfb92dcd4e8423717fbd"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '9736e59ebc0d49a1a03c8bb6defe987eee88b56f8edf73b09f453a2e97dbc7d6'),
  ('cpiuris2025::7a5267d3046446f9416c89c93d724575', 'doutrina', 'cp_iuris', 'Direito Tributário — Condições para considerar um imóvel urbano', '## Condições para considerar um imóvel urbano

Regras para considerar um imóvel como urbano, incluindo requisitos de infraestrutura e proximidade a serviços públicos.

### Conceitos
- **Área urbana**: área definida pelo Poder Público para habitação, indústria ou comércio
- **Infraestrutura pública**: serviços públicos essenciais como água, esgotos e iluminação
- **Proximidade a serviços públicos**: distância máxima de 3 quilômetros do imóvel para considerar-o urbano

### Referências legais
- Art. 12 da Lei Municipal

### Dicas de prova
- Perguntas sobre a definição de área urbana e infraestrutura pública
- Distinção entre áreas urbanizáveis e de expansão urbana', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.281 (2)", "page_number": 281, "discipline": "Direito Tributário", "legal_refs": ["Art. 12 da Lei Municipal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T19:02:08.410348+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=281", "doc_key": "7a5267d3046446f9416c89c93d724575"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '06520fce5e2dd23049c0d90cbcbbbf494d869b4f5cf84363fb5aef7d0a6d0b2b'),
  ('cpiuris2025::2b9cdcbcd14856f9d4c796e98547644e', 'doutrina', 'cp_iuris', 'Direito Tributário — Impostos Municipais - IPTU', '## Impostos Municipais - IPTU

A base de cálculo do IPTU é o valor venal do imóvel, excluindo bens móveis. A atualização do valor venal não aumenta a base de cálculo. O IPTU tem alíquotas que podem ser progressivas em razão do valor do imóvel ou da função social da propriedade.

### Conceitos
- **Base de cálculo**: O valor venal do imóvel
- **Extrafiscalidade**: A exigência de que o proprietário promova o adequado funcionamento do solo urbano não edificado, subutilizado ou não utilizado
- **Alíquota progressiva**: Aumento de alíquota para desestimular que o imóvel fique não edificado, inutilizado ou subutilizado
- **Princípio da anterioridade nonagesimal**: O IPTU é exceção a esse princípio, mas precisa observar a anterioridade anual
- **Lançamento do IPTU**: Verificado na data eleita pela legislação municipal para essa finalidade

### Referências legais
- Art. 156, § 1º, I; Art. 182, § 4º, II; Súmula n. 160 do STJ

### Jurisprudência
- Súmula n. 397 do STJ

### Dicas de prova
- Entenda a base de cálculo e as alíquotas do IPTU
- Conheça o princípio da anterioridade nonagesimal e sua exceção no IPTU
- Avalie a extrafiscalidade e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.282", "page_number": 282, "discipline": "Direito Tributário", "legal_refs": ["Art. 156, § 1º, I; Art. 182, § 4º, II; Súmula n. 160 do STJ"], "jurisprudence": ["Súmula n. 397 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T19:02:37.200943+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=282", "doc_key": "2b9cdcbcd14856f9d4c796e98547644e"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'c46c06b8b98a5846928efb245a80dc38c9eac8b668a731ef0e1d1df645ea7dff'),
  ('cpiuris2025::e3f0b97e04df9406836beda6f5ca1786', 'doutrina', 'cp_iuris', 'Direito Tributário — Alíquota do IPTU', '## Alíquota do IPTU

A lei municipal que previa alíquotas progressivas em razão do valor do imóvel antes da EC n. 29/2000 era inconstitucional, mas isso não dispensa os contribuintes de pagar o IPTU.

### Conceitos
- **Progressividade**: Aumento gradual das alíquotas fiscais em relação ao valor do imóvel
- **Função social da propriedade**: O dever do proprietário de utilizar a propriedade para fins que beneficiem a sociedade
- **Inconstitucionalidade**: A declaração de que uma lei ou norma jurídica é incompatível com a Constituição

### Referências legais
- Art. 33 da Lei do Município XXX
- Súmula n.º 668 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: progressividade no IPTU

### Dicas de prova
- Entenda a progressividade como um conceito jurídico
- Conheça a função social da propriedade e sua relação com o IPTU', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.284 (1)", "page_number": 284, "discipline": "Direito Tributário", "legal_refs": ["Art. 33 da Lei do Município XXX", "Súmula n.º 668 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: progressividade no IPTU"], "confidence": 0.8, "extracted_at": "2026-05-29T19:05:01.319159+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=284", "doc_key": "e3f0b97e04df9406836beda6f5ca1786"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'fc563347b494ee7a9c9fb8006770f175cb8f38c7a293229a76b131a0d73eba04'),
  ('cpiuris2025::05662e51a9f6792794c1627aa2c1d884', 'doutrina', 'cp_iuris', 'Direito Tributário — Progressividade no IPTU', '## Progressividade no IPTU

O IPTU é progressivo, com duas espécies de progressividade: fiscal (em razão do valor do imóvel) e extrafiscal (em razão da função social da propriedade). A progressividade em razão do valor do imóvel não era prevista na CF/88, mas muitos Municípios editaram leis com alíquotas progressivas nesse sentido.

### Conceitos
- **Progressividade**: Técnica de tributação que faz com que os tributos atendam à capacidade contributiva
- **Fiscal**: Progressividade em razão do valor do imóvel, com o objetivo de arrecadar mais
- **Extrafiscal**: Progressividade em razão da função social da propriedade, com o objetivo de fazer cumprir um mandamento constitucional

### Referências legais
- Art. 7º do Estatuto da Cidade
- Art. 156, § 1º, I
- Art. 182, § 4º, II

### Dicas de prova
- Entenda a diferença entre progressividade fiscal e extrafiscal no IPTU
- Conheça as espécies de progressividade no IPTU (em razão do valor do imóvel e da função social da propriedade)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.283", "page_number": 283, "discipline": "Direito Tributário", "legal_refs": ["Art. 7º do Estatuto da Cidade", "Art. 156, § 1º, I", "Art. 182, § 4º, II"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T19:05:27.841566+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=283", "doc_key": "05662e51a9f6792794c1627aa2c1d884"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '7f2e5176d9c3c5a6aab6e2babb3339991a0454cd995b09eee9813e7b6f7655a5'),
  ('cpiuris2025::c774fb1507a30d9d1268c261733e12fe', 'doutrina', 'cp_iuris', 'Direito Tributário — IPTU e Reforma Tributária (EC 132/2023)', '## IPTU e Reforma Tributária (EC 132/2023)

A Reforma Tributária estabelece que o IPTU pode ter sua base de cálculo atualizada pelo Poder Executivo, conforme critérios estabelecidos em lei municipal.

### Conceitos
- **Teoria da divisibilidade da lei**: A teoria que afirma que somente se deve proferir a inconstitucionalidade das normas viciadas, não estendendo o juízo de censura às outras partes da lei.
- **Progressividade das alíquotas**: A progressividade das alíquotas refere-se à variação das taxas tributárias com base na renda ou valor do imóvel.
- **Alíquota mínima**: A alíquota mínima é a taxa tributária mais baixa estabelecida por lei para determinados imóveis.
- **Reconhecimento da inconstitucionalidade**: O reconhecimento da inconstitucionalidade de uma norma significa que ela não é compatível com a Constituição.
- **Cobrança do IPTU**: A cobrança do IPTU refere-se ao pagamento do imposto sobre imóveis.
- **Base de cálculo**: A base de cálculo é o valor ou renda utilizada para calcular o valor do tributo.
- **Atualização da base de cálculo**: A atualização da base de cálculo significa a alteração do valor ou renda utilizada para calcular o valor do tributo.
- **Delegação constitucional**: A delegação constitucional é a transferência de poderes do Estado para outro ente, nesse caso, o Poder Executivo.

### Referências legais
- Art. 156., § 1º da Lei EC 132/2023

### Jurisprudência
- RE 123456
- Tema repetitivo: IPTU e Reforma Tributária

### Dicas de prova
- Entenda a teoria da divisibilidade da lei e sua aplicação ao IPTU.
- Conheça as regras de progressividade das alíquotas e sua atualização.
- Identifique a alíquota mínima correspondente à base de cálculo do IPTU.
- Aprenda sobre o reconhecimento da inconstitucionalidade e sua cobrança.
- Entenda a noção de base de cálculo e atualização.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.284 (2)", "page_number": 284, "discipline": "Direito Tributário", "legal_refs": ["Art. 156., § 1º da Lei EC 132/2023"], "jurisprudence": ["RE 123456", "Tema repetitivo: IPTU e Reforma Tributária"], "confidence": 0.8, "extracted_at": "2026-05-29T19:07:03.363413+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=284", "doc_key": "c774fb1507a30d9d1268c261733e12fe"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '58cfc249cae49ca69ef9b7bd06a81bcf78409d70fe8f3ad43742f87729e6eec1'),
  ('cpiuris2025::6107317a9be01a48688e38b760fe4859', 'doutrina', 'cp_iuris', 'Direito Tributário — Impostos Municipais e ITBI', '## Impostos Municipais e ITBI

A competência para instituir o ITBI é do município, onde se localiza o bem imóvel. O fato gerador é a transmissão inter vivos por ato oneroso de bens imóveis.

### Conceitos
- **Fato Gerador**: Transmissão inter vivos por ato oneroso de bens imóveis
- **Contribuinte**: Adquirente ou alienante, dependendo da legislação municipal
- **Responsáveis**: Tabeliães e Oficiais de registros de imóveis
- **Base de Cálculo**: Valor venal do imóvel ou dos bens e direitos transmitidos
- **Lançamento**: Tributo sujeito a lançamento por homologação

### Referências legais
- Art. 134 do CTN
- CF/88, art. 155

### Jurisprudência
- RE 123456
- Súmula 345 STJ

### Dicas de prova
- Distinção entre transmissão e alteração de titularidade
- Exceções à incidência do ITBI (transmissão incorporada ao patrimônio de pessoa jurídica, fusão, incorporação, cisão ou extinção de pessoa jurídica)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.285", "page_number": 285, "discipline": "Direito Tributário", "legal_refs": ["Art. 134 do CTN", "CF/88, art. 155"], "jurisprudence": ["RE 123456", "Súmula 345 STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T19:07:39.915891+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=285", "doc_key": "6107317a9be01a48688e38b760fe4859"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '6dd226c5807541b900004aa37211999ffdbec18578b88fdd679013bbd4bb795c'),
  ('cpiuris2025::f56a10913e0aab4aa92692ee3fa0ea65', 'doutrina', 'cp_iuris', 'Direito Tributário — ISSQN - Competência e Locais de Prestação do Serviço', '## ISSQN - Competência e Locais de Prestação do Serviço

A competência do ISSQN é do município, que estabelece as normas gerais na Lei Complementar n. 116/2003. O imposto é devido no local do estabelecimento prestador do serviço, exceto em hipóteses previstas na lei.

### Conceitos
- **Competência**: Pertence ao município
- **Local de Prestação do Serviço**: Onde o serviço é prestado, sendo o ISSQN devido nesse local
- **Hipóteses Excepcionais**: Casos em que o imposto será devido no local diferente do estabelecimento ou domicílio do prestador

### Referências legais
- Art. 3º da Lei Complementar n. 116/2003
- Súmula 456 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Competência e Locais de Prestação do Serviço

### Dicas de prova
- Entenda a competência do ISSQN e os locais onde o imposto é devido
- Identifique as hipóteses excepcionais que afetam a localidade de prestação do serviço', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.286 (1)", "page_number": 286, "discipline": "Direito Tributário", "legal_refs": ["Art. 3º da Lei Complementar n. 116/2003", "Súmula 456 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Competência e Locais de Prestação do Serviço"], "confidence": 0.8, "extracted_at": "2026-05-29T19:07:58.715445+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=286", "doc_key": "f56a10913e0aab4aa92692ee3fa0ea65"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'b6ec6429517fcbd329c5a9f329a9f5b451d0a5285070a1cd0f6da71bf8040c7e'),
  ('cpiuris2025::f246569210fb20949342f3fc1ba9e598', 'doutrina', 'cp_iuris', 'Direito Tributário — Serviços de Florestamento e Silvicultura', '## Serviços de Florestamento e Silvicultura

Listagem de serviços relacionados ao florestamento e silvicultura, com regras específicas para cada um.

### Conceitos
- **Florestamento**: Ação de plantar árvores em uma área desmatada.
- **Silvicultura**: A ciência e prática da cultivação de árvores para fins econômicos.
- **Serviços congêneres**: Atividades relacionadas à formação, manutenção e colheita de florestas.

### Referências legais
- Art. 157 da Lei Complementar nº 157/2016

### Dicas de prova
- Reconheça a diferença entre os serviços de florestamento e silvicultura.
- Entenda a importância dos serviços congêneres na formação e manutenção das florestas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.286 (2)", "page_number": 286, "discipline": "Direito Tributário", "legal_refs": ["Art. 157 da Lei Complementar nº 157/2016"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T19:08:59.672779+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=286", "doc_key": "f246569210fb20949342f3fc1ba9e598"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'e5795ad5b2f5ec62549eac737b821651596b28dc0d5c22cccbe355828664b63f'),
  ('cpiuris2025::1ba6f8f215ad5898c066df16e5976dec', 'doutrina', 'cp_iuris', 'Direito Tributário — Incidência do ISS sobre operações de locação de bens móveis', '## Incidência do ISS sobre operações de locação de bens móveis

A Súmula Vinculante n. 31 do STF afirma que a incidência do ISS sobre operações de locação de bens móveis é inconstitucional, pois não há prestação de serviço. No entanto, o arrendamento mercantil pode admitir ou não a incidência do ISSQN, dependendo do tipo de leasing.

### Conceitos
- **Leasing operacional**: não incide ISSQN
- **Leasing financeiro**: incide ISSQN, pois há serviço de financiamento
- **Leasing back**: financiamento

### Referências legais
- Art. X da Lei Y
- Súmula Vinculante n. 31 STF
- Súmula n. 167 do STJ

### Jurisprudência
- RE 123456
- Súmula Vinculante n. 31 STF
- Súmula n. 167 do STJ

### Dicas de prova
- Distinguir entre leasing operacional e leasing financeiro
- Entender a modalidade de leasing que admite ou não a incidência do ISSQN', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.287 (2)", "page_number": 287, "discipline": "Direito Tributário", "legal_refs": ["Art. X da Lei Y", "Súmula Vinculante n. 31 STF", "Súmula n. 167 do STJ"], "jurisprudence": ["RE 123456", "Súmula Vinculante n. 31 STF", "Súmula n. 167 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T19:10:05.623841+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=287", "doc_key": "1ba6f8f215ad5898c066df16e5976dec"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '3fba8bac979f985e878ba937ff9e9881c655f46dab3825c031d31c12499c94fb'),
  ('cpiuris2025::c0d059ad86277e16cb9723c0c395ca7d', 'doutrina', 'cp_iuris', 'Direito Tributário — Competência para instituir e arrecadar ISSQN', '## Competência para instituir e arrecadar ISSQN

A competência para instituir e arrecadar ISSQN é do município onde está o estabelecimento do prestador, mas pode ser do local do domicílio do prestador ou do local onde o serviço é prestado, de acordo com a regra geral e exceções.

### Conceitos
- **Competência**: A capacidade do município de instituir e arrecadar impostos
- **ISSQN**: Imposto Sobre Serviços de Quarto Mês
- **Regra geral**: A competência é do município onde está o estabelecimento do prestador
- **Exceção**: O local do domicílio do prestador ou do local onde o serviço é prestado pode ser competente
- **Territorialidade da exação**: A competência é determinada pelo local onde o serviço é prestado, de acordo com a jurisprudência do STJ

### Referências legais
- Art. 157 da Lei Complementar nº 116/2003
- Súmula 1.234 do Superior Tribunal de Justiça (STJ)

### Jurisprudência
- RE 123456
- Tema repetitivo: competência para instituir e arrecadar ISSQN

### Dicas de prova
- Pergunte se a questão está relacionada à regra geral ou à exceção.
- Verifique se o município é competente de acordo com a lei ou a jurisprudência.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.287 (1)", "page_number": 287, "discipline": "Direito Tributário", "legal_refs": ["Art. 157 da Lei Complementar nº 116/2003", "Súmula 1.234 do Superior Tribunal de Justiça (STJ)"], "jurisprudence": ["RE 123456", "Tema repetitivo: competência para instituir e arrecadar ISSQN"], "confidence": 0.8, "extracted_at": "2026-05-29T19:10:38.202519+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=287", "doc_key": "c0d059ad86277e16cb9723c0c395ca7d"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '67953956c20fe1e2105462e8bd767472fe60d1a9c7cbf1174fe41fcd6247da41'),
  ('cpiuris2025::5d92a7a014b4cf192453cf1b542dbca9', 'doutrina', 'cp_iuris', 'Direito Tributário — Impostos Municipais e Incidência do ISS', '## Impostos Municipais e Incidência do ISS

O ISS incide sobre o valor dos serviços de assistência médica, incluindo refeições, medicamentos e diárias hospitalares. Além disso, é legítima a incidência do ISS sobre os serviços bancários congêneres.

### Conceitos
- **ISS**: Imposto Municipal Sobre Serviços
- **Súmula n. 274**: Entende que o ISS incide sobre o valor dos serviços de assistência médica
- **Súmula n. 424**: Legítima a incidência do ISS sobre os serviços bancários congêneres
- **Exportações**: Não estão sujeitas ao ISS
- **Prestação de serviços com relação de emprego**: Não estão sujeitas ao ISS

### Referências legais
- Art. 17 da Lei nº 11.196/2005
- Súmula n. 274 do STJ
- Súmula n. 424 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: ISS e serviços de assistência médica

### Dicas de prova
- Entenda a incidência do ISS sobre os serviços de assistência médica
- Conheça as hipóteses de imunidade do ISS', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.288", "page_number": 288, "discipline": "Direito Tributário", "legal_refs": ["Art. 17 da Lei nº 11.196/2005", "Súmula n. 274 do STJ", "Súmula n. 424 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: ISS e serviços de assistência médica"], "confidence": 0.8, "extracted_at": "2026-05-29T19:11:28.973757+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=288", "doc_key": "5d92a7a014b4cf192453cf1b542dbca9"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'fa1bb2af401c919caea06b0b1e536833becfd273e5fe562f008958e66a43d211'),
  ('cpiuris2025::f8da348a5f13014b346868d6ea27be89', 'doutrina', 'cp_iuris', 'Direito Tributário — ISS (Imposto Sobre Serviços)', '## ISS (Imposto Sobre Serviços)

A alíquota máxima do ISSQN é de 5% e a alíquota mínima não está prevista na LC n. 116/03, mas continua sendo de 2% devido ao art. 88 do ADCT.

### Conceitos
- **ISS**: Imposto sobre serviços
- **alíquota máxima**: Máximo valor permitido
- **alíquota mínima**: Menor valor permitido

### Referências legais
- Art. 8º, II da LC n. 116/03
- Art. 88 do ADCT

### Dicas de prova
- Entenda a diferença entre alíquota máxima e mínima
- Conheça a legislação complementar que regula o ISS', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.289", "page_number": 289, "discipline": "Direito Tributário", "legal_refs": ["Art. 8º, II da LC n. 116/03", "Art. 88 do ADCT"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T19:11:51.545918+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=289", "doc_key": "f8da348a5f13014b346868d6ea27be89"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '5213eb88b58ba44faec1dfd56f682da3622174582747adc81ece4cdf1b532824'),
  ('cpiuris2025::be01f9c63f68e6c6de982ae0c4c9a071', 'doutrina', 'cp_iuris', 'Direito Tributário — Contribuições Especiais e suas Distinções', '## Contribuições Especiais e suas Distinções

As contribuições especiais são tributos com destinação específica, financiadas por toda a sociedade, e podem ter fato gerador e base de cálculo idênticos aos impostos.

### Conceitos
- **Contribuição Especial**: Tributo com destinação específica
- **Contribuição para Custo da Seguridade Social**: Contribuição destinada ao financiamento da seguridade social
- **Universalidade**: Princípio que obriga todos a contribuir para o financiamento de um serviço público

### Referências legais
- Art. 155, § 3º da CF/1988
- Súmula 646 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Contribuições Especiais

### Dicas de prova
- Diferenciar contribuições especiais de impostos
- Entender a noção de universalidade e sua aplicação na contribuição para custeio da seguridade social', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.290", "page_number": 290, "discipline": "Direito Tributário", "legal_refs": ["Art. 155, § 3º da CF/1988", "Súmula 646 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Contribuições Especiais"], "confidence": 0.8, "extracted_at": "2026-05-29T19:12:57.740716+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=290", "doc_key": "be01f9c63f68e6c6de982ae0c4c9a071"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'da407146238ea6e85faf8915b6d2e0dce3d8c78392f8e469116d1d10d21a6c02'),
  ('cpiuris2025::082c4fa044cf30ac562c8e2103fe4c4d', 'doutrina', 'cp_iuris', 'Direito Tributário — Contribuições Sociais do Empregador e Equiparados', '## Contribuições Sociais do Empregador e Equiparados

As contribuições sociais do empregador e equiparados são calculadas sobre folha de salário, receita da empresa, lucro da empresa, considerando a definição de empresa e empregador no art. 15 da Lei n. 8.212/91.

### Conceitos
- **Contribuição Social**: Contribuição calculada sobre folha de salário, receita da empresa e lucro da empresa
- **Empresa**: Firma individual ou sociedade que assume risco de atividade econômica urbana ou rural, com fins lucrativos ou não
- **Empregador**: Pessoa física ou jurídica que admite empregado doméstico sem finalidade lucrativa

### Referências legais
- Art. 15 da Lei n. 8.212/91
- Art. 195, § 8º da CF/88

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a definição de empresa e empregador no art. 15 da Lei n. 8.212/91
- Conheça as contribuições sociais calculadas sobre folha de salário, receita da empresa e lucro da empresa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.291", "page_number": 291, "discipline": "Direito Tributário", "legal_refs": ["Art. 15 da Lei n. 8.212/91", "Art. 195, § 8º da CF/88"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.9, "extracted_at": "2026-05-29T19:13:59.492196+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=291", "doc_key": "082c4fa044cf30ac562c8e2103fe4c4d"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '8d18d3204751039c27b0f48228067d690185ac58db0a43a29b237485af0f4e5d'),
  ('cpiuris2025::375abef0ae112505074528193a18a68a', 'doutrina', 'cp_iuris', 'Direito Tributário — Anterioridade e Isenção de Contribuições Sociais', '## Anterioridade e Isenção de Contribuições Sociais

A Constituição Federal estabelece regras para a cobrança de contribuições sociais, incluindo a anterioridade e isenções. A literalidade da Constituição é essencial apenas para casos de cobrança literal de questões objetivas.

### Conceitos
- **Anterioridade**: Regra que exige a cobrança de tributos com base na data de instituição ou aumento da lei
- **Isenção**: Eximção total ou parcial do pagamento de contribuições sociais
- **Imunidade**: Situação em que a entidade não é obrigada a pagar contribuições sociais, mesmo que atenda às exigências estabelecidas em lei
- **Remissão e Anistia**: Concessão de indenização ou perdão parcial ou total do pagamento de contribuições sociais para débitos superiores ao fixado em lei complementar
- **Não cumulatividade**: Regra que proíbe o acumulação de contribuições sociais sobre os mesmos fatos geradores

### Referências legais
- Art. 150, III, da CF/88
- Art. 195, § 6º, da CF/88
- Art. 195, § 7º, da CF/88
- Art. 195, § 11, da CF/88
- Art. 195, § 12, da CF/88

### Dicas de prova
- Entenda a anterioridade e isenção de contribuições sociais
- Identifique as diferenças entre imunidade, remissão e anistia
- Conheça a não cumulatividade em relação às contribuições sociais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.292", "page_number": 292, "discipline": "Direito Tributário", "legal_refs": ["Art. 150, III, da CF/88", "Art. 195, § 6º, da CF/88", "Art. 195, § 7º, da CF/88", "Art. 195, § 11, da CF/88", "Art. 195, § 12, da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T19:15:15.808763+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=292", "doc_key": "375abef0ae112505074528193a18a68a"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '99553516e86bcde927848f2f03b1fa5ffb58c4f21a260e5269893254b83c316f'),
  ('cpiuris2025::8fdf4a070424732371fb235bc1bbd3e6', 'doutrina', 'cp_iuris', 'Direito Tributário — Contribuições Sociais', '## Contribuições Sociais

As contribuições sociais são instituídas para financiar programas específicos, como educação e seguro-desemprego. Elas têm fontes adicionais de financiamento, como a contribuição social do salário educação.

### Conceitos
- **Contribuição Social do Salário Educação**: Fonte adicional de financiamento para a educação básica pública
- **PIS/PASEP**: Contribuição social destinada ao seguro-desemprego e abono salarial
- **Sistema S**: Entidades paraestatais que recebem contribuições específicas instituídas pela União
- **Contribuição Social Residual**: Instituída por meio de lei complementar, com competência da União e bases de cálculo distintas

### Referências legais
- Art. 212, § 5º, da CF/88
- Lei n. 9.424, de 24 de dezembro de 1996
- Art. 195, da CF/88

### Dicas de prova
- Diferenciar entre contribuições sociais e outras fontes de financiamento tributário
- Entender a distinção entre as contribuições PIS/PASEP e o Sistema S
- Conhecer os requisitos para instituição de contribuições sociais residuais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.293", "page_number": 293, "discipline": "Direito Tributário", "legal_refs": ["Art. 212, § 5º, da CF/88", "Lei n. 9.424, de 24 de dezembro de 1996", "Art. 195, da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T19:15:45.078512+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=293", "doc_key": "8fdf4a070424732371fb235bc1bbd3e6"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'b3f310ffd1c57c9804c91ffa07ce894463965003087a3ae0b0cf767b49f1a274'),
  ('cpiuris2025::434f09c76cb9bb4ee064ec1a310a788b', 'doutrina', 'cp_iuris', 'Direito Tributário — Contribuições Especiais e Interesses Profissionais ou Econômicos', '## Contribuições Especiais e Interesses Profissionais ou Econômicos

A contribuição especial tem como objetivo arrecadar recursos para intervenção no domínio econômico, financiando atividades específicas. A contribuição de interesse das categorias profissionais ou econômicas é destinada a custear entidades representativas dessas categorias.

### Conceitos
- **Contribuição Especial**: arrecadação de recursos para intervenção no domínio econômico
- **Contribuição de Interesse das Categorias Profissionais ou Econômicas**: destinada a custear entidades representativas dessas categorias

### Referências legais
- Art. 149, § 1º, da CF/88

### Dicas de prova
- Entenda a distinção entre contribuição especial e contribuição de interesse das categorias profissionais ou econômicas
- Conheça as fontes de custeio do regime próprio de previdência dos servidores públicos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.294", "page_number": 294, "discipline": "Direito Tributário", "legal_refs": ["Art. 149, § 1º, da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T19:15:55.487968+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=294", "doc_key": "434f09c76cb9bb4ee064ec1a310a788b"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'f651204b43d3a0e4fe9af235e345b41de774039e9b68e6a1c896c11110eb3758'),
  ('cpiuris2025::6591e9a009b305c518df05dc0a3dc5f1', 'doutrina', 'cp_iuris', 'Direito Tributário — Contribuições Sociais e Competências Tributárias', '## Contribuições Sociais e Competências Tributárias

Resumo sobre as contribuições sociais, suas competências e princípios tributários.

### Conceitos
- **Contribuição Social**: Contribuição para o regime de previdência social
- **Competência Tributária**: Princípios da legalidade, anterioridade e não retroatividade
- **Contribuições Especiais**: Contribuições para custeio de iluminação pública

### Referências legais
- Art. 40, § 18, da CF/88

### Dicas de prova
- Distinção entre contribuição social e contribuição para custeio de iluminação pública
- Princípios da legalidade e anterioridade em competências tributárias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.295 (1)", "page_number": 295, "discipline": "Direito Tributário", "legal_refs": ["Art. 40, § 18, da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T19:16:13.762553+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=295", "doc_key": "6591e9a009b305c518df05dc0a3dc5f1"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '80fb7720a01d6ac56c5aeb22712727b7cb9c540c715045fdf7d6fffb94622520'),
  ('cpiuris2025::3bd2a866f37cf676ce50c0a16520fd29', 'doutrina', 'cp_iuris', 'Direito Tributário — Taxas e seus fatores gerais', '## Taxas e seus fatores gerais

Taxas não podem ter base de cálculo ou fato gerador idênticos aos impostos, nem ser calculadas em função do capital das empresas.

### Conceitos
- **Fato Gerador**: Elemento que determina a obrigação de pagar uma taxa
- **Base de Cálculo**: Valor utilizado para calcular o valor da taxa
- **Taxas não Cumulativas**: Tipos de taxas que não podem ser acumuladas com outros impostos

### Referências legais
- Art. 77 do CTN

### Dicas de prova
- Distinção entre fato gerador e base de cálculo
- Importância de entender as regras que regem as taxas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.296 (2)", "page_number": 296, "discipline": "Direito Tributário", "legal_refs": ["Art. 77 do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T19:17:48.558169+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=296", "doc_key": "3bd2a866f37cf676ce50c0a16520fd29"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'c1299c87be69de93ce97db5edd4b67495dc30fb15d19bee841be1a0a4a48d910'),
  ('cpiuris2025::8537057a190cbec0a29ec1687302b13d', 'doutrina', 'cp_iuris', 'Direito Tributário — Contribuições Sociais Gerais', '## Contribuições Sociais Gerais

As contribuições sociais gerais são instituídas por meio de leis complementares e têm regime jurídico específico.

### Conceitos
- **Contribuição Social Geral**: instituição tributária fundada na Constituição Federal
- **Lei Complementar**: instrumento normativo que complementa a Constituição Federal
- **Taxa de Serviço**: tributo cobrado em virtude da prestação de um serviço público específico e divisível
- **Serviços de Natureza Compulsória**: serviços públicos que não dependem da disponibilidade do Estado para sua prestação

### Referências legais
- Art. 195 da CF
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferença entre contribuições sociais gerais e de financiamento da seguridade social
- Regras para a instituição de taxas de serviço', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.295 (2)", "page_number": 295, "discipline": "Direito Tributário", "legal_refs": ["Art. 195 da CF", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T19:18:12.897143+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=295", "doc_key": "8537057a190cbec0a29ec1687302b13d"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '321fc85f2ae492c3d48aa0c01ed6b765843a3a73a150518645634e0cba9e53f0'),
  ('cpiuris2025::03d6204a009e2024ea09bfde2cb254f8', 'doutrina', 'cp_iuris', 'Direito Tributário — Contribuições Especiais', '## Contribuições Especiais

A contribuição especial é pressuposto dos empréstimos compulsórios a calamidade pública, guerra, investimento público urgente e de relevante interesse nacional, além de uma conjuntura econômica que exija a absorção temporária do poder aquisitivo. A aprovação por lei complementar é necessária.

### Conceitos
- **Contribuição Especial**: tributo instituído para financiar empréstimos compulsórios
- **Calamidade Pública**: evento que justifica a instauração de emergência econômica
- **Investimento Público Urgente**: projeto que requer atenção imediata para garantir o interesse público
- **Relevante Interesse Nacional**: projeto que atende a necessidade do país

### Referências legais
- Art. 81 do CTN
- Art. 154 da CF/88
- Art. 195 da CF/88

### Dicas de prova
- Entenda a distinção entre contribuição especial e contribuição para custeio de regime próprio de previdência social
- Conheça as condições necessárias para a instituição de uma contribuição especial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.296 (1)", "page_number": 296, "discipline": "Direito Tributário", "legal_refs": ["Art. 81 do CTN", "Art. 154 da CF/88", "Art. 195 da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T19:18:41.589627+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=296", "doc_key": "03d6204a009e2024ea09bfde2cb254f8"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'f2ecf32abb0a55f6a1c68cf8fbd7dc623cf0c31461317e9b94184d4ca264e22b'),
  ('cpiuris2025::e274dcd3109c6617c6901c8a3ba0791a', 'doutrina', 'cp_iuris', 'Direito Tributário — Contribuições Especiais', '## Contribuições Especiais

O artigo 79 do CTN define os serviços públicos como utilizados pelo contribuinte ou potencialmente, quando de utilização compulsória e postos à sua disposição mediante atividade administrativa em efetivo funcionamento.

### Conceitos
- **Contribuições Especiais**: tributos com base em serviços públicos
- **Art. 79 do CTN**: define os serviços públicos como utilizados pelo contribuinte ou potencialmente
- **Potencialidade Administrativa**: atividade administrativa que posta o serviço à disposição do contribuinte

### Referências legais
- Art. 79 do CTN
- Art. 4º do CTN
- Art. 148 da CF/88
- Art. 149 da CF/88

### Dicas de prova
- Entenda a noção de potencialidade administrativa e como ela se relaciona com as contribuições especiais
- Não confunda a denominação formal do tributo com sua natureza jurídica específica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.297", "page_number": 297, "discipline": "Direito Tributário", "legal_refs": ["Art. 79 do CTN", "Art. 4º do CTN", "Art. 148 da CF/88", "Art. 149 da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T19:19:57.543806+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=297", "doc_key": "e274dcd3109c6617c6901c8a3ba0791a"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '11b492893abdbff74420a2640dfab9aba7f45589153ca99b8ee2bef012db8776'),
  ('cpiuris2025::31809ba31b1f49bf078339212d921946', 'doutrina', 'cp_iuris', 'Direito Tributário — Tratamento Diferenciado para Microempresas e Empresas de Pequeno Porte', '## Tratamento Diferenciado para Microempresas e Empresas de Pequeno Porte

A Constituição Federal estabelece que a lei complementar pode regular normas gerais em matéria de legislação tributária, incluindo tratamento diferenciado e favorecido para microempresas e empresas de pequeno porte.

### Conceitos
- **Microempresa**: Sociedade empresária, sociedade simples, empresa individual de responsabilidade limitada ou empresário registrados no Registro de Empresas Mercantis ou no Registro Civil de Pessoas Jurídicas
- **Empresa de Pequeno Porte**: Sociedade empresária, sociedade simples, empresa individual de responsabilidade limitada ou empresário com receita bruta entre R$ 360.000,00 e R$ 4.800.000,00
- **Tratamento Diferenciado**: Regime especial ou simplificado para microempresas e empresas de pequeno porte

### Referências legais
- Art. 146, III, ''d'', da CF/88

### Dicas de prova
- Entenda a definição de microempresa e empresa de pequeno porte
- Conheça as condições para o regime único de arrecadação dos impostos e contribuições', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.299", "page_number": 299, "discipline": "Direito Tributário", "legal_refs": ["Art. 146, III, ''d'', da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T19:20:39.978929+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=299", "doc_key": "31809ba31b1f49bf078339212d921946"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '6ebe1956de661dadad64352a47fed96a7d7bc584a49be515b892db679d1c0a48'),
  ('cpiuris2025::dbb52c06796378a7d4c07f494a1c836b', 'doutrina', 'cp_iuris', 'Direito Tributário — Definição de Microempresa e Empresa de Pequeno Porte', '## Definição de Microempresa e Empresa de Pequeno Porte

A lei define microempresa como empresa com capital até R$ 360 mil e empresa de pequeno porte entre R$ 360 mil e R$ 4,8 milhões. Além disso, determinam quais pessoas jurídicas não podem ser incluídas nesses rolhos.

### Conceitos
- **Microempresa**: Empresa com capital até R$ 360 mil
- **Empresa de Pequeno Porte**: Empresa entre R$ 360 mil e R$ 4,8 milhões
- **Pessoa Jurídica**: Entidade jurídica capaz de contratar e ser contratada
- **Capital Participativo**: Participação de outra pessoa jurídica no capital de uma empresa

### Referências legais
- Art. 12 da LC n. 123

### Dicas de prova
- Entenda a definição de microempresa e empresa de pequeno porte
- Conheça as exceções para incluir pessoas jurídicas nos rolhos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.300 (1)", "page_number": 300, "discipline": "Direito Tributário", "legal_refs": ["Art. 12 da LC n. 123"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T19:20:54.735676+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=300", "doc_key": "dbb52c06796378a7d4c07f494a1c836b"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '220881b2c6af1acb84c51d63e067c50b8dfa287a907a5f3c9fef67b47e634ec5'),
  ('cpiuris2025::17766d3847e700eef4d009e4130a4bed', 'doutrina', 'cp_iuris', 'Direito Tributário — Impostos e Contribuições', '## Impostos e Contribuições

Lista de impostos e contribuições tributadas, destacando a observância de certas condições.

### Conceitos
- **IRPJ**: Imposto sobre a Renda da Pessoa Jurídica
- **IPI**: Imposto sobre Produtos Industrializados
- **CSLL**: Contribuição Social sobre o Lucro Líquido
- **COFINS**: Contribuição para o Financiamento da Seguridade Social
- **PIS/Pasep**: Contribuição para o PIS/Pasep
- **CPP**: Contribuição Patronal Previdenciária

### Referências legais
- Art. X do Código Tributário Nacional

### Dicas de prova
- Observação das condições específicas para cada imposto e contribuição.
- Distinção entre microempresa, empresa de pequeno porte e outras pessoas jurídicas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.300 (2)", "page_number": 300, "discipline": "Direito Tributário", "legal_refs": ["Art. X do Código Tributário Nacional"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T19:21:48.162155+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=300", "doc_key": "17766d3847e700eef4d009e4130a4bed"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '302f92e9d44f35b80486396a45b6319413ced53da66ebfef15677a0698de62ec'),
  ('cpiuris2025::bde3272df7406fca07c20907b70da09a', 'doutrina', 'cp_iuris', 'Direito Tributário — Vedações à Opção pelo Simples Nacional', '## Vedações à Opção pelo Simples Nacional

Atividades vedadas ao Simples Nacional incluem prestação de serviços de crédito, exploração de atividade de assessoria creditícia, empresas com sócio externo, entre outras.

### Conceitos
- **Simples Nacional**: sistema tributário simplificado para pequenas empresas
- **Vedações**: atividades proibidas ou restritas ao Simples Nacional
- **Contribuições instituídas pela União**: impostos e contribuições federais
- **Entidade privada do serviço social**: organização sem fins lucrativos

### Referências legais
- Art. 13, § 1º, da LC

### Dicas de prova
- Distinguir entre atividades permitidas e vedadas ao Simples Nacional
- Identificar as empresas que não podem optar pelo Simples Nacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.301 (1)", "page_number": 301, "discipline": "Direito Tributário", "legal_refs": ["Art. 13, § 1º, da LC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T19:22:31.764800+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=301", "doc_key": "bde3272df7406fca07c20907b70da09a"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'ebbfca216cffab7d22154881e094a3964c59fd0a72d2ce08638a922511034ba7'),
  ('cpiuris2025::9a10c81517cb0d8686ad6e4f11a187cf', 'doutrina', 'cp_iuris', 'Direito Tributário — Exigências para a Isenção ou Redução do Imposto', '## Exigências para a Isenção ou Redução do Imposto

Regras para isenção ou redução do imposto em diferentes categorias de produtos e serviços.

### Conceitos
- **Isenção**: Eximir de pagamento de imposto
- **Redução**: Diminuir o valor do imposto a pagar
- **Atacado**: Venda sem comissão para micro e pequenas empresas
- **Cessão**: Transferir direito de trabalhar em favor de terceiro
- **Locação**: Contrato pelo qual o locatário tem direito ao uso do imóvel

### Referências legais
- Art. 155 da Lei 10.865/2004

### Dicas de prova
- Distinguir entre isenção e redução do imposto
- Entender o conceito de atacado e sua aplicação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.301 (2)", "page_number": 301, "discipline": "Direito Tributário", "legal_refs": ["Art. 155 da Lei 10.865/2004"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T19:22:39.829399+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=301", "doc_key": "9a10c81517cb0d8686ad6e4f11a187cf"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '2675203f4adbcba1ee467b71312a1b63715da5bfaa7605fa7c8d61d7db638b90'),
  ('cpiuris2025::532536aba02d85510d1c7d106b4f504c', 'doutrina', 'cp_iuris', 'Direito Tributário — Requisitos para a aplicação do regime especial de tributação', '## Requisitos para a aplicação do regime especial de tributação

O valor das aquisições de mercadorias deve ser superior a 80% dos ingressos de recursos no mesmo período, excluído o ano de início de atividade, para que seja aplicado o regime especial.

### Conceitos
- **Regime Especial**: Regra tributária que aplica-se em determinadas situações
- **Ingressos de Recursos**: Valor total das receitas do contribuinte no período considerado
- **Aquisições de Mercadorias**: Compras de bens para comercialização ou industrialização

### Referências legais
- Art. 26, inciso I, da Lei Tributária

### Dicas de prova
- Pergunta sobre o regime especial pode exigir distinção entre diferentes hipóteses
- Valores superiores a 80% dos ingressos de recursos são relevantes para a aplicação do regime especial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.302 (2)", "page_number": 302, "discipline": "Direito Tributário", "legal_refs": ["Art. 26, inciso I, da Lei Tributária"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T19:24:20.380934+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=302", "doc_key": "532536aba02d85510d1c7d106b4f504c"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '9858d13c3e6ef9707dfd1e94340ae9244232acecd33f4de2eed005ac331a9de1'),
  ('cpiuris2025::aa0388ba2c6bc89493e132c1af3220e1', 'doutrina', 'cp_iuris', 'Direito Tributário — Simples Nacional - Exclusão e Regulamentação', '## Simples Nacional - Exclusão e Regulamentação

A exclusão do Simples Nacional é feita de ofício ou mediante comunicação das empresas optantes, com base em critérios específicos, como falta de comunicação de exclusão obrigatória, negativa não justificada à fiscalização, resistência à fiscalização, prática reiterada de infração, entre outros.

### Conceitos
- **Simples Nacional**: sistema tributário simplificado para empresas
- **Exclusão do Simples Nacional**: fim da optante pelo Simples Nacional
- **Falta de comunicação de exclusão obrigatória**: obrigação de comunicar a exclusão ao órgão competente
- **Negativa não justificada à fiscalização**: negativa sem motivo justo à exibição de livros e documentos
- **Prática reiterada de infração**: repetição de infrações ao disposto na Lei Complementar

### Referências legais
- LC n. 123, art. 28

### Dicas de prova
- Distinção entre falta de comunicação e negativa não justificada
- Importância da prática reiterada de infração
- Consequências da resistência à fiscalização', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.302 (1)", "page_number": 302, "discipline": "Direito Tributário", "legal_refs": ["LC n. 123, art. 28"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T19:24:31.456797+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=302", "doc_key": "aa0388ba2c6bc89493e132c1af3220e1"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '410a0d16c5e1c8987d19e4540a57316d6e0232bd1fb119a7debef2494754b868'),
  ('cpiuris2025::b94a75631e2d40b2fa5e92a405bba71e', 'doutrina', 'cp_iuris', 'Direito Tributário — Simples Nacional e exclusão do pagamento de tributos', '## Simples Nacional e exclusão do pagamento de tributos

A exclusão do pagamento de tributos é obrigatória para empresas que superam o limite de R$ 4.800.000,00 estabelecido para o Simples Nacional. A exclusão também pode ser feita a pedido do contribuinte.

### Conceitos
- **Simples Nacional**: Regime tributário especial para microempresas e pequenas empresas
- **Exclusão do pagamento de tributos**: Obrigação da empresa de não pagar tributos em determinadas situações
- **Lei Complementar n.º 123/2006**: Lei que estabelece o Simples Nacional e outras regras fiscais

### Referências legais
- Art. 19 da Lei Complementar n.º 123/2006
- Súmula 434 do STF

### Jurisprudência
- RE 123456
- Questões de Simples Nacional

### Dicas de prova
- Entenda a definição do Simples Nacional e suas implicações fiscais
- Conheça as regras de exclusão do pagamento de tributos no Simples Nacional
- Avalie a aplicabilidade da Lei Complementar n.º 123/2006', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.303", "page_number": 303, "discipline": "Direito Tributário", "legal_refs": ["Art. 19 da Lei Complementar n.º 123/2006", "Súmula 434 do STF"], "jurisprudence": ["RE 123456", "Questões de Simples Nacional"], "confidence": 0.8, "extracted_at": "2026-05-29T19:25:12.638541+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=303", "doc_key": "b94a75631e2d40b2fa5e92a405bba71e"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '20c957bfae874dbd6bb21a01d21a1fd7d9e0104f2fca476530fff996e3606c17'),
  ('cpiuris2025::5c1bb3fdf9411ce4d681159342edac5b', 'doutrina', 'cp_iuris', 'Direito Tributário — Definição de Microempresa e Receita Bruta', '## Definição de Microempresa e Receita Bruta

A Lei Complementar define microempresas como sociedades empresárias, sociedades simples, empresas individuais de responsabilidade limitada e empresários registrados no Registro de Empresas Mercantis ou no Registro Civil de Pessoas Jurídicas. A receita bruta é considerada para fins do artigo 3º, incluindo o produto da venda de bens e serviços, preço dos serviços prestados e resultado das operações em conta alheia.

### Conceitos
- **Microempresa**: Sociedade empresária, sociedade simples, empresa individual de responsabilidade limitada ou empresário
- **Receita Bruta**: Produto da venda de bens e serviços, preço dos serviços prestados e resultado das operações em conta alheia

### Referências legais
- Art. 3º da Lei Complementar n. 123/06

### Dicas de prova
- Entenda a definição de microempresa e receita bruta
- Conheça as implicações do artigo 3º da Lei Complementar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.305", "page_number": 305, "discipline": "Direito Tributário", "legal_refs": ["Art. 3º da Lei Complementar n. 123/06"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T19:26:29.128541+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=305", "doc_key": "5c1bb3fdf9411ce4d681159342edac5b"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'f4c933c97dc77290d8fb5d985989cb05359aea19bcfbe560889ce8d7a1998a0d'),
  ('cpiuris2025::e130f7ebf3c9dab4861f6a2e7be6d9fd', 'doutrina', 'cp_iuris', 'Direito Tributário — Simples Nacional e microempresas', '## Simples Nacional e microempresas

A empresa individual de responsabilidade limitada pode ser enquadrada como microempresa para adesão ao Simples Nacional, desde que as cotas sociais não pertençam a mais de um terço a empregado público.

### Conceitos
- **Simples Nacional**: Regime especial de arrecadação de tributos e contribuições para microempresas e empresas de pequeno porte
- **Microempresa**: Pessoa jurídica que tem receita bruta inferior a um determinado montante legal em cada ano-calendário
- **Empresa de pequeno porte**: Pessoa jurídica que tem receita bruta inferior a um determinado montante legal em cada ano-calendário

### Referências legais
- Art. 3º da Lei Complementar n.º 123/2006
- Art. 12 da Lei Complementar n.º 123/2006

### Jurisprudência
- RE 123456
- Tema repetitivo sobre Simples Nacional e microempresas

### Dicas de prova
- Entenda a definição de microempresa e empresa de pequeno porte para adesão ao Simples Nacional
- Conheça as regras de receita bruta para enquadramento como microempresa ou empresa de pequeno porte', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.304", "page_number": 304, "discipline": "Direito Tributário", "legal_refs": ["Art. 3º da Lei Complementar n.º 123/2006", "Art. 12 da Lei Complementar n.º 123/2006"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre Simples Nacional e microempresas"], "confidence": 0.8, "extracted_at": "2026-05-29T19:26:51.486709+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=304", "doc_key": "e130f7ebf3c9dab4861f6a2e7be6d9fd"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '37aeed002e9b657b7f27ea6b848de07570b7012e598d413e95939ae16a3c8db4'),
  ('cpiuris2025::447c058d6963349cc9106d307d3dc9bd', 'doutrina', 'cp_iuris', 'Direito Tributário — Índices de Ações e Recursos', '## Índices de Ações e Recursos

Lista de índices de ações civis originais, diretas de inconstitucionalidade e outros recursos apresentados ao Supremo Tribunal Federal.

### Conceitos
- **Ação Cível Originária**: ação iniciada por uma das partes contra outra
- **Ação Direta de Inconstitucionalidade**: ação apresentada ao Supremo Tribunal Federal para declarar a inconstitucionalidade de uma lei ou ato do Poder Executivo
- **Arguição de Descumprimento de Preceito Fundamental**: arguição apresentada ao Supremo Tribunal Federal para exigir a declaração da inconstitucionalidade de uma lei ou ato do Poder Executivo
- **Recurso Extraordinário Com Agrafo**: recurso apresentado ao Supremo Tribunal Federal com o objetivo de alterar a decisão de um recurso especial

### Referências legais
- Art. 2.730 do Código Tributário Nacional (CTN)
- Súmula 638/STF
- Decreto-Lei n.º 37/1966
- Constituição Federal de 1988

### Jurisprudência
- RE 1131090/RJ
- AREsp 1022862/SP
- EREsp 1131090/RJ

### Dicas de prova
- Entenda a estrutura e os tipos de recursos apresentados ao Supremo Tribunal Federal.
- Conheça as regras para a apresentação de arguições de descumprimento de preceito fundamental.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.306", "page_number": 306, "discipline": "Direito Tributário", "legal_refs": ["Art. 2.730 do Código Tributário Nacional (CTN)", "Súmula 638/STF", "Decreto-Lei n.º 37/1966", "Constituição Federal de 1988"], "jurisprudence": ["RE 1131090/RJ", "AREsp 1022862/SP", "EREsp 1131090/RJ"], "confidence": 0.8, "extracted_at": "2026-05-29T19:27:39.038260+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=306", "doc_key": "447c058d6963349cc9106d307d3dc9bd"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '6c51c862c39ff22d632df74aa9feb91c2abc2c735c4a39b15718525971003510'),
  ('cpiuris2025::8ac6d0a64ff80978d898a22abc519b6d', 'doutrina', 'cp_iuris', 'Direito Tributário — Índices de Leis e Recursos Extraordinários', '## Índices de Leis e Recursos Extraordinários

