  ('cpiuris2025::275b48210a2db582a9d06dfc02fbe207', 'doutrina', 'cp_iuris', 'Direito Tributário — Índices de Súmulas e Temas', '## Índices de Súmulas e Temas

Lista de súmulas e temas organizados por número, indicando as súmulas vinculantes e os temas específicos abordados.

### Conceitos
- **Súmula Vinculante**: súmula do STF que tem foro de direito e é aplicada por todos os juízes
- **Índice**: lista organizada de súmulas e temas para facilitar a busca e localização de determinado assunto

### Referências legais
- Art. 93 da CF/88

### Jurisprudência
- RE 123456
- Súmula n.º 395
- Súmula n.º 397

### Dicas de prova
