- Conheça os índices de súmulas e temas para localizar rapidamente determinado assunto.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.309", "page_number": 309, "discipline": "Direito Tributário", "legal_refs": ["Art. 93 da CF/88"], "jurisprudence": ["RE 123456", "Súmula n.º 395", "Súmula n.º 397"], "confidence": 0.8, "extracted_at": "2026-05-29T19:30:23.877100+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=309", "doc_key": "275b48210a2db582a9d06dfc02fbe207"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '90cdcbfc8b0f16b8467482dee551434b11447891a87c5190ac557d4f7fd6c23d'),
  ('cpiuris2025::d798b53a0302894024e15b5395c31bef', 'doutrina', 'cp_iuris', 'Direito Tributário — Índice de Recursos Especiais e Súmulas STF/STJ', '## Índice de Recursos Especiais e Súmulas STF/STJ

