  ('cpiuris2025::54db5ce2420d302131fc7a4939ec2b50', 'doutrina', 'cp_iuris', 'Direito da Criancça e do Adolescente — Poder Familiar', '## Poder Familiar

O poder familiar refere-se ao direito das famílias, incluindo a perda ou suspensão desse direito. O processo judicial e o contraditório são fundamentais para essa questão.

### Conceitos
- **Poder Familiar**: direito das famílias
- **Perda de Poder Familiar**: ocorrência que resulta na perda do direito familiar
- **Suspensão de Poder Familiar**: ocorrência que resulta na suspensão do direito familiar

### Referências legais
- Art. 1.634 CC/2002
- Súmula 342 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Poder Familiar

