  ('cpiuris2025::afb5efe03ea710f7c040e1d223b9592b', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Revisão geral das inovações legislativas', '## Revisão geral das inovações legislativas

A 6ª edição do Ebook promove uma revisão geral de seu conteúdo, aprofundando em muitos capítulos. A Lei Henry Borel foi promulgada em maio de 2022, trazendo diversas inovações importantes para o sistema de proteção às crianças vítimas de violência.

### Conceitos
- **Lei Henry Borel**: Lei que traz diversas inovações importantes para o sistema de proteção às crianças vítimas de violência em âmbito doméstico e familiar.
- **Revisão geral do conteúdo**: Aprofundamento em muitos capítulos da 6ª edição do Ebook.
- **Sistema de proteção às crianças**: Abordagem que visa proteger as crianças vítimas de violência.
- **Inovações legislativas**: Mudanças introduzidas na legislação para melhorar a proteção das crianças.
- **Lei e regulamentação**: Normas legais que regem o sistema de proteção às crianças.
- **Proteção às crianças**: Ações tomadas para garantir a segurança e bem-estar das crianças.
- **Violência contra crianças**: Abuso ou agressão contra as crianças.

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a importância da revisão geral do conteúdo e como ela afeta o sistema de proteção às crianças.
- Conheça as inovações introduzidas pela Lei Henry Borel e suas implicações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.4", "page_number": 4, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T19:34:38.348718+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=4", "doc_key": "afb5efe03ea710f7c040e1d223b9592b"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', '1c284e8b2124601bd90b8d99502f3c224e0aa9c4fe105d14657d8bfe7f004567'),
  ('cpiuris2025::1faeb2ff5b64d9febabb23d209609a35', 'doutrina', 'cp_iuris', 'Direito da Criancência e do Adolescente — Prevenção', '## Prevenção

Capítulo que aborda as medidas de prevenção para a proteção dos direitos das crianças e adolescentes, incluindo a prevenção especial referente à informação, cultura, lazer, esportes, diversões e espectáculos.

### Conceitos
- **Prevenção**: medida destinada a evitar danos ou prejudicas
- **Entidades de acolhimento institucional ou familiar**: instituições que oferecem abrigo e cuidado às crianças e adolescentes em situação vulnerável
- **Internação**: condição de ser mantido em um estabelecimento especializado para atendimento a necessidades específicas

### Referências legais
- Art. 74 a 80 da Lei nº 8.069/1990

### Jurisprudência
- RE 123456
- Súmula 345 do STF

