  ('cpiuris2025::76cff42d909bc420a35c10b51939686b', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Medidas pertinentes aos pais e responsáveis', '## Medidas pertinentes aos pais e responsáveis

