- **Garantias Processuais**: direito dos menores à liberdade condicional ou à suspensão da pena
- **Medidas Socioeducativas**: medidas alternativas ao encarceramento, como educação e reabilitação

### Referências legais
- Art. 8º da Lei nº 11.340/2006

