  ('cpiuris2025::b723eb69f6a0b403bf9b0a9b8bf2299b', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Noções Preliminares', '## Noções Preliminares

Discute as noções iniciais sobre a proteção dos direitos das crianças e adolescentes.

### Conceitos
- **Poder familiar**: O poder de um pai ou mãe para tomar decisões sobre o bem-estar da criança.
- **Tutela**: A proteção jurídica que as autoridades públicas e privadas exercem sobre a pessoa menor.
- **Família substituta**: Uma família que cuida de um menor após o término do poder familiar ou em caso de ausência do pai ou mãe.
- **Habilitação dos pretendentes à adoção**: O processo pelo qual os pais ou guardiões são substituídos por outros para cuidar da criança.
- **Entidade de atendimento**: Organização que fornece assistência e apoio às crianças e adolescentes.
- **Infiltração policial**: A ação de policiais infiltrados em entidades de atendimento para investigar crimes contra a dignidade sexual de criança e adolescente.
- **Ato infracional**: Um comportamento que viola as leis, mas não é considerado crime.

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a definição de poder familiar e tutela.
- Conheça as diferenças entre família substituta e entidade de atendimento.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.7 (1)", "page_number": 7, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T19:37:10.078064+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=7", "doc_key": "b723eb69f6a0b403bf9b0a9b8bf2299b"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', 'b3f738c1f1bf4c5728b058b1bb7d98c13e1bfd488ce69fd53c1095aa693c8d9f'),
