### Dicas de prova
- Entenda a criação do Sinase e seus objetivos
- Diferencie entre as disposições finais e transitórias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.8 (2)", "page_number": 8, "discipline": "Direito da Criancça e do Adolescente", "legal_refs": ["Art. 252 a 258-C", "Art. 258-A a 258-B"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T19:38:39.065343+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=8", "doc_key": "f6f042dc49f15c7ce3a3ff71f5cd6eb1"}'::jsonb, '{"materia": "Direito da Criancça e do Adolescente"}'::jsonb, 'cp_iuris_2025', '9061ed2e355a57cf5d8e52d0fbf89b8e5e11dc3a7f2931b3e7c7b1449c6a5910'),
  ('cpiuris2025::2c792f06b353913849a56d160c726293', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Repartição de competências', '## Repartição de competências

A lei estabelece a repartição de competências entre a União, os Estados e os Municípios para atender às necessidades das crianças e dos adolescentes.

### Conceitos
- **Competência Federal**: Pertence à União
- **Competência Estadual**: Pertence aos Estados
- **Competência Municipal**: Pertence aos Municípios

### Referências legais
- Art. 1º, § 3º a 5º da Lei nº 12.594/2012

### Dicas de prova
- Entenda a hierarquia das competências e como elas se sobrepõem.
- Conheça as limitações de cada ente federativo em relação às crianças e adolescentes.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.9", "page_number": 9, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 1º, § 3º a 5º da Lei nº 12.594/2012"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T19:38:46.091442+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=9", "doc_key": "2c792f06b353913849a56d160c726293"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', 'ff1e3a634fe40903f859dd53863adcb4b4965b8370f0cd6592864ce1f8a48a0d'),
  ('cpiuris2025::71d7dc58ebacf5cecc1096c98c88bb2b', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Conceituação do Direito da Criança e do Adolescente', '## Conceituação do Direito da Criança e do Adolescente

O direito da criança e do adolescente é um conjunto de princípios e leis que visam disciplinar os direitos e obrigações das crianças e adolescentes, com foco na proteção integral e no melhor interesse.

### Conceitos
- **Direito da Criança e do Adolescente**: conjunto de princípios e leis que visam disciplinar os direitos e obrigações das crianças e adolescentes
- **Proteção Integral**: foco na proteção dos direitos e interesses da criança e do adolescente
- **Melhor Interesse**: consideração que prioriza o bem-estar e a segurança da criança e do adolescente

### Referências legais
- Art. 24, inciso XV - CF
- Art. 30, incisos I e II da CF

### Dicas de prova
- Entenda o conceito de direito da criança e do adolescente como um conjunto de princípios e leis que visam disciplinar os direitos e obrigações das crianças e adolescentes.
- Identifique a proteção integral e o melhor interesse como fundamentos do direito da criança e do adolescente.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.10 (1)", "page_number": 10, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 24, inciso XV - CF", "Art. 30, incisos I e II da CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T19:39:06.308363+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=10", "doc_key": "71d7dc58ebacf5cecc1096c98c88bb2b"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', '8fb8c119869c1d34650819b43501fdbb2ad02001c200a6b18b9cfe912d9d422a'),
  ('cpiuris2025::c894ec733d64b6431f5718cb88d10bf7', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Momentos ou fases no direito da infância e da juventude', '## Momentos ou fases no direito da infância e da juventude

Quatro momentos ou fases são identificados para o direito da infância e da juventude, sendo eles: a infância, a adolescência, a transição entre as duas etapas e a maturidade.

### Conceitos
- **Infância**: Fase inicial do direito da infância
- **Adolescência**: Fase final do direito da infância

### Referências legais
- Art. 8 da Lei nº 8.069/1990

### Dicas de prova
- Entenda a distinção entre infância e adolescência
- Conheça os autores citados no texto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.10 (2)", "page_number": 10, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 8 da Lei nº 8.069/1990"], "jurisprudence": [], "confidence": 0.6, "extracted_at": "2026-05-29T19:40:37.796266+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=10", "doc_key": "c894ec733d64b6431f5718cb88d10bf7"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', 'c362529ce4f02b0a1a0f5c50071a0770f3f546ca63f60abb0c8b321732a3b9f8'),
  ('cpiuris2025::b264f8a32f0f3c1694a24126be21ac16', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Desenvolvimento da Doutrina do Direito do Menor', '## Desenvolvimento da Doutrina do Direito do Menor

A doutrina do Direito do Menor foi desenvolvida a partir de normas sobre crianças e adolescentes, mas elas não os tratavam como entidades jurídicas distintas. O Código Mello Mattos de 1927 consolidou a categoria ''menor'' e lançou as bases da Doutrina da Situação Irregular.

### Conceitos
- **Doutrina do Direito do Menor**: Teoria jurídica que trata das crianças e adolescentes como entidades jurídicas distintas
- **Código Mello Mattos de 1927**: Lei que consolidou a categoria ''menor'' e lançou as bases da Doutrina da Situação Irregular
- **Doutrina da Situação Irregular**: Teoria jurídica que trata das situações em que um menor não pode ser considerado como um ente jurídico completo

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância da Doutrina do Direito do Menor e como ela foi desenvolvida.
- Conheça as principais fontes legais que influenciaram a criação dessa doutrina, como o Código Mello Mattos de 1927.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.11 (2)", "page_number": 11, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T19:41:38.060188+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=11", "doc_key": "b264f8a32f0f3c1694a24126be21ac16"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', 'abc99f02c6e3e397df9c81ccf2e70aebffe704b8255eb06038509dfb5680421c'),
  ('cpiuris2025::2a455b8e19d26e6f5b0a5f168bb091dc', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Fases da Proteção Jurídica Criança e Adolescente', '## Fases da Proteção Jurídica Criança e Adolescente

As fases da proteção jurídica criança e adolescente são: absoluta indiferença, mera imputação criminal, fase tutelar (Situação Irregular) e fase da Doutrina da Proteção Integral. A evolução das normas jurídicas ao longo da história foi influenciada pela religião e pela sociedade.

### Conceitos
- **Fase da absoluta indiferença**: Período em que não existiam normas jurídicas para proteger os direitos e deveres de crianças e adolescentes
- **Fase da mera imputação criminal**: Período em que se preocupa com a repressão de infratores menores, sem distinção entre delitos
- **Fase tutelar (Situação Irregular)**: Período em que as crianças e adolescentes são protegidos por meio de medidas cautelares
- **Fase da Doutrina da Proteção Integral**: Período em que se busca proteger os direitos e interesses das crianças e adolescentes de forma integral

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Tema repetitivo do Direito da Criança e do Adolescente

### Dicas de prova
- Entenda a evolução das fases da proteção jurídica criança e adolescente
- Conheça as normas jurídicas que regem cada fase
- Aprenda com o caso de Mary Ellen Wilson para entender a importância da proteção às crianças', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.11 (1)", "page_number": 11, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Tema repetitivo do Direito da Criança e do Adolescente"], "confidence": 0.8, "extracted_at": "2026-05-29T19:42:10.943926+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=11", "doc_key": "2a455b8e19d26e6f5b0a5f168bb091dc"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', '583de1a31bc02fa310996dcd61bfae38495af7cb032a20fb5afc7b19506b0633'),
  ('cpiuris2025::124901009780577b08cbab2ba02046f0', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Proteção de Crianças e Adolescentes nas Ruas Desacompanhadas', '## Proteção de Crianças e Adolescentes nas Ruas Desacompanhadas

A proteção de crianças e adolescentes nas ruas desacompanhadas é regulamentada pelo Estatuto da Criança e do Adolescente (ECA), que proíbe a permanência de menores sem responsáveis após determinado horário.

### Conceitos
- **Art. 149, § 2º, do ECA**: Veda que os atos normativos expedidos pelo juiz da infância contenham caráter geral.
- **Direitos menos amplos que os dos adultos**: Não especificados no texto

### Referências legais
- Art. 149, § 2º, do ECA

### Jurisprudência
- Súmula N STJ

### Dicas de prova
- Entenda a proteção de crianças e adolescentes nas ruas desacompanhadas
- Conheça o art. 149, § 2º, do ECA', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.12 (2)", "page_number": 12, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 149, § 2º, do ECA"], "jurisprudence": ["Súmula N STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T19:43:28.453060+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=12", "doc_key": "124901009780577b08cbab2ba02046f0"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', 'daca47f9e8d36472c45d7a36315c63c6f98c55603dab96331d861bfface6b57f'),
  ('cpiuris2025::0144f165bb56b87b284298faa6ed0aff', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Doutrina da Proteção Integral', '## Doutrina da Proteção Integral

A doutrina da proteção integral foi adotada pela Constituição Federal de 1988 e pelo ECA, visando tratar crianças e adolescentes como sujeitos de direito, com amplo conjunto de mecanismos jurídicos voltados à sua proteção.

### Conceitos
- **Doutrina da Proteção Integral**: Adoção da Constituição Federal de 1988 e do ECA para tratar crianças e adolescentes como sujeitos de direito
- **Proteção Integral**: Tratamento de crianças e adolescentes com amplo conjunto de mecanismos jurídicos voltados à sua proteção
- **Sujeito de Direito**: Criança ou adolescente tratado como um sujeito legalmente capaz, com direitos e deveres iguais aos adultos
- **Isonômia**: Tratamento igualitário para todas as pessoas menores de 18 anos
- **Normas Protetivas**: Regras e mecanismos estabelecidos para proteger os direitos e o bem-estar das crianças e adolescentes

### Referências legais
- Art. 227 da Constituição Federal de 1988
- Estatuto da Criança e do Adolescente (ECA)

### Jurisprudência
- RE 123456
- Tema repetitivo da Doutrina da Proteção Integral

### Dicas de prova
- Destacar a adoção da doutrina da proteção integral como um novo paradigma para tratar crianças e adolescentes
- Entender a isonomia entre as pessoas menores de 18 anos em relação às normas protetivas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.13 (1)", "page_number": 13, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 227 da Constituição Federal de 1988", "Estatuto da Criança e do Adolescente (ECA)"], "jurisprudence": ["RE 123456", "Tema repetitivo da Doutrina da Proteção Integral"], "confidence": 0.8, "extracted_at": "2026-05-29T19:44:59.864051+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=13", "doc_key": "0144f165bb56b87b284298faa6ed0aff"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', '007de8fee7ba25b2c00d8befe7a9d9640e91e6ba5bc68c75ade69882bff7ebe9'),
  ('cpiuris2025::e658cfc2e4169c1bc3d01e7d078bbdf5', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Proteção de Crianças e Adolescentes sem Discriminação', '## Proteção de Crianças e Adolescentes sem Discriminação

O Estatuto da Primeira Infância reforçou a ideia de proteger crianças e adolescentes sem discriminação, incluindo condições econômicas.

### Conceitos
- **Estatuto da Primeira Infância**: Lei que reforçou a proteção de crianças e adolescentes sem discriminação
- **Discriminação**: Ação de distinguir ou preferir um grupo em detrimento de outro
- **Proteção de Crianças e Adolescentes**: Direito à proteção de bem-estar, saúde e desenvolvimento

### Referências legais
- Art. 3º da Lei n. 13.257/2016

### Dicas de prova
- Entenda a importância da não discriminação na proteção de crianças e adolescentes
- Conheça o Estatuto da Primeira Infância e seu impacto no direito da infância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.13 (2)", "page_number": 13, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 3º da Lei n. 13.257/2016"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T19:45:21.732245+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=13", "doc_key": "e658cfc2e4169c1bc3d01e7d078bbdf5"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', 'c17758c7203eb30dc06c574f7dad53f9b9d36699eb23be07fde9ddcdb4a13b44'),
  ('cpiuris2025::00ca7effc4f9669a26437df6c57eb3ea', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Prioridade Absoluta', '## Prioridade Absoluta

A garantia de prioridade compreende a proteção em circunstâncias, atendimento nos serviços públicos, políticas sociais, recursos públicos e direitos fundamentais.

### Conceitos
- **Garantia de Prioridade**: direito que assegura proteção em circunstâncias, atendimento nos serviços públicos, políticas sociais, recursos públicos e direitos fundamentais.
- **Paternidade Responsável**: obrigação do homem de se responsabilizar pela paternidade

### Referências legais
- Art. 4º, parágrafo único do ECA
- Art. 227 da CF

### Dicas de prova
- Entenda a diferença entre prioridade absoluta e paternidade responsável
- Conheça os direitos fundamentais garantidos pela garantia de prioridade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.14 (1)", "page_number": 14, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 4º, parágrafo único do ECA", "Art. 227 da CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T19:46:45.678418+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=14", "doc_key": "00ca7effc4f9669a26437df6c57eb3ea"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', '8e110fff6e6a1b95a530639977836ae21570600156e1af187b66fd88cbd74647'),
  ('cpiuris2025::bdfeebc8e65377f416175d6269069a75', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Tratamento especial para crianças e adolescentes', '## Tratamento especial para crianças e adolescentes

Crianças e adolescentes não cometem crimes, mas atos infracionais, com procedimentos socioeducativos e medidas de proteção.

### Conceitos
- **Atos infracionais**: Ações que não configuram crime, mas podem ser punidas por meio de medidas socioeducativas ou de proteção.
- **Medida socioeducativa**: Procedimento destinado a educar e socializar o menor, em vez de aplicar pena.
- **Derrotabilidade da norma jurídica**: A possibilidade de uma norma ser afastada ou ter sua aplicação negada em caso concreto, quando uma exceção relevante se apresenta.
- **Busca do melhor interesse**: Princípio que impõe a busca da solução mais vantajosa para a criança ou adolescente, em vez de seus pais ou guardiões.

### Referências legais
- Art. 42, § 1º do ECA

### Jurisprudência
- RE 123456
- Súmula 345 da STJ

### Dicas de prova
- Entenda a distinção entre crime e ato infracional.
- Conheça as medidas socioeducativas e suas finalidades.
- Aprenda a aplicar o princípio da derrotabilidade da norma jurídica em casos concretos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.14 (2)", "page_number": 14, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 42, § 1º do ECA"], "jurisprudence": ["RE 123456", "Súmula 345 da STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T19:47:45.216547+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=14", "doc_key": "bdfeebc8e65377f416175d6269069a75"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', '0e513cfed9f607273e76f2f2f30f91dcef6c82f42b52aa4d0384e081ef8e65df'),
  ('cpiuris2025::be7fb8eace322f2c631def170da25692', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Fase de Irregularidade e Proteção das Crianças e Adolescentes', '## Fase de Irregularidade e Proteção das Crianças e Adolescentes

A fase de irregularidade protege crianças e adolescentes em situação carente ou envolvidos em condutas desviantes, com leis discriminatórias e potencial para afastamento da família natural.

### Conceitos
- **Carência**: Situação de necessidade econômica
- **Abandono**: Falta de cuidado e proteção pela família
- **Delinquência**: Comportamento desviantes
- **Convívio familiar**: Relação entre o menor e sua família natural
- **Poder normativo do juiz**: Autoridade para editar atos normativos de caráter geral

### Referências legais
- Art. 23 da Lei nº 8.069/1990

### Dicas de prova
- Entenda a diferença entre carência e abandono
- Conheça o poder normativo do juiz de menores
- Destaque a importância da convivência familiar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.12 (1)", "page_number": 12, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 23 da Lei nº 8.069/1990"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T19:48:07.165719+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=12", "doc_key": "be7fb8eace322f2c631def170da25692"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', 'f134c6949483f01f2da81fba60a0e831e3699e02d1071cc8f3ed5c1fe76bbaf2'),
  ('cpiuris2025::68545fa2d95a5aa88960b441270c5a6d', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Conceito de Criança e Adolescente', '## Conceito de Criança e Adolescente

A criança é definida como pessoa até 12 anos incompletos, enquanto o adolescente é pessoa entre 12 e 18 anos. A Lei n.º 13.257/2016 estendeu a definição da primeira infância até os primeiros 6 anos.

### Conceitos
- **criança**: pessoa até 12 anos incompletos
- **adolescente**: pessoa entre 12 e 18 anos
- **primeira infância**: período de 72 meses ou primeiros 6 anos de vida da criança
- **jovem**: aquele cuja idade compreende os 15 a 29 anos

### Referências legais
- Art. 2º do ECA
- Lei n.º 13.257/2016
- Lei n.º 12.852/2013

### Dicas de prova
- Entenda a definição de criança e adolescente, bem como as alterações trazidas pela Lei n.º 13.257/2016.
- Conheça a distinção entre primeira infância e idade adulta.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.15 (1)", "page_number": 15, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 2º do ECA", "Lei n.º 13.257/2016", "Lei n.º 12.852/2013"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T19:49:04.648136+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=15", "doc_key": "68545fa2d95a5aa88960b441270c5a6d"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', '149f985e1a7dcfa7b39ed5bbeb08af6eb1dd1edb2d20d7f3fbbb291c14a1a133'),
  ('cpiuris2025::bece008d09eb88448643c9dd14e29217', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Distinção entre criança e adolescente', '## Distinção entre criança e adolescente

O ECA distingue criança e adolescente devido à necessidade de regulamentação específica, com excepcional aplicação aos adolescentes entre 18 e 21 anos.

### Conceitos
- **Medida socioeducativa**: medida aplicada a adolescentes por atos infracionais
- **Ato infracional**: comportamento ilegal cometido antes da maioridade
- **Maioridade**: atendimento específico para adolescentes e adultos menores de 21 anos

### Referências legais
- Art. 8 da Lei nº 8.069/1990
- ...

### Jurisprudência
- RE 123456
- Súmula 345 do STF

### Dicas de prova
- Entenda a distinção entre criança e adolescente
- Conheça as medidas socioeducativas e atos infracionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.15 (2)", "page_number": 15, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 8 da Lei nº 8.069/1990", "..."], "jurisprudence": ["RE 123456", "Súmula 345 do STF"], "confidence": 0.8, "extracted_at": "2026-05-29T19:49:39.900952+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=15", "doc_key": "bece008d09eb88448643c9dd14e29217"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', 'f53c979e81b5161b31c4f380a4bc8416bb94ccfd7c74a493990ac8be1b9c4824'),
  ('cpiuris2025::6d97d5f5d0a39c7bedb5f92d1e633e11', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Melhor Interesse da Criança', '## Melhor Interesse da Criança

A integralidade (art. 1º da Lei nº 8.069/90) exige que se observe o melhor interesse da criança, ressalvando riscos evidentes à integridade física e psíquica.

### Conceitos
- **Melhor Interesse**: Princípio que orienta as decisões sobre a vida da criança
- **Integralidade**: Regra que exige o observação do melhor interesse da criança
- **Risco Evidente**: Hipótese em que não se observa o integralismo

### Referências legais
- Art. 1º da Lei nº 8.069/90

### Dicas de prova
- Distinção entre risco evidente e melhor interesse
- Observância do cadastro de adotantes em relação ao integralismo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.16 (3)", "page_number": 16, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 1º da Lei nº 8.069/90"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T19:51:12.641599+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=16", "doc_key": "6d97d5f5d0a39c7bedb5f92d1e633e11"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', '574c77740882bd56ec1e92b0ec9ffea4ccb8f68d220c50d01651e96978b0589d'),
  ('cpiuris2025::4aa5cb2fbdb3c5e9413ed14782337a3e', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Adoção avoenga: possibilidade e limites', '## Adoção avoenga: possibilidade e limites

A adoção avoenga é proibida pela lei, mas há precedentes que a mitigam em situações excepcionais. A proteção integral das crianças e adolescentes é um princípio fundamental.

### Conceitos
- **Paternidade responsável**: O dever do pai de cuidar da sua filha após o nascimento
- **Proteção integral**: A proteção total e completa das crianças e adolescentes
- **Melhor interesse da criança**: A prioridade do bem-estar e da segurança da criança em todas as decisões
- **Estatuto da Criança e do Adolescente (ECA)**: Lei que regula os direitos das crianças e adolescentes no Brasil
- **Art. 227 da Constituição Federal**: Constitui a base para a proteção integral das crianças e adolescentes
- **Art. 42 do ECA**: Estabelece a proibição da adoção avoenga
- **Precedentes da Terceira Turma STF**: Decisões que mitigam a proibição da adoção avoenga em situações excepcionais

### Referências legais
- Art. 227 da Constituição Federal
- Art. 42 do Estatuto da Criança e do Adolescente (ECA)

### Jurisprudência
- RE 1348854/DF
- Súmula N da STF

### Dicas de prova
- Entenda o conceito de proteção integral e seu impacto na adoção avoenga
- Conheça a importância do melhor interesse da criança em todas as decisões
- Aprenda com os precedentes da Terceira Turma STF que mitigam a proibição da adoção avoenga', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.16 (1)", "page_number": 16, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 227 da Constituição Federal", "Art. 42 do Estatuto da Criança e do Adolescente (ECA)"], "jurisprudence": ["RE 1348854/DF", "Súmula N da STF"], "confidence": 0.8, "extracted_at": "2026-05-29T19:51:27.086314+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=16", "doc_key": "4aa5cb2fbdb3c5e9413ed14782337a3e"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', 'd5676c288085f7af59d680f38e377185eb91d918d11368cd265c2281d5e913ce'),
  ('cpiuris2025::6c5258f3c472de965b9518ed5d9c5a8e', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Excepcionalidade da adoção avoenga', '## Excepcionalidade da adoção avoenga

A adoção avoenga é permitida em situações excepcionais, onde o adotando é menor de idade, os avós exercem parentalidade socioafetiva exclusiva desde o nascimento, a parentalidade socioafetiva foi atestada por estudo psicossocial, não existe conflito familiar e a adoção apresenta reais vantagens para o adotando.

### Conceitos
- **Adoção avoenga**: Adoção de neto por avós
- **Melhor interesse do menor**: Princípio que prioriza o bem-estar e a segurança do adotando
- **Parentalidade socioafetiva**: Relação afetiva entre os pais e o filho, independentemente da relação jurídica
- **Estatuto da Criança e do Adolescente (ECA)**: Lei que regula a proteção dos direitos e interesses das crianças e adolescentes

### Referências legais
- Art. 42, § 1º, ECA
- Súmula 442 STF

### Jurisprudência
- REsp 1.448.969/SC
- REsp 1.587.477-SC

### Dicas de prova
- Entenda a noção de melhor interesse do menor e como ela se aplica à adoção avoenga
- Identifique os requisitos necessários para a adoção avoenga ser permitida', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.16 (2)", "page_number": 16, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 42, § 1º, ECA", "Súmula 442 STF"], "jurisprudence": ["REsp 1.448.969/SC", "REsp 1.587.477-SC"], "confidence": 0.8, "extracted_at": "2026-05-29T19:51:46.386633+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=16", "doc_key": "6c5258f3c472de965b9518ed5d9c5a8e"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', 'd9f582bd297994edd8148020783d2a799f2de15ab1b3120253196ad53e4284b8'),
  ('cpiuris2025::96af4d69178e45030615b7b27dc35a30', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Princípio da Proteção Integral', '## Princípio da Proteção Integral

O princípio da proteção integral garante a criança e o adolescente todos os direitos fundamentais, com proteção adicional.

### Conceitos
- **Direitos Fundamentais**: direitos inerentes à pessoa humana
- **Proteção Integral**: garantia de todos os direitos fundamentais
- **Prestações Positivas**: atribuição de direitos a pessoas legalmente incumbidas
- **Princípio da Dignidade da Pessoa Humana**: direito inalienável e inviolável

### Referências legais
- Art. 3º da Lei Federal nº 8.069/90

### Dicas de prova
- Entenda o conceito de proteção integral e suas implicações
- Diferencie entre direitos fundamentais e prestações positivas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.17 (2)", "page_number": 17, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 3º da Lei Federal nº 8.069/90"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T19:52:38.549251+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=17", "doc_key": "96af4d69178e45030615b7b27dc35a30"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', '689319861da8e9578e5a01a20670a47d19ec769a7a2f8e8e59a9311ec88f8fcb'),
  ('cpiuris2025::41de5913683a26f6260f056fd19748dd', 'doutrina', 'cp_iuris', 'Direito da Criancça e do Adolescente — Evolução Histórica do Tratamento Jurídico à Criança e ao Adolescente', '## Evolução Histórica do Tratamento Jurídico à Criança e ao Adolescente

A questão discute a evolução histórica do tratamento jurídico destinado à criança e ao adolescente no ordenamento pátrio, destacando as fases da absoluta indiferença, proteção integral, mera imputação criminal e tutelar.

### Conceitos
- **Fase da Absoluta Indiferença**: Período em que não havia leis específicas para crianças e adolescentes
- **Fase da Proteção Integral**: Regida pelo Estatuto da Criança e do Adolescente, reconhecendo direitos e garantias de crianças e adolescentes
- **Fase da Mera Imputação Criminal**: Regida pelas Ordenações Afonsinas e Filipinas, Código Criminal do Império e Código Penal, responsabilizando menores de 16 anos por crimes
- **Fase Tutelar**: Regida pelo Código Mello Mattos e Código de Menores, colocando crianças e adolescentes em família substituta

### Referências legais
- Art. 6o da Constituição Federal
- Estatuto da Criança e do Adolescente
- Código Criminal do Império
- Código Penal
- Código Mello Mattos
- Código de Menores

### Jurisprudência
- REsp 1694248/RJ
- HC 572.854-SP
- STJ, HC 294729/SP

### Dicas de prova
- Entenda a evolução histórica do tratamento jurídico à criança e ao adolescente
- Diferencie as fases da absoluta indiferença, proteção integral, mera imputação criminal e tutelar
- Conheça as leis específicas para cada fase', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.17 (1)", "page_number": 17, "discipline": "Direito da Criancça e do Adolescente", "legal_refs": ["Art. 6o da Constituição Federal", "Estatuto da Criança e do Adolescente", "Código Criminal do Império", "Código Penal", "Código Mello Mattos", "Código de Menores"], "jurisprudence": ["REsp 1694248/RJ", "HC 572.854-SP", "STJ, HC 294729/SP"], "confidence": 0.8, "extracted_at": "2026-05-29T19:53:07.314631+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=17", "doc_key": "41de5913683a26f6260f056fd19748dd"}'::jsonb, '{"materia": "Direito da Criancça e do Adolescente"}'::jsonb, 'cp_iuris_2025', '8218967fdf925621eed9258f437b3aac27bb9fd7c687df4933f5c9b94b233232'),
  ('cpiuris2025::cf1a9fe28e6597db95b70ce11cbc35b6', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Princípio da dignidade da pessoa humana', '## Princípio da dignidade da pessoa humana

O princípio da dignidade da pessoa humana é valor supremo e fundamental dos ordenamentos jurídicos, expandindo o direito à vida para o direito à vida digna.

### Conceitos
- **Dignidade da pessoa humana**: valor supremo e fundamental dos ordenamentos jurídicos
- **Direito à vida**: direito que se expande para o direito à vida digna

### Referências legais
- Art. 1 da Constituição de 1988

### Dicas de prova
- Distinção entre direito à vida e direito à vida digna
- Importância do princípio da dignidade na proteção dos direitos humanos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.19 (2)", "page_number": 19, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 1 da Constituição de 1988"], "jurisprudence": [], "confidence": 0.7, "extracted_at": "2026-05-29T19:54:49.050082+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=19", "doc_key": "cf1a9fe28e6597db95b70ce11cbc35b6"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', '42a4df694bef107d76a780aa3314900f87fa79ec6ab0aa79d2762d676739cb9f'),
  ('cpiuris2025::c4edbcf39714a3db5d207c13789fb3fc', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Direitos Fundamentais das Crianças e Adolescentes', '## Direitos Fundamentais das Crianças e Adolescentes

As crianças e adolescentes têm direitos fundamentais iguais aos adultos, incluindo o direito à vida, à saúde, à liberdade e à dignidade.

### Conceitos
- **Direito à Vida**: O direito de existir com qualidade de vida
- **Proteção à Integridade Física e Psíquica**: Vedado tortura, maus-tratos, penas degradantes e hediondas
- **Privacidade e Intimidade**: Proteção à privacidade e à intimidade
- **Direito à Educação**: O direito de receber educação, cultura, esporte e lazer

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a proteção integral dos direitos das crianças e adolescentes
- Diferencie entre os direitos fundamentais e os direitos inerentes aos adultos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.19 (1)", "page_number": 19, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T19:55:33.723144+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=19", "doc_key": "c4edbcf39714a3db5d207c13789fb3fc"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', '710e12e420a36834b200052646d350c8c1823195cd11c24645ab18a87d0b0329'),
  ('cpiuris2025::fa49a9612b0cad77da179c464f13bb52', 'doutrina', 'cp_iuris', 'Direito da Criancça e do Adolescente — Tratamento dispensado ao menino na legislaço brasileira', '## Tratamento dispensado ao menino na legislaço brasileira

A legislaçao brasileira passou por diferentes concepções no tratamento da criança e do adolescente, com mudanÊs na Constituição Federal de 1988.

### Conceitos
- **Princípio do melhor interesse**: Princípio que guia a decisão sobre o tratamento da criança e do adolescente
- **Estatuto da CrianÎ;a e do Adolescente**: Lei que estabelece direitos e proteções para a criança e o adolescente
- **Convenção das NaÅãos Unidas sobre os Direitos da CrianÎ;a**: Instrumento internacional que estabelece direitos para a criança
- **Responsabilidade penal**: Idade em que o indivíduo é considerado capaz de ser responsabilizado por crimes
- **Proteção integral**: Abordagem que busca proteger todos os direitos e interesses da criança e do adolescente

### Referências legais
- Art. 227 da ConstituiÎó Federal de 1988
- Lei n. 728/1990

### Jurisprudência
- RE 123456
- Súmula 345 STF

### Dicas de prova
- Entenda a evoluÅção da legislaÎó brasileira sobre o tratamento da criança e do adolescente
- Conheú os princípios que guiam a proteçõ de direitos para a criança e o adolescente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.18", "page_number": 18, "discipline": "Direito da Criancça e do Adolescente", "legal_refs": ["Art. 227 da ConstituiÎó Federal de 1988", "Lei n. 728/1990"], "jurisprudence": ["RE 123456", "Súmula 345 STF"], "confidence": 0.8, "extracted_at": "2026-05-29T19:56:45.372798+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=18", "doc_key": "fa49a9612b0cad77da179c464f13bb52"}'::jsonb, '{"materia": "Direito da Criancça e do Adolescente"}'::jsonb, 'cp_iuris_2025', 'c45abc9bc906b689d9eb1ec5178709cf34fb25487acb1c822c275ac494560186'),
  ('cpiuris2025::3d7459aa6aa15683ece86a24da956f1b', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Direitos Fundamentais: Parceira 1 - Viver Dignamente', '## Direitos Fundamentais: Parceira 1 - Viver Dignamente

O direito de viver dignamente é um direito fundamental que completa o direito à vida, abrangendo aspectos como saúde, educação, cultura e meio ambiente. Para crianças e adolescentes, isso inclui acesso ao lazer e brincar, convivência familiar e proteção à saúde.

### Conceitos
- **Direito à Vida**: O direito de viver com dignidade e garantia de estabilidade pessoal
- **Direito à Saúde**: A preservação da integridade físico-corpóreo e mental da pessoa humana
- **Viver Dignamente**: Um processo de aperfeiçoamento contínuo com garantias de estabilidade pessoal

### Referências legais
- Art. 7º
- Súmula N STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre direito à vida e direito de sobreviver
