  ('cpiuris2025::a539a44a5654ca321f87a611598d09e9', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Direito das Gestantes ao Estabelecimento de Parto', '## Direito das Gestantes ao Estabelecimento de Parto

As gestantes têm direito a escolher o estabelecimento onde será realizado o parto e estar vinculadas a ele nos últimos meses de gestação.

### Conceitos
- **Autonomia do Sujeito**: Direito do paciente de tomar decisões sobre seu próprio tratamento
- **Cuidados Domiciliares**: Tratamento realizado em ambiente domiciliar, com apoio médico remoto
- **Atenção Básica**: Nível de atendimento básico e primário da Rede de Atenção à Saúde

### Referências legais
- Art. 16 da PORTARIA Nº 3.390/2013 do Ministério da Saúde

### Dicas de prova
- Entenda a autonomia do sujeito e a importância dos cuidados domiciliares
- Conheça as diferentes formas de continuidade do cuidado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.20 (2)", "page_number": 20, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 16 da PORTARIA Nº 3.390/2013 do Ministério da Saúde"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T19:57:26.882980+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=20", "doc_key": "a539a44a5654ca321f87a611598d09e9"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', '0fed4d51b05626fdb33d3faf2dd998ba2e7ac5fdbddc25dc050a2a27a3545d2e'),
  ('cpiuris2025::aa187dbd69e6d5415c96368492df8ab2', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Direitos das crianças e adolescentes durante a gestação e amamentação', '## Direitos das crianças e adolescentes durante a gestação e amamentação

O ECA exige condições adequadas para o aleitamento materno, priorizando a saúde do recém-nascido.

### Conceitos
- **Aleitamento Materno**: Direito do recém-nascido à amamentação
- **Gestante presa**: Mãe submetida à medida socioeducativa de privação de liberdade
- **Condições para o aleitamento materno**: Requisitos para garantir a saúde do recém-nascido

### Referências legais
- Art. 9º da ECA
- Art. 5º, L, da CF
- Lei n.º 12.594, § 2º do art. 63

### Dicas de prova
- Distinção entre o direito do recém-nascido e a gestante
- Importância das condições para o aleitamento materno', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.21 (2)", "page_number": 21, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 9º da ECA", "Art. 5º, L, da CF", "Lei n.º 12.594, § 2º do art. 63"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T19:58:58.752660+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=21", "doc_key": "aa187dbd69e6d5415c96368492df8ab2"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', '48bdfa7767a27d83ef836f93ea1cb3a09c44d743a6246aa14adc5240680dbf90'),
  ('cpiuris2025::f0d7a4f757b00aca3af837d7053a33d5', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Direitos Fundamentais: Parte 1 - Direitos das Gestantes e Adolescentes', '## Direitos Fundamentais: Parte 1 - Direitos das Gestantes e Adolescentes

O texto destaca as obrigações dos hospitais e estabelecimentos de saúde em relação às gestantes e adolescentes, incluindo a necessidade de manter registros individuais, realizar exames para detectar anormalidades no recém-nascido e fornecer declaração de nascimento.

### Conceitos
- **Declaração de Nascimento**: Documento base para a lavratura do assento de nascimento
- **Teste do Pezinho**: Exame realizado no calcanhar do recém-nascido para detectar fenilcetonúria e hipotireoidismo congênito
- **Internação de Adolescentes Gestantes**: Permissível desde que assegurada atenção integral à saúde e condições necessárias para permanecer com o filho durante o período de amamentação

### Referências legais
- Art. 8º-A do ECA
- Art. 10 do ECA

### Jurisprudência
- Informativo n° 668 do STJ

### Dicas de prova
- Entenda a importância da declaração de nascimento e do teste do pezinho
- Conheça as obrigações dos hospitais em relação às gestantes e adolescentes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.22 (1)", "page_number": 22, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 8º-A do ECA", "Art. 10 do ECA"], "jurisprudence": ["Informativo n° 668 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T19:59:48.717099+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=22", "doc_key": "f0d7a4f757b00aca3af837d7053a33d5"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', '6b295f8a1b11ccf3c34dc39f3bbeb3696a61875b5322f8af72a232b824e7d447'),
  ('cpiuris2025::69a011d59c6a3ac0112845fb79934660', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Direitos Fundamentais: Parte 1 - Gravidez e Parto', '## Direitos Fundamentais: Parte 1 - Gravidez e Parto

O texto destaca a importância de atenção humanizada à gravidez e ao parto, bem como os direitos da gestante, incluindo o direito a um acompanhante e a assistência psicológica. Além disso, é mencionado o dever da gestante de buscar ativamente as consultas de pré-natal e pós-parto.

### Conceitos
- **Direitos Fundamentais**: direitos garantidos à mulher durante a gravidez e o parto
- **Atenção Humanizada**: abordagem mais humana e respeitosa da gravidez e do parto
- **Direito ao Acompanhante**: direito da gestante de escolher uma pessoa para acompanhá-la durante o parto
- **Assistência Psicológica**: serviço de apoio psicológico oferecido às gestantes e mães após o parto
- **Violação dos Direitos da Gestante**: ocorrência de atos médicos e de saúde que violam os direitos da gestante
- **Violência Obstétrica**: violência física, psicológica e moral que ocorre contra a mulher grávida ou seus nascituros
- **Tratamento Desumanizado**: abordagem médica que ignora a autonomia e capacidade de decisão da mulher

### Referências legais
- Art. 8°, § 8° do ECA

### Dicas de prova
- Entenda o conceito de atenção humanizada à gravidez e ao parto
- Identifique os direitos da gestante mencionados no texto
- Aprenda a distinguir entre violação dos direitos da gestante e violência obstétrica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.21 (1)", "page_number": 21, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 8°, § 8° do ECA"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T20:00:14.041452+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=21", "doc_key": "69a011d59c6a3ac0112845fb79934660"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', '9a90ac82a8c7d19931a18541daa9e01e37d3d50bfa58cf33e098b78757d5f359'),
  ('cpiuris2025::b875b05b42144170f242bfb921b4b870', 'doutrina', 'cp_iuris', 'Direito da Criancê e do Adolescente — Acesso à Saú de CrianÊ e Adolescente', '## Acesso à Saú de CrianÊ e Adolescente

O artigo 11 do ECA assegura o acesso integral ao cuidado voltado para a saúde da crianÊ e do adolescente, observando o princípio da equidade.

### Conceitos
- **Acesso à Saú**: direito garantido ao cidadão
- **Equidade**: princípio que prioriza a justiça e a igualdade em acesso a serviços e ações de saúde
- **CrianÊ e Adolescente**: faixa etária protegida por leis especiais

### Referências legais
- Art. 11 da Lei núo 8.842/1993 (ECA)

### Dicas de prova
- Entenda o conceito de equidade e como ela se aplica ao acesso a serviços de saúde
- Identifique os direitos garantidos ao cidadão pela Lei núo 8.842/1993', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.22 (2)", "page_number": 22, "discipline": "Direito da Criancê e do Adolescente", "legal_refs": ["Art. 11 da Lei núo 8.842/1993 (ECA)"], "jurisprudence": [], "confidence": 0.9, "extracted_at": "2026-05-29T20:01:05.935498+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=22", "doc_key": "b875b05b42144170f242bfb921b4b870"}'::jsonb, '{"materia": "Direito da Criancê e do Adolescente"}'::jsonb, 'cp_iuris_2025', '507a76cd55d3f28761c14e6a85d71291bb93200ba4418aacb6c644afcf7e0b99'),
  ('cpiuris2025::c323ca0d4a8d18be711b8acbea441c23', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Obrigação de proteção contra violências contra crianças e adolescentes', '## Obrigação de proteção contra violências contra crianças e adolescentes

A lei exige que os agentes públicos e privados tomem medidas para proteger as crianças e adolescentes de violências, com a obrigação de notificar o Conselho Tutelar em caso de suspeitas ou casos de maus-tratos.

### Conceitos
- **Obrigação de proteção**: Dever de agentes públicos e privados para proteger as crianças e adolescentes
- **Notificação ao Conselho Tutelar**: Obligação de notificar o Conselho Tutelar em caso de suspeitas ou casos de maus-tratos
- **Programas de proteção**: Medidas estabelecidas para a proteção das crianças e adolescentes

### Referências legais
- Art. 70-B ECA
- Art. 2415

### Dicas de prova
- Distinção entre notificação e comunicação ao Conselho Tutelar
- Importância dos programas de proteção para as vítimas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.23 (2)", "page_number": 23, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 70-B ECA", "Art. 2415"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T20:02:11.290358+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=23", "doc_key": "c323ca0d4a8d18be711b8acbea441c23"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', '6e3cbcbd93926928e490df79dbdde1ce38695985fa6b7b3d8d61554e97ee98c2'),
  ('cpiuris2025::fbfe7aba096a147d2cc208288130b5e1', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Direitos Fundamentais: Parte 1', '## Direitos Fundamentais: Parte 1

O texto destaca a importância dos direitos fundamentais da criança e do adolescente, incluindo o direito à vida, à saúde, à educação e ao cuidado. Além disso, é abordada a responsabilidade do responsável pela criação e educação do menor, bem como a obrigação de comunicar suspeitas de maus tratos ou violência doméstica e familiar.

### Conceitos
- **Responsável**: Pessoa que zela pela criação e educação do menor
- **Tutor**: Pessoa que assume o cuidado e a responsabilidade de um menor
- **Guardião Legal**: Pessoa nomeada pelo juiz para assumir a responsabilidade do menor
- **Guardião de Fato**: Pessoa que assume a responsabilidade do menor em virtude de uma decisão judicial ou de um acordo entre as partes
- **Direito à Visitação**: Direito da criança e do adolescente a visitar sua mãe ou pai internado em instituição de saúde
- **Crime do Deixar de Comunicar**: Crime previsto no art. 26 da Lei Henry Borel, que configura o descumprimento de obrigação de comunicar suspeitas de violência doméstica e familiar

### Referências legais
- Art. 12 do ECA
- Lei n. 14.950/2024
- Lei n.º 13.010/2014
- Lei n.° 14.344/2022

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a definição de responsável e suas responsabilidades
- Conheça as diferentes figuras de tutor, guardião legal e guardião de fato
- Destaque a importância do direito à visitação da criança e do adolescente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.23 (1)", "page_number": 23, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 12 do ECA", "Lei n. 14.950/2024", "Lei n.º 13.010/2014", "Lei n.° 14.344/2022"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-29T20:03:12.052138+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=23", "doc_key": "fbfe7aba096a147d2cc208288130b5e1"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', '690f3962fd65daba088e7c9b7c4c5eaf4de9b5361da9ad5bf6d7f5b2b87ca86f'),
  ('cpiuris2025::597aed63e6b45a0a2ec9d55048b21c83', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Direitos Fundamentais: Parte 1', '## Direitos Fundamentais: Parte 1

O texto destaca a importância dos direitos fundamentais para crianças e adolescentes, incluindo liberdade, respeito e dignidade. Além disso, é abordado o direito à convivência familiar e comunitária, bem como as medidas de proteção necessárias para garantir a integridade física e psicológica das crianças e adolescentes.

### Conceitos
- **Direitos Fundamentais**: direitos que são titularizados por todas as pessoas, incluindo crianças e adolescentes
- **Liberdade**: direito à liberdade, respeito e dignidade para crianças e adolescentes
- **Convivência Familiar e Comunitária**: direito à convivência familiar e comunitária para crianças e adolescentes
- **Proteção Integral**: direitos próprios, como brincar, praticar esportes e divertir-se, que são especiais para crianças e adolescentes

### Referências legais
- Art. 8 da Lei n.º 13.509/2017

### Dicas de prova
- Distinção entre direitos fundamentais e proteção integral
- Importância do direito à convivência familiar e comunitária
- Consequências da denúncia ou notificação de condutas descritas no artigo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.24 (1)", "page_number": 24, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 8 da Lei n.º 13.509/2017"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T20:03:50.891979+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=24", "doc_key": "597aed63e6b45a0a2ec9d55048b21c83"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', 'f316222535608969a7f5ef0f582b735d8d4318014a63e8ca0b35aa4b4e23f14f'),
  ('cpiuris2025::9012b31495b35f574ba27b4f8f2e67a5', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Medidas de Proteção para Noticiantes e Denunciantes', '## Medidas de Proteção para Noticiantes e Denunciantes

O noticiante ou denunciante que sofrer coação ou ameaça pode requerer medidas de proteção previstas na Lei nº 9.807/99.

### Conceitos
- **coação**: Ameaça ou pressão para revelar informações
- **ameaça**: Atitude que visa intimidar ou assustar alguém
- **medidas de proteção**: Mídias implementadas para garantir a segurança do noticiante ou denunciante
- **Lei nº 9.807/99**: Lei que regula as medidas de proteção para noticiantes e denunciantes
- **juiz competente**: Magistrado responsável por decidir sobre a medida de proteção
- **Ministério Público**: Autoridade que pode requerer a medida de proteção
- **Conselho Tutelar**: Órgão que pode solicitar a medida de proteção

### Referências legais
- Art. 5º da Lei nº 9.807/99

### Dicas de prova
- Entenda o conceito de coação e ameaça
- Conheça a Lei nº 9.807/99 e suas medidas de proteção
- Identifique o papel do juiz competente e do Ministério Público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.24 (2)", "page_number": 24, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 5º da Lei nº 9.807/99"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T20:04:49.147331+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=24", "doc_key": "9012b31495b35f574ba27b4f8f2e67a5"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', '83ddf3668ee608be2f57f8782d81c541754e6a01192640b52c14d0f98a3e95b3'),
  ('cpiuris2025::1e090e4ab2709d45309f1e7e3525cd81', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Direito à liberdade', '## Direito à liberdade

O direito à liberdade dos infantes abrange vários aspectos, incluindo ir, vir e estar nos logradouros públicos e espaços comunitários, opinião e expressão, crença e culto religioso, entre outros.

### Conceitos
- **Direito à liberdade**: direito dos infantes que abrange vários aspectos, como ir, vir e estar nos logradouros públicos e espaços comunitários
- **Liberdade de opinião e expressão**: direito dos infantes a expressar seu pensamento e manifestação, incluindo atividade intelectual, artística e de comunicação

### Referências legais
- Art. 16 do ECA

### Dicas de prova
- Memorizar o conteúdo do direito à liberdade para não confundir com o direito ao respeito
- Entender que a liberdade de ir e vir pode ser disciplinada pelo juiz, mas apenas em casos específicos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.25 (1)", "page_number": 25, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 16 do ECA"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T20:05:19.386338+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=25", "doc_key": "1e090e4ab2709d45309f1e7e3525cd81"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', 'afcfb9d582ae52e181288a20326b99251b951816cbaf1e1db17d44be8e439db8'),
  ('cpiuris2025::716bc9405b559d13bcf7745b5e8fca0e', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Liberdade de opinião, expressão e religião', '## Liberdade de opinião, expressão e religião

O direito à liberdade de opinião, expressão e religião é protegido pelo ECA. Os pais têm o poder familiar para orientar a religião dos filhos, mas os adolescentes podem escolher sua própria fé após uma certa maturidade.

### Conceitos
- **Liberdade de opinião**: direito à expressão e crença
- **Poder familiar**: direito dos pais para orientar a criação e educação dos filhos
- **Maturidade**: idade em que os adolescentes podem escolher sua própria fé

### Referências legais
- Art. 179, inciso II do ECA

### Dicas de prova
- Entenda a diferença entre liberdade de opinião e poder familiar.
- Conheça o conceito de maturidade nos termos do direito infantil.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.25 (2)", "page_number": 25, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 179, inciso II do ECA"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T20:05:33.155646+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=25", "doc_key": "716bc9405b559d13bcf7745b5e8fca0e"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', 'dc8039d1c1a17363a12c568dd1482f4306c58378966d44f1c7806ad475036f6d'),
  ('cpiuris2025::d49df3c48bd03afef818b34682657dd8', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Direitos Fundamentais: Parte 1 - Religião e Educação', '## Direitos Fundamentais: Parte 1 - Religião e Educação

A religião dos pais não pode afetar a existência dos filhos, especialmente em situações que colham risco à vida. O Estado protege os direitos fundamentais do menor, prevalecendo sua vida sobre a crença religiosa dos pais.

### Conceitos
- **Dereito à vida**: O direito fundamental de viver e manter-se seguro
- **Educação religiosa**: O dever do Estado de promover a educação religiosa, mas respeitando os direitos fundamentais dos filhos
- **Testemunha de Jeová**: Religião que proíbe a transfusão de sangue em casos de risco de vida
- **Pátrio poder**: O direito dos pais de tomar decisões sobre a educação e o bem-estar de seus filhos
- **Teoria do Menor Amadurecido**: A teoria que afirma que o menor deve ter sua vontade respeitada se demonstrar maturidade e capacidade decisória

### Referências legais
- Art. 227 da Lei nº 8.069/1990
- ...

### Jurisprudência
- RE 123456
- Súmula 444 STF

### Dicas de prova
- Distinção entre o direito dos pais e os direitos fundamentais do menor
- Importância da educação religiosa respeitando os direitos fundamentais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.26 (1)", "page_number": 26, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 227 da Lei nº 8.069/1990", "..."], "jurisprudence": ["RE 123456", "Súmula 444 STF"], "confidence": 0.8, "extracted_at": "2026-05-29T20:06:09.695509+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=26", "doc_key": "d49df3c48bd03afef818b34682657dd8"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', '2a2dfe391934a55dbf93fded2c08efd1be6cf763dbf4e0afbdef08366528e07d'),
  ('cpiuris2025::c416a3b9bbf537110da733f2f504188f', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Direitos das crianças e adolescentes: liberdade e atividades lúdicas', '## Direitos das crianças e adolescentes: liberdade e atividades lúdicas

O direito de brincar, praticar esportes e divertir-se é um desdobramento da liberdade especialmente destinado aos infantes. A idade de 18 anos é considerada a devida maturidade para tomada de decisões.

### Conceitos
- **Liberdade**: direito fundamental
- **Atividades lúdicas**: espaços e atividades criados para o entretenimento dos infantes
- **Maturidade**: idade considerada a devida para tomada de decisões

### Referências legais
- Art. 227 da Constituição Federal
- ...

### Jurisprudência
- Súmula 444 do STF
- ...

### Dicas de prova
- Diferenciar entre liberdade e responsabilidade dos pais
- Entender a importância da idade de 18 anos para tomada de decisões', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.26 (2)", "page_number": 26, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 227 da Constituição Federal", "..."], "jurisprudence": ["Súmula 444 do STF", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T20:08:05.337414+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=26", "doc_key": "c416a3b9bbf537110da733f2f504188f"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', '9a56bcbff2ea9a160bfd6ded86d2d50f1fe072e068302a2fc6d67f263d47c9dd'),
  ('cpiuris2025::dab73bc041e41824220638a92e7cc97b', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Direitos Fundamentais: Parte 1', '## Direitos Fundamentais: Parte 1

Resumo objetivo: Este trecho aborda os direitos fundamentais dos adolescentes e crianças, incluindo participação familiar, política e comunitária, liberdade ao refúgio, auxílio e orientação, respeito e proteção da imagem.

### Conceitos
- **Participação Familiar**: Inclui a família natural e extensa, bem como a participação na comunidade
- **Capacidade Eleitoral**: Adquirida aos 16 anos de idade, com exercício facultativo
- **Liberdade ao Refúgio**: Direito à proteção contra violência e busca por refúgio
- **Auxílio e Orientação**: Proporcionado para desenvolvimento esclarecido
- **Respeito**: Inviolabilidade da integridade física, psíquica e moral
- **Direitos da Personalidade**: Relacionados à preservação da imagem, identidade e autonomia
- **Proteção da Imagem**: Vedada a veiculação de material jornalístico com imagens vexatórias ou constrangedoras

### Referências legais
- Art. 17 do ECA

### Jurisprudência
- Informativo 511 do STJ

### Dicas de prova
- Distinção entre direitos fundamentais e direitos da personalidade
- Legitimidade do Ministério Público para propor ações civis públicas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.27 (1)", "page_number": 27, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 17 do ECA"], "jurisprudence": ["Informativo 511 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T20:09:02.247957+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=27", "doc_key": "dab73bc041e41824220638a92e7cc97b"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', '38095ca2b6233144f707c02dcf537713e77a3e74e3ff5b46aaf8382dd39269e3'),
  ('cpiuris2025::72865c894cbef721ae53e5be286b455b', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Vedação de divulgação de atos judiciais, policiais e administrativos relacionados a crianças e adolescentes', '## Vedação de divulgação de atos judiciais, policiais e administrativos relacionados a crianças e adolescentes

A vedação de divulgação de atos judiciais, policiais e administrativos que digam respeito a crianças e adolescentes autóricas de atos infracionais é permitida, mas com restrições. A divulgação pode ser feita à luz do artigo 144 do ECA, quando houver interesse jurídico.

### Conceitos
- **Vedação**: Restrição ou proibição de algo
- **Atos judiciais**: Decisões e procedimentos do sistema judicial
- **Divulgação**: Compartilhamento de informações
- **Interesse jurídico**: Motivo legítimo para a divulgação de informações
- **Art. 144 do ECA**: Lei que permite a divulgação de atos judiciais em determinadas circunstâncias
- **Ato infracional**: Ato ilegal cometido por uma criança ou adolescente
- **Criança e adolescente autóricas**: Menores que cometeram atos infracionais

### Referências legais
- Art. 143 do ECA
- Art. 144 do ECA

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Pergunte sobre a vedação de divulgação de atos judiciais e policiais relacionados a crianças e adolescentes.
- Entenda o conceito de interesse jurídico e como ele afeta a divulgação de informações.
- Conheça as restrições para a divulgação de notícias sobre fatos que envolvem crianças e adolescentes.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.27 (2)", "page_number": 27, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 143 do ECA", "Art. 144 do ECA"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-29T20:09:29.059110+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=27", "doc_key": "72865c894cbef721ae53e5be286b455b"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', '6d4cdf04a1d60d374f92fe8f4dcb699157b23cefb4b5bd6c32bcca3cb9e253df'),
  ('cpiuris2025::606ff29d481c620d3c1495658bb38257', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Direitos Fundamentais: Parte 1', '## Direitos Fundamentais: Parte 1

O texto discute a importância de proteger os direitos das crianças e adolescentes, especialmente em relação à divulgação de fotos de desaparecidos e ao tratamento desumano. Além disso, aborda o direito à educação sem castigo físico ou cruel.

### Conceitos
- **Tratamento Desumano**: Impinge sofrimento físico ou mental
- **Violento**: Implica força física contra infantes
- **Aterrorizante**: Embute medo, pavor ou terror
- **Vexatório**: Impõe vergonha ou humilhação
- **Constrangedor**: Implica embaraço semelhante ao vexatório

### Referências legais
- Art. 22, IV, da CF/88
- Art. 220 da CF/88
- Lei n.° 12.127/2009
- Art. 18-A

### Jurisprudência
- RE 123456
- Informativo n° 1048 STF

### Dicas de prova
- Distinção entre tratamento desumano e castigo físico
- Importância do princípio da dignidade na infância e juventude', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.28 (1)", "page_number": 28, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 22, IV, da CF/88", "Art. 220 da CF/88", "Lei n.° 12.127/2009", "Art. 18-A"], "jurisprudence": ["RE 123456", "Informativo n° 1048 STF"], "confidence": 0.8, "extracted_at": "2026-05-29T20:10:43.722963+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=28", "doc_key": "606ff29d481c620d3c1495658bb38257"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', '58761cdf506c9bfcd2462f1c2c451fd5c757e0d68044d521c41c49d4db1e003e'),
  ('cpiuris2025::06d94d0d60b5e9ff90948c4dc6d2ce72', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Castigo Físico nas Crianças e Adolescentes', '## Castigo Físico nas Crianças e Adolescentes

O castigo físico é ação disciplinar ou punitiva que causa sofrimento físico na criança ou adolescente, sendo vedado apenas aquele que causa lesão.

### Conceitos
- **Castigo Físico**: ação disciplinar ou punitiva que causa sofrimento físico
- **Sofrimento Físico**: lesão ou dano causado à criança ou adolescente
- **Lei da Palmada**: Lei n.º 13.010/2014, que proíbe o castigo físico que causa lesão

### Referências legais
- Art. 227 do ECA
- Art. 39 da Lei n.º 13.010/2014

### Jurisprudência
- RE 123456
- Súmula 444 STF

### Dicas de prova
- Diferenciar entre castigo físico e sofrimento físico
- Entender a distinção entre palmada leve e grave', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.28 (2)", "page_number": 28, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 227 do ECA", "Art. 39 da Lei n.º 13.010/2014"], "jurisprudence": ["RE 123456", "Súmula 444 STF"], "confidence": 0.8, "extracted_at": "2026-05-29T20:11:03.184517+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=28", "doc_key": "06d94d0d60b5e9ff90948c4dc6d2ce72"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', 'b12f1db9959cdad39faef3477798bb76b363d836c023cf137593014c7f567dc6'),
  ('cpiuris2025::ae629b4c2edcad7947f75230f1b69988', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Tratamento cruel ou degradante', '## Tratamento cruel ou degradante

A lei proíbe tratamentos cruéis ou degradantes, incluindo agressões verbais, e estabelece medidas para proteger as crianças e adolescentes.

### Conceitos
- **Dano Moral**: dano que a criança ou adolescente sofre como resultado do tratamento cruel ou degradante
- **Tratamento Cruel ou Degradante**: tratamento que humilha, ameaça gravemente ou ridiculariza a criança ou adolescente
- **Castigo Físico**: uso de força física para punir a criança ou adolescente
- **Agressão Verbal**: agressão verbal que pode ser considerada tratamento cruel ou degradante
- **Medidas de Proteção**: medidas aplicadas pelo Conselho Tutelar para proteger a criança ou adolescente, incluindo encaminhamento a programas de proteção à família e tratamento psicológico
- **Dano Moral In Re Ipsa**: dano moral que é presumido quando ocorre agressão verbal ou física contra uma criança ou adolescente

### Referências legais
- Art. 13.010/2014

### Jurisprudência
- Informativo 598/STJ

### Dicas de prova
- Diferenciar entre tratamento cruel e degradante e castigo físico
- Entender a importância do dano moral in re ipsa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.29 (1)", "page_number": 29, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 13.010/2014"], "jurisprudence": ["Informativo 598/STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T20:12:13.672853+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=29", "doc_key": "ae629b4c2edcad7947f75230f1b69988"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', 'f1e0862edfb94e0517e61c602af160600dd7b53f1e708e99eb350c468847df72'),
  ('cpiuris2025::7003193ba13e72b06c703763e80e0b51', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Castigo físico e punição', '## Castigo físico e punição

O castigo físico é sempre punido, mas pode configurar crimes previstos no Código Penal ou no ECA, dependendo do caso concreto.

### Conceitos
- **Lesão corporal**: dano físico sofrido por uma pessoa
- **Crime**: conduta punível pela lei
- **Código Penal**: lei que estabelece as normas penais do país
- **ECA**: Estatuto da Criança e do Adolescente
- **Poder familiar**: direito de um pai ou mãe sobre o filho

### Referências legais
- Art. 129 do Código Penal
- Art. 136 do Código Penal
- Art. 232 do ECA
- Art. 1.638 do Código Civil

### Dicas de prova
- Diferenciar entre lesão corporal e crime
- Entender a distinção entre art. 129 e art. 136 do Código Penal
- Conhecer o conceito de ECA e sua aplicação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.29 (2)", "page_number": 29, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 129 do Código Penal", "Art. 136 do Código Penal", "Art. 232 do ECA", "Art. 1.638 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T20:12:59.999748+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=29", "doc_key": "7003193ba13e72b06c703763e80e0b51"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', '988107c2e5c2913e5857edf4d9ce3e73eb8f374cad353ce65b068d8e608908a4'),
  ('cpiuris2025::0d13a71d70f2465ae7eec40ac5041aaa', 'doutrina', 'cp_iuris', 'Direito da Criancça e do Adolescente — Internação de adolescente gestante ou com filho em amamentação', '## Internação de adolescente gestante ou com filho em amamentação

A lei permite a internação de adolescentes gestantes ou com filhos em amamentação, desde que garanta atenção integral à saúde e as condições necessárias para permanecer com o filho durante o período de amamentação.

### Conceitos
- **Internação**: Ação de colocar alguém em um estabelecimento para cuidado ou tratamento
- **Gestante**: Mulher grávida
- **Amamentação**: Prática de amamentar um bebê
- **Atenção integral à saúde**: Cuidados médicos e sociais para garantir a saúde do adolescente

### Referências legais
- Art. 227 da Lei nº 12.594/2012 - SINASE

### Jurisprudência
- STJ. 5ª Turma. HC 543.279-SP, Rel. Min. Reynaldo Soares da Fonseca
- AgInt no REsp 1.597.299/PE, Min. Herman Benjamin

### Dicas de prova
- Distinção entre internação e privação de liberdade
- Importância do registro na Anvisa para a dispensação de medicamentos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.30 (1)", "page_number": 30, "discipline": "Direito da Criancça e do Adolescente", "legal_refs": ["Art. 227 da Lei nº 12.594/2012 - SINASE"], "jurisprudence": ["STJ. 5ª Turma. HC 543.279-SP, Rel. Min. Reynaldo Soares da Fonseca", "AgInt no REsp 1.597.299/PE, Min. Herman Benjamin"], "confidence": 0.8, "extracted_at": "2026-05-29T20:13:31.914321+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=30", "doc_key": "0d13a71d70f2465ae7eec40ac5041aaa"}'::jsonb, '{"materia": "Direito da Criancça e do Adolescente"}'::jsonb, 'cp_iuris_2025', '9f8b3b6e2750842f22f24ef619775f384b8694a0885d73f7560ca4bd1e16b558'),
  ('cpiuris2025::105cd4d751ae86846652578ae8ecdef1', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Dano Moral Coletivo em Crianças e Adolescentes', '## Dano Moral Coletivo em Crianças e Adolescentes

A lesão ao direito transindividual da coletividade de crianças e adolescentes configura dano moral coletivo, permitindo a indenização.

### Conceitos
- **Dano Moral Coletivo**: Lesão ao direito transindividual da coletividade
- **Direito à Informação**: Proteção contra a censura
- **Ponderação de Valores Fundamentais**: Juízo de ponderação entre valores fundamentais
- **Lesão à Dignidade da Criança**: Afronta à dignidade da criança exposta em reportagens

### Referências legais
- Art. 227 da Constituição Federal
- Arts. 11 e seguintes do ECA
- Art. 24 da Convenção Internacional dos Direitos da Criança (ONU/1989)

### Jurisprudência
- REsp 1645067/RS
- STJ, REsp 1.517.973-PE
- AgRg no AgRg no AREsp 685.750/PB

### Dicas de prova
- Distinção entre dano moral individual e coletivo
- Importância da ponderação de valores fundamentais em juízo de equidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.30 (2)", "page_number": 30, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 227 da Constituição Federal", "Arts. 11 e seguintes do ECA", "Art. 24 da Convenção Internacional dos Direitos da Criança (ONU/1989)"], "jurisprudence": ["REsp 1645067/RS", "STJ, REsp 1.517.973-PE", "AgRg no AgRg no AREsp 685.750/PB"], "confidence": 0.8, "extracted_at": "2026-05-29T20:14:45.897377+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=30", "doc_key": "105cd4d751ae86846652578ae8ecdef1"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', '8f47c4f324633383a39463c753fe1e52b47f1cc73cded2981bc0aea0171d5774'),
  ('cpiuris2025::4124170ebd93599958fbae772eecb492', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Ônus da prova em ação de compensação por dano moral', '## Ônus da prova em ação de compensação por dano moral

A criança tem direito à proteção irrestrita dos direitos da personalidade, com indenização pelo dano moral decorrente de sua violação. O ônus da prova é presumido para o agressor.

### Conceitos
- **Dano Moral**: prejuízo à dignidade e ao bem-estar de uma pessoa
- **Ônus da Prova**: obrigação de provar a existência de um fato para justificar uma ação ou reivindicação
- **Repartição do Ónus Probatório**: distribuição do peso da prova entre as partes em um processo

### Referências legais
- Art. 5º, X da CF
- Art. 12 do CC/02

### Jurisprudência
- STJ, REsp nº 1642318-MS
- RE 123456

### Dicas de prova
- Entenda o conceito de dano moral e como ele é relacionado com a proteção dos direitos da personalidade.
- Conheça a regra do ônus da prova em ações de compensação por dano moral.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.31 (2)", "page_number": 31, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 5º, X da CF", "Art. 12 do CC/02"], "jurisprudence": ["STJ, REsp nº 1642318-MS", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T20:15:46.441318+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=31", "doc_key": "4124170ebd93599958fbae772eecb492"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', 'e925ab9413faf220748683d4898063f3c3474c264e9a19951d695f958e05e064'),
  ('cpiuris2025::24adf40e421ae0fb6264d794955d4d47', 'doutrina', 'cp_iuris', 'Direito da Criancça e do Adolescente — Dano Moral em Relaóes de Consumo', '## Dano Moral em Relaóes de Consumo

O direito à integridade mental dos menores é protegido pela Constituição Federal e pelo Cço Civil. A recusa indevida de cobertura médica pode causar danos morais, pois agrava a situação de afliçó psicológica e de angúó no espírito daquele.

### Conceitos
- **Dano Moral**: prejuízo causado à integridade mental ou à dignidade de uma pessoa
- **Direito à Integridade Mental**: direito dos menores à proteção da sua personalidade e dignidade
- **RelaÎes de Consumo**: relações entre consumidores e fornecedores de bens e serviços

### Referências legais
- Art. 5º, X da CF
- Art. 12, caput do CC/02
- Art. 6º, VI do CDC

### Jurisprudência
- REsp 509.968-SP
- STJ, REsp nº 1037759-RJ

### Dicas de prova
- Distinção entre dano moral e danos físicos
- Importância da proteção dos direitos da personalidade nos menores', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.31 (1)", "page_number": 31, "discipline": "Direito da Criancça e do Adolescente", "legal_refs": ["Art. 5º, X da CF", "Art. 12, caput do CC/02", "Art. 6º, VI do CDC"], "jurisprudence": ["REsp 509.968-SP", "STJ, REsp nº 1037759-RJ"], "confidence": 0.8, "extracted_at": "2026-05-29T20:16:02.292728+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=31", "doc_key": "24adf40e421ae0fb6264d794955d4d47"}'::jsonb, '{"materia": "Direito da Criancça e do Adolescente"}'::jsonb, 'cp_iuris_2025', 'c9ad2eb2510fda5dd2412af11f64fdb4db96a903c27664105edd75945e7b9037'),
  ('cpiuris2025::6cee4d761bddaf4a0840ca88129246f3', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Direitos Fundamentais da Criança e do Adolescente', '## Direitos Fundamentais da Criança e do Adolescente

Resumo sobre os direitos fundamentais das crianças e adolescentes, incluindo saúde, vida, liberdade e dignidade.

### Conceitos
- **Assistência Odontológica**: Garantia da saúde bucal para crianças e adolescentes
- **Descumprimento de obrigações do ECA**: Ilícito administrativo
- **Registro de atividades desenvolvidas**: Prazo reduzido ou dispensado para manter prontuários individuais
- **Fornecimento gratuito de medicamentos e recursos**: Obrigação do Poder Público
- **Tratamento físico como castigo**: Violação do Estatuto da Criança e do Adolescente

### Referências legais
- Art. 7º do ECA
- Art. 10 do ECA
- Art. 228 do ECA

### Dicas de prova
- Distinção entre tratamento físico como castigo e violência doméstica
- Importância da assistência odontológica para a saúde bucal das crianças e adolescentes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.32", "page_number": 32, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 7º do ECA", "Art. 10 do ECA", "Art. 228 do ECA"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T20:17:09.927116+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=32", "doc_key": "6cee4d761bddaf4a0840ca88129246f3"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', 'e1ff65288adbb0ee348251c5064d4bd75eede5913005cc4d0d4cf0bae6d2df3e'),
  ('cpiuris2025::1f9c58e73bf6492b8d70b73f6e6ef33d', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Direitos Fundamentais: Parte 1', '## Direitos Fundamentais: Parte 1

Resumo de direitos fundamentais garantidos à mulher durante a gestação, incluindo atendimento pré-natal, acompanhante, alta hospitalar e acompanhamento saudável.

### Conceitos
- **Atendimento pré-natal**: Garantido o direito de opção da mulher
- **Acompanhante**: De sua preferência, durante o período do pré-natal, trabalho de parto e pós-parto imediato
- **Alta hospitalar responsável**: E contrarreferência na atenção primária
- **Acesso a outros serviços**: E grupos de apoio e amamentação
- **Acompanhamento saudável**: Durante toda a gestação, parto natural cuidadoso, aplicação de cesariana e outras intervenções cirúrgicas por motivos médicos

### Referências legais
- Art. 227 do Estatuto da Criança e do Adolescente

### Dicas de prova
- Entenda a importância de cada direito fundamental garantido à mulher durante a gestação
- Conheça as diferenças entre atendimento pré-natal e acompanhante', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.33", "page_number": 33, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 227 do Estatuto da Criança e do Adolescente"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T20:18:04.020109+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=33", "doc_key": "1f9c58e73bf6492b8d70b73f6e6ef33d"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', 'fe8e9b0725c83624f44944fc95a75c18c4ed5a66feab371d87589bf2747bb852'),
  ('cpiuris2025::6a0ad72a2f0158bce3926ef7436f27d8', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Direito à Convivência Familiar', '## Direito à Convivência Familiar

O direito fundamental da criança e do adolescente de viver e ser criado junto de sua família natural ou extensa, em ambiente que garanta seu desenvolvimento integral.

### Conceitos
- **Família Natural**: Composta pelos pais (ou um deles) e os descendentes
- **Família Extensa ou Ampliada**: Formada por parentes próximos com os quais a criança ou adolescente convive e mantém vínculos de afinidade e afetividade
- **Convivência Familiar**: Direito fundamental da criança e do adolescente de viver e ser criado junto de sua família natural ou extensa

### Referências legais
- Art. 226 da Lei Maior
- Súmula N STF (ADI 4277/DF)

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre família natural e extensa.
- Conheça as hipóteses em que a prioridade da família natural persiste
- Avalie o conceito de convivência familiar como direito fundamental', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.34 (1)", "page_number": 34, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 226 da Lei Maior", "Súmula N STF (ADI 4277/DF)"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T20:18:21.969688+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=34", "doc_key": "6a0ad72a2f0158bce3926ef7436f27d8"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', '4dd1deeaca34611dcbecc2e05eca8f0dffa7602b29963fb8521431d88daf1d2f'),
  ('cpiuris2025::858ebb38d1d6305d7de3b73423424489', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Acolhimento Institucional e Familiar', '## Acolhimento Institucional e Familiar

O acolhimento institucional e familiar são medidas provisórias e excepcionais para proteger crianças e adolescentes em situação de risco. O acolhimento institucional entrega a criança ou adolescente a uma entidade de atendimento, enquanto o acolhimento familiar entrega a criança ou adolescente a uma família previamente cadastrada.

### Conceitos
- **Acolhimento Institucional**: Entrega da criança ou adolescente a uma entidade de atendimento para protegê-lo de situações de violência.
- **Acolhimento Familiar**: Entrega da criança ou adolescente a uma família previamente cadastrada para ampará-lo temporariamente até que seja reintegrado ao convívio familiar.
- **Privação de Liberdade**: Não ocorre no acolhimento institucional ou familiar, pois não é uma medida de privação de liberdade.

### Referências legais
- Art. 101 da Lei nº 8.037/1990
- Art. 19, § 1º do ECA

### Dicas de prova
- Diferenciar entre acolhimento institucional e familiar.
- Entender que o acolhimento institucional é uma medida provisória e excepcional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.35 (1)", "page_number": 35, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 101 da Lei nº 8.037/1990", "Art. 19, § 1º do ECA"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T20:19:45.920450+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=35", "doc_key": "858ebb38d1d6305d7de3b73423424489"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', 'f82b724ab054152f718fc5d9fcc09231bf84b6dad27c2aab932f489da70c521b'),
  ('cpiuris2025::9b4fb6c2b4e13629caa9c590a26552f1', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Colocação em família substituta e direitos das crianças e adolescentes', '## Colocação em família substituta e direitos das crianças e adolescentes

Resalta a importância de proteger os direitos fundamentais das crianças e adolescentes, especialmente em situações de risco, e estabelece regras para a colocação em família substituta.

### Conceitos
- **Colocação em família substituta**: Prática que envolve o envio de uma criança ou adolescente a um ambiente familiar substituto.
- **Direitos fundamentais das crianças e adolescentes**: Direitos inalienáveis e invioláveis, como a vida, a dignidade e a liberdade.
- **Família natural**: Unidade familiar composta por pais e filhos.
- **Família substituta**: Unidade familiar alternativa à família natural, criada por meio de adoção ou outro mecanismo legal.
- **Acolhimento familiar**: Prática que envolve o recebimento e cuidado de uma criança ou adolescente em um ambiente familiar.
- **Acolhimento institucional**: Prática que envolve o recebimento e cuidado de uma criança ou adolescente em um estabelecimento institucional.
- **Situação de risco**: Condição em que a criança ou adolescente se encontra em perigo iminente à sua integridade física, moral ou psicológica.
- **Autorização judicial**: Decisão do juiz que autoriza a transferência de uma criança ou adolescente para um ambiente familiar substituto.

### Referências legais
- Art. 98 da Lei nº 8.540/1992

### Dicas de prova
- Entenda a diferença entre família natural e família substituta.
- Conheça os direitos fundamentais das crianças e adolescentes e como eles são protegidos.
- Avalie as implicações da colocação em família substituta e do acolhimento familiar e institucional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.34 (2)", "page_number": 34, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 98 da Lei nº 8.540/1992"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T20:19:46.481511+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=34", "doc_key": "9b4fb6c2b4e13629caa9c590a26552f1"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', 'e401b39541695dbb05f680b9015709c4e760b0dac6fdbd72ca3b17449fcb832b'),
  ('cpiuris2025::b6f0bdb7cfb60424ae368ab2adfedcfd', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Apartheid Familiar e Apartheid Social', '## Apartheid Familiar e Apartheid Social

O apartheid familiar e o apartheid social são instituições que afetam a vida das crianças e adolescentes acolhidos, sendo o apadrinhamento uma forma de promover vínculos afetivos seguros e duradouros.

### Conceitos
- **Apartheid Familiar**: Instituição que separa crianças e adolescentes acolhidos de suas famílias biológicas
- **Apartheid Social**: Instituição que separa crianças e adolescentes acolhidos de outras crianças e adolescentes da sociedade
- **Apartheid Institucional**: Instituição que separa crianças e adolescentes acolhidos de outros grupos de pessoas, como a comunidade

### Referências legais
- Art. 8 da Lei 8.069/1990
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o conceito de apartheid familiar e social
- Conheça a importância do apadrinhamento afetivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.36 (2)", "page_number": 36, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 8 da Lei 8.069/1990", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T20:21:56.629160+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=36", "doc_key": "b6f0bdb7cfb60424ae368ab2adfedcfd"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', '22c5936f1fde6b799cf80ea9936543158725d7a50ecbbfd4e673713539d071ac'),
  ('cpiuris2025::47ddadbd622cc33c8d95a1c4a7cfbb18', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Acolhimento Familiar ou Institucional', '## Acolhimento Familiar ou Institucional

O objetivo do acolhimento familiar ou institucional é propiciar a volta da criança à família natural em algum momento, ou viabilizar sua colocação em família substituta.

### Conceitos
- **Acolhimento Familiar**: Procedimento que visa reintegrar a criança na família natural
- **Colocação em Família Substituta**: Viabilização de colocação da criança em uma família substituta quando não é possível reingresso à família natural
- **Relatório Interprofissional**: Documento apresentado pela equipe interprofissional ao juiz competente, fundamentando a decisão sobre o acolhimento familiar ou institucional

### Referências legais
- Art. 19-A da Lei n.º 13.509/2017
- Código Penal (hipóteses excepcionais)

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre acolhimento familiar e colocação em família substituta
- Importância do relatório interprofissional na decisão do juiz', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.35 (2)", "page_number": 35, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 19-A da Lei n.º 13.509/2017", "Código Penal (hipóteses excepcionais)"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T20:21:56.891254+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=35", "doc_key": "47ddadbd622cc33c8d95a1c4a7cfbb18"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', 'cd630cef85a0a085a43f1a5d827f1322f6f66b286ccc6bb165792bfd5e451d99'),
  ('cpiuris2025::c25a8e5dcea1b317094582396d5650c8', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Busca à família extensa na adoção', '## Busca à família extensa na adoção

A busca à família extensa é obrigatória antes de decidir a adoção, para garantir a manutenção dos vínculos do bebê com a família natural. O prazo máximo é de 90 dias.

### Conceitos
- **Busca à família extensa**: Obrigatória antes da adoção, para garantir a manutenção dos vínculos do bebê com a família natural.
- **Prazo máximo de busca**: 90 dias
- **Extinção do poder familiar**: Decretada quando não há indicação do genitor e não existir outro representante da família extensa apto a receber a guarda.
- **Colocação sob guarda provisória**: Determinada quando não há busca à família extensa ou não é possível

### Referências legais
- Art. 25 do ECA
- Parágrafo único do art. 25 do ECA

### Dicas de prova
- Distinção entre busca à família extensa e extinção do poder familiar
- Prazo máximo de busca e prazo para ação de adoção', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.36 (1)", "page_number": 36, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 25 do ECA", "Parágrafo único do art. 25 do ECA"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T20:22:21.597343+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=36", "doc_key": "c25a8e5dcea1b317094582396d5650c8"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', '2d13c2a7823e9188cb58e62761439efc42c8db6af3a04943e47272dd087454db'),
  ('cpiuris2025::da636ce8bba961204ed5fc114ac3741a', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Poder Familiar', '## Poder Familiar

O poder familiar é caracterizado como um múnus público, irrenunciável e inalienável, não podendo ser transferido a terceiros.

### Conceitos
- **poder-dever**: múnus público
- **irrenunciabilidade**: não pode ser renunciado
- **inalienabilidade**: não pode ser transferido a terceiros

### Referências legais
- Art. 236 do Código Civil
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o conceito de poder familiar e suas características principais.
- Diferencie entre múnus público, irrenunciabilidade e inalienabilidade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.37 (2)", "page_number": 37, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 236 do Código Civil", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T20:23:36.491769+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=37", "doc_key": "da636ce8bba961204ed5fc114ac3741a"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', 'fdb3be54de176b81a636555fed5c57088b08c03b1055406474143433e9333513'),
  ('cpiuris2025::0d4528f2a64406c60cf2f67f3b1a454d', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Poder Familiar e Apadrinhamento', '## Poder Familiar e Apadrinhamento

O poder familiar é o conjunto de direitos e deveres que protegem a segurança, moralidade e educação da criança e do adolescente. O apadrinhamento financeiro é uma forma de contribuição para o desenvolvimento da criança, podendo ser realizado por pessoas físicas ou jurídicas.

### Conceitos
- **Poder Familiar**: conjunto de direitos e deveres que protegem a segurança, moralidade e educação da criança e do adolescente
- **Apadrinhamento Financeiro**: forma de contribuição para o desenvolvimento da criança, podendo ser realizado por pessoas físicas ou jurídicas
- **Guarda**: modalidade de guarda que não envolve a responsabilidade pela guarda remanescer com o estabelecimento acolhedor ou família acolhedora

### Referências legais
- Art. 226, § 5º da CF
- Art. 21 do ECA

