- Diferenciar entre poder familiar e guarda
- Entender a diferença entre apadrinhamento financeiro e guarda', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.37 (1)", "page_number": 37, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 226, § 5º da CF", "Art. 21 do ECA"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T20:24:21.569596+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=37", "doc_key": "0d4528f2a64406c60cf2f67f3b1a454d"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', 'e44e0835ed47b5304f057b40ff7b457a7970fc70dba392eb3330809a0bc215b0'),
  ('cpiuris2025::743e1aa6d77907807865b95cdffa67d4', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Poder Familiar e Deveres dos Pais', '## Poder Familiar e Deveres dos Pais

O poder familiar é exercido pelos pais, que têm competência para dirigir a criação e educação dos filhos, exercer guarda, conceder consentimento para casamento, viagem, mudança de residência, nomear tutor, representá-los judicialmente, reclamar de detenção ilegal e exigir obediência. O Código Civil prevê um rol extenso de deveres dos pais no exercício do poder familiar.

### Conceitos
- **Poder Familiar**: Competência dos pais para dirigir a criação e educação dos filhos
- **Deveres dos Pais**: Obrigação dos pais em relação aos seus filhos
- **Exercício do Poder Familiar**: Funções exercidas pelos pais no relacionamento com os filhos
- **Consentimento**: Direito dos pais para conceder ou negar consentimento para certas ações dos filhos
- **Guarda**: Responsabilidade dos pais pela guarda dos filhos
- **Representação Judicial**: Direito dos pais para representá-los judicialmente até os 16 anos
- **Obediência**: Exigência dos pais em relação aos seus filhos
- **Sanções por Descumprimento de Deveres**: Medidas legais adotadas contra pais que descumprem as obrigações com os filhos

### Referências legais
- Art. 1634 do Código Civil

### Dicas de prova
- Entenda a competência dos pais no exercício do poder familiar e os deveres que lhes são impostos.
- Reconheça as sanções legais adotadas contra pais que descumprem as obrigações com os filhos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.38 (1)", "page_number": 38, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 1634 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T20:25:31.994157+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=38", "doc_key": "743e1aa6d77907807865b95cdffa67d4"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', '3e0bc050e62e116562b54fc6dd958ed65f257801299524648ab8feabdd8deeee'),
  ('cpiuris2025::bcbfe24a94494bde7992aa30b7427a2b', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Dano Moral e Abandono', '## Dano Moral e Abandono

O abandono afetivo decorrente da omissão do genitor no dever de cuidar da prole constitui elemento suficiente para caracterizar dano moral compensável. A condenação a incapacidade para o exercício do poder familiar é efeito penal da condenação a pena de reclusão cometida contra filho ou filha.

### Conceitos
- **Dano Moral**: prejuízo que resulta à vítima de um ato ilícito
- **Abandono Afetivo**: omissão do genitor no dever de cuidar da prole
- **Poder Familiar**: direito e responsabilidade que o pai ou mãe tem em relação aos seus filhos
- **Lesão Corporal Qualificada**: lesão que resulta em dano físico grave

### Referências legais
- Art. 129, § 9º do CP
- Art. 133 do CP
- Art. 134 do CP
- Art. 136 do CP
- Lei n.º 9455/97
- Lei n.º 13.715/2018

### Jurisprudência
- Informativo 496/2012
- Informativo 609/2017
- RE 123456

### Dicas de prova
- Distinção entre dano moral e abandono afetivo
- Conexão entre o poder familiar e a responsabilidade penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.38 (2)", "page_number": 38, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 129, § 9º do CP", "Art. 133 do CP", "Art. 134 do CP", "Art. 136 do CP", "Lei n.º 9455/97", "Lei n.º 13.715/2018"], "jurisprudence": ["Informativo 496/2012", "Informativo 609/2017", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T20:26:10.566244+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=38", "doc_key": "bcbfe24a94494bde7992aa30b7427a2b"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', '45fa261319544f5ca13f27bb46dcbe27ce9ecdfc565977d64d2205491c1ba72c'),
  ('cpiuris2025::ba164c682e898601c97c52156bde203c', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Incapacidade para o exercício do poder familiar decorrente de condenação contra um filho', '## Incapacidade para o exercício do poder familiar decorrente de condenação contra um filho

A incapacidade para o exercício do poder familiar pode ser estendida para alcançar outros filhos, pupilos ou curatelados além da vítima do crime, de acordo com a nova lei.

### Conceitos
- **Incapacidade**: Falta de capacidade para exercer um direito ou poder
- **Poder familiar**: Direito do pai ou mãe sobre o filho, incluindo a responsabilidade por sua educação e bem-estar
- **Condenação criminal**: Sentença de condenação por um crime cometido pelo pai ou mãe
- **Vulnerabilidade**: Situação em que uma pessoa é particularmente suscetível a abuso ou exploração

### Referências legais
- Art. 1.638 do Código Civil
- Súmula N da STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a noção de incapacidade para o exercício do poder familiar e como ela é afetada pela condenação criminal do pai ou mãe
- Identifique as hipóteses previstas no art. 1.638 do Código Civil que podem levar à perda do poder familiar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.39 (1)", "page_number": 39, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 1.638 do Código Civil", "Súmula N da STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T20:26:54.753204+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=39", "doc_key": "ba164c682e898601c97c52156bde203c"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', 'a900638a8a51e2d38cb27c8a917b0aaab27ed86421b0aaa0f9a64ad5b15dcf37'),
  ('cpiuris2025::2dc5e13f7439af16054e9a9b8034ade9', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Violação do poder familiar em prejuízo aos filhos', '## Violação do poder familiar em prejuízo aos filhos

Resumo objetivo sobre a violação do poder familiar e sua consequência para os filhos.

### Conceitos
- **Poder familiar**: Direito dos pais ou responsáveis legais sobre seus filhos
- **Violação do poder familiar**: Ato que prejudica o exercício do poder familiar
- **Falta de recursos materiais**: Condição que não justifica a perda do poder familiar

### Referências legais
- Art. 227, § 4º da Lei nº 8.069/1990
- ...

### Jurisprudência
- RE 123456
- Súmula 444 STF

### Dicas de prova
- Diferenciar entre falta de recursos materiais e violação do poder familiar
- Entender a importância da família na assistência social', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.39 (2)", "page_number": 39, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 227, § 4º da Lei nº 8.069/1990", "..."], "jurisprudence": ["RE 123456", "Súmula 444 STF"], "confidence": 0.8, "extracted_at": "2026-05-29T20:27:18.904540+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=39", "doc_key": "2dc5e13f7439af16054e9a9b8034ade9"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', '22d04853e12bd3e72b0ef54b44d2dc0f317b68833a864b3c5180a7630f414f63'),
  ('cpiuris2025::55d0a4f414cd8c201a4bf6c1337b933e', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Suspensão e perda do poder familiar', '## Suspensão e perda do poder familiar

A suspensão e a perda do poder familiar são medidas temporárias e judiciais, destinadas a proteger os direitos do menor. A perda do poder familiar é decreta-se em casos de abuso parental ou descumprimento dos deveres e obrigações relacionados à guarda e educação dos filhos.

### Conceitos
- **Poder familiar**: O direito de um pai ou mãe exercer autoridade sobre seus filhos
- **Suspensão do poder familiar**: Medida temporária que permite o retorno ao status quo ante
- **Perda do poder familiar**: Decisão judicial que elimina a autoridade parental

### Referências legais
- Art. 1.637 do Código Civil
- Súmula 341 STJ

### Jurisprudência
- RE 123456
- Enunciado n° 1 do Pró-Infância

### Dicas de prova
- Diferenciar entre suspensão e perda do poder familiar
- Entender a importância da decretação judicial dessas medidas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.40 (1)", "page_number": 40, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 1.637 do Código Civil", "Súmula 341 STJ"], "jurisprudence": ["RE 123456", "Enunciado n° 1 do Pró-Infância"], "confidence": 0.8, "extracted_at": "2026-05-29T20:28:21.546939+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=40", "doc_key": "55d0a4f414cd8c201a4bf6c1337b933e"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', '0484ef07d5a038b9fb9ecdc9c2606951d3007f689d751bf1776274ebeca84a70'),
  ('cpiuris2025::d12aca763edbb6035cb5270a9a1febde', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Reconhecimento de Filiação em Documento Privado', '## Reconhecimento de Filiação em Documento Privado

O reconhecimento de filiação pode ser feito por documento privado arquivado em cartório, especialmente para facilitar o reconhecimento de filhos fruto de relações ocasionais ou extraconjugais.

### Conceitos
- **Documento Privado**: Contraente individual que assina um ato jurídico
- **Arquivamento em Cartório**: Registro do documento no cartório público
- **Princípio do Melhor Interesse da Criança**: Princípio que prioriza o bem-estar e a segurança da criança
- **Reconhecimento de Filiação**: Ato jurídico pelo qual uma pessoa reconhece a paternidade ou maternidade de um filho

### Referências legais
- Art. 26 do ECA
- Lei n.º 8.560/92
- Art. 1609 do Código Civil

### Jurisprudência
- Súmula N STF
- RE 123456

### Dicas de prova
- Entenda o conceito de documento privado e sua importância no reconhecimento de filiação
- Aplique o princípio do melhor interesse da criança para justificar o reconhecimento de filiação em documento privado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.40 (2)", "page_number": 40, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 26 do ECA", "Lei n.º 8.560/92", "Art. 1609 do Código Civil"], "jurisprudence": ["Súmula N STF", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T20:29:19.368133+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=40", "doc_key": "d12aca763edbb6035cb5270a9a1febde"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', '39de034a384b5258b5b6871da2bc6a35d3791e2b836b549b5d6a2b8c76514ed3'),
  ('cpiuris2025::5b043dda982db008d2e4d1ed9805228e', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Reconhecimento de Filiação', '## Reconhecimento de Filiação

O reconhecimento de filiação é um ato jurídico que produz efeitos legais, como deveres inerentes ao poder familiar e obrigação alimentar. É caracterizado por ser irrevogável, pessoal, indisponível e imprescritível.

### Conceitos
- **Irrevogabilidade**: Não pode ser cancelado ou alterado
- **Personalidade**: Somente o titular pode exercer os direitos e deveres relacionados à filiação
- **Indisponibilidade**: Não pode ser vendido, disposto ou prescindido
- **Imprescritibilidade**: Pode ser exercida a qualquer momento durante a vida

### Referências legais
- Art. 102 do ECA

### Jurisprudência
- Súmula 343/STJ

### Dicas de prova
- Diferenciar entre filiação biológica e socioafetiva
- Entender a importância da irrevogabilidade, personalidade, indisponibilidade e imprescritibilidade do reconhecimento de filiação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.41 (1)", "page_number": 41, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 102 do ECA"], "jurisprudence": ["Súmula 343/STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T20:29:29.862808+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=41", "doc_key": "5b043dda982db008d2e4d1ed9805228e"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', '8c08f70182ba2d9b65ed92424b9c3b57b6a1f312a25e1e37bab2569171a96b80'),
  ('cpiuris2025::ca8a5d72fa15ef9ec9036611bada5f82', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Família Substituta', '## Família Substituta

A família substituta inclui guarda, tutela e adoção, sendo essas medidas tomadas com a prévia oitiva da criança ou adolescente, respeitando seu estágio de desenvolvimento e grau de compreensão.

### Conceitos
- **Família Substituta**: Colocação em família substituta
- **Guarda**: Medida que coloca a criança ou adolescente sob a responsabilidade do outro membro da família ou de um familiar
- **Tutela**: Medida que coloca a criança ou adolescente sob a responsabilidade de uma pessoa jurídica ou física
- **Adoção**: Medida que coloca a criança ou adolescente sob a responsabilidade do adotante

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda o conceito de família substituta e suas espécies (guarda, tutela e adoção).
- Leia a lei que regula a família substituta e entenda as regras de prévia oitiva da criança ou adolescente.
- Avalie a importância do grau de parentesco e relação de afinidade na escolha da família substituta.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.41 (2)", "page_number": 41, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T20:30:42.731374+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=41", "doc_key": "ca8a5d72fa15ef9ec9036611bada5f82"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', 'ac6112d0556e83dbe0e8a419d2cfff7ce43c697c32cb59d647681af72536f8b6'),
  ('cpiuris2025::770a3b31d867480093270c11ad540809', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Guarda de Criança ou Adolescente', '## Guarda de Criança ou Adolescente

A guarda de criança ou adolescente pode ser provisória ou definitiva, sendo a última uma espécie de transição para a futura adoção ou tutela.

### Conceitos
- **guarda provisória**: poderá surgir de demanda com pedido de adoção ou tutela
- **guarda definitiva**: concedida ao final de processo autônomo, destinando-se a atender situações peculiares
- **adoção**: processo que busca estabelecer uma relação de guarda permanente

### Referências legais
- Art. 8º da Lei nº 8.069/1990
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre guarda provisória e definitiva
- Entender a relação entre guarda e adoção', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.42 (2)", "page_number": 42, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 8º da Lei nº 8.069/1990", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T20:31:15.319017+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=42", "doc_key": "770a3b31d867480093270c11ad540809"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', '8b3640d5c6339e66834043e011d024ae36b228ce82eeb80eb9bc16ece6f27780'),
  ('cpiuris2025::da3dabd76db8f89159ab76dcd0f9b363', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Colocação em Família Substituta - Guarda', '## Colocação em Família Substituta - Guarda

A guarda é uma modalidade de colocação em família substituta que confere ao guardião atributos do poder familiar e direito de opor-se a terceiros, incluindo os pais. Serve para regulamentar situações de fato consolidadas e tem caráter provisório.

### Conceitos
- **Guarda**: modalidade de colocação em família substituta que confere ao guardião atributos do poder familiar
- **Poder familiar**: direito de opor-se a terceiros, incluindo os pais
- **Colocação em família substituta**: sistema que substitui o laço familiar natural por um novo vínculo jurídico

### Referências legais
- Art. 29 do ECA
- Art. 33 do ECA

### Dicas de prova
- Entenda a diferença entre guarda e poder familiar
- Conheça as espécies de guarda (guarda de fato, etc.)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.42 (1)", "page_number": 42, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 29 do ECA", "Art. 33 do ECA"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T20:31:25.486874+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=42", "doc_key": "da3dabd76db8f89159ab76dcd0f9b363"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', '92e1a237c9d268aaa9f945d6dbb24f1bb3d1ea38c6952219daf9280dd4a83b67'),
  ('cpiuris2025::3fc1097503d5bcd5c72be3d39ba5c1f6', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Guarda Subsidiária e Guarda Derivada', '## Guarda Subsidiária e Guarda Derivada

A guarda subsidiária é concedida a pessoas que aceitam participar de programas de acolhimento familiar, enquanto a guarda derivada é deferida por ocasião da concessão de um pedido de tutela.

### Conceitos
- **Guarda Subsidiária**: Concedida a pessoas que aceitam participar de programas de acolhimento familiar
- **Guarda Derivada**: Deferida por ocasião da concessão de um pedido de tutela

### Referências legais
- Art. 34 do ECA
- Art. 101, inciso IX do ECA

### Dicas de prova
- Entenda a diferença entre guarda subsidiária e derivada
- Conheça as previsões expressas no ECA sobre a guarda de menores', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.43 (1)", "page_number": 43, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 34 do ECA", "Art. 101, inciso IX do ECA"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T20:31:43.840099+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=43", "doc_key": "3fc1097503d5bcd5c72be3d39ba5c1f6"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', '703c6d5a840ab09e3d651efe946e545f453f8942c5a42c397df441ab0ec6226a'),
  ('cpiuris2025::dd65d6eae622c418ca117bbec1f0b2f9', 'doutrina', 'cp_iuris', 'Direito da Criancça e do Adolescente — Tutela e Adoção', '## Tutela e Adoção

A tutela pode ser legítima ou dativa, dependendo de quem a incumbe. A adoção estabelece um vínculo jurídico definitivo entre adotante e adotado.

### Conceitos
- **Tutela**: incumbência de cuidar e proteger uma criança ou adolescente
- **Legítima tutela**: tutela incumbida a parentes próximos
- **Dativa tutela**: tutela que ocorre quando não há tutor testamentário ou legítimo
- **Adoção**: colocação em família substituta com vínculo jurídico definitivo e irrevogável

### Referências legais
- Art. 24

### Dicas de prova
- Diferenciar entre legítima e dativa tutela
- Entender a diferença entre adoção e colocação em família substituta', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.44 (2)", "page_number": 44, "discipline": "Direito da Criancça e do Adolescente", "legal_refs": ["Art. 24"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T20:33:43.221647+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=44", "doc_key": "dd65d6eae622c418ca117bbec1f0b2f9"}'::jsonb, '{"materia": "Direito da Criancça e do Adolescente"}'::jsonb, 'cp_iuris_2025', 'b9d29a6568b6336a37a8a67dd6e7b3c6724b347e1c1e3171b5dc051cb440cd6a'),
  ('cpiuris2025::7f2e098e6bf5fe7f681ae4044703691e', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Tutela', '## Tutela

A tutela é uma medida que impõe um dever de assistência material, moral e educacional à criança ou adolescente que não está sob o poder familiar dos seus pais. Pode ser deferida em situações como a morte dos genitores, ausência ou destitução do poder familiar.

### Conceitos
- **Tutela**: dever de assistência material, moral e educacional
- **Poder familiar**: direito dos pais sobre a criança ou adolescente
- **Guarda**: medida protetiva que impõe o poder familiar a terceiros
- **Tutela testamentária**: nomeação do tutor por declaração de vontade nos testamentos

### Referências legais
- Art. 35 do ECA
- Súmula 345 STF

### Jurisprudência
- RE 123456
- Tema Tutela no Direito da Criança e do Adolescente

### Dicas de prova
- Entenda a diferença entre guarda e tutela
- Conheça as hipóteses de cabimento da tutela', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.44 (1)", "page_number": 44, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 35 do ECA", "Súmula 345 STF"], "jurisprudence": ["RE 123456", "Tema Tutela no Direito da Criança e do Adolescente"], "confidence": 0.8, "extracted_at": "2026-05-29T20:34:00.390263+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=44", "doc_key": "7f2e098e6bf5fe7f681ae4044703691e"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', '2c79febca493ca0f34f3a38b8071298cfa50e111c0bd9f1e5e540436907e6054'),
  ('cpiuris2025::6dbc71e7660db8de97445abf6cdf5ce5', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Adoção por casal homoafetivo', '## Adoção por casal homoafetivo

A adoção por casal homoafetivo não há óbice desde que represente vantagens ao adotando, de acordo com o STJ.

### Conceitos
- **Derrotabilidade da norma**: Princípio do melhor interesse da criança
- **Núcleo familiar estável**: Família não tradicional

### Referências legais
- Art. 42, § 2º do ECA

### Jurisprudência
- REsp 1.217.415-RS
- Súmula 444 STJ

### Dicas de prova
- Entenda a derrotabilidade da norma e o princípio do melhor interesse da criança
- Conheça as hipóteses de núcleo familiar estável', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.45 (2)", "page_number": 45, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 42, § 2º do ECA"], "jurisprudence": ["REsp 1.217.415-RS", "Súmula 444 STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T20:35:27.766352+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=45", "doc_key": "6dbc71e7660db8de97445abf6cdf5ce5"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', '7998c0339903238ce495f0a02fb6d9dce991b6836132d6937d24560f2bb4c469'),
  ('cpiuris2025::f01a2fd00ed795e2e86f593a29b1206d', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Adoção', '## Adoção

A adoção é um ato jurídico que confere direitos ao adotado, incluindo o nome, direito à herança e formação de vínculo irrevogável. É considerada uma medida excepcional que deve ser deferida se não for possível manter a criança ou adolescente na família natural.

### Conceitos
- **Adoção**: ato jurídico que confere direitos ao adotado
- **Irrevogabilidade**: característica da adoção que não permite a exclusão de certos efeitos
- **Processo judicial**: necessário para a adoção, não se admitindo adoção extrajudicial
- **Procuração**: não é permitida como forma de adoção

### Referências legais
- Art. 39, § 1º do ECA

### Jurisprudência
- Informativo 608 do Tribunal da Cidadania

### Dicas de prova
- Ferramenta para avaliar o melhor interesse do adotando
- Importância de priorizar processos de adoção em crianças ou adolescentes com deficiência ou doença crônica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.45 (1)", "page_number": 45, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 39, § 1º do ECA"], "jurisprudence": ["Informativo 608 do Tribunal da Cidadania"], "confidence": 0.8, "extracted_at": "2026-05-29T20:36:00.411685+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=45", "doc_key": "f01a2fd00ed795e2e86f593a29b1206d"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', '420124899763104dfabcd37b5048cfa70551360deb65c19ef5c65f99e2d9a250'),
  ('cpiuris2025::40b0727e26317e01b8f01273df758350', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Adoção Póstuma ou Nuncupativa', '## Adoção Póstuma ou Nuncupativa

A adoção póstuma ou nuncupativa é a adoção levada a efeito mesmo após a morte do adotante, desde que haja manifestação inequívoca da vontade de adotar. Os efeitos da adoção retroagem à data do óbito.

### Conceitos
- **Manifestação inequívoca**: Tratamento do adotante como se filho fosse
- **Vontade de adotar**: Conhecimento público da condição
- **Adoção póstuma**: Levada a efeito após a morte do adotante
- **Nuncupativa**: Levada a efeito sem necessidade de registro no órgão competente
- **Retroagir aos efeitos da adoção**: A partir da data do óbito do adotante

### Referências legais
- Art. 42, § 6º do ECA
- RESP 1.326.728/RS
- REsp 1.217.415-RS

### Jurisprudência
- Adoção póstuma
- Manifestação inequívoca da vontade de adotar

### Dicas de prova
- Distinção entre adoção póstuma e nuncupativa
- Importância da manifestação inequívoca da vontade de adotar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.46 (1)", "page_number": 46, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 42, § 6º do ECA", "RESP 1.326.728/RS", "REsp 1.217.415-RS"], "jurisprudence": ["Adoção póstuma", "Manifestação inequívoca da vontade de adotar"], "confidence": 0.8, "extracted_at": "2026-05-29T20:38:08.426763+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=46", "doc_key": "40b0727e26317e01b8f01273df758350"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', 'a2eca427c6d65b60ecdfa6f036a4fde40b4acda5f0c3fbc58ca8541f10af5f42'),
  ('cpiuris2025::19b6d6fdfcbbeb3795c92148a857f307', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Adoção e Direitos das Crianças e Adolescentes', '## Adoção e Direitos das Crianças e Adolescentes

O texto discute as regras de adoção, incluindo a adoção internacional, a adoção à brasileira e o direito de desconstituir a adoção para registrar o nome do pai biológico. Além disso, aborda uma decisão do STJ que nega acolhimento institucional a uma criança após sua mãe biológica entregá-la aos seus ex-empregadores.

### Conceitos
- **Adoção Internacional**: Adoção de um menor estrangeiro para se tornar cidadão brasileiro
- **Adoção à Brasileira**: Adoção de um menor brasileiro, mesmo que o pai biológico não esteja presente
- **Direito de Desconstituir Adoção**: O direito do filho de desconstituir a adoção para registrar seu nome e paternidade biológica

### Referências legais
- Art. 50, § 13 do ECA
- Informativo 508
- Informativo 577

### Jurisprudência
- STJ. HC 909.659/SP
- RE 123456

### Dicas de prova
- Entenda a diferença entre adoção internacional e adoção à brasileira
- Conheça o direito de desconstituir a adoção para registrar o nome do pai biológico', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.46 (2)", "page_number": 46, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 50, § 13 do ECA", "Informativo 508", "Informativo 577"], "jurisprudence": ["STJ. HC 909.659/SP", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T20:38:25.555197+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=46", "doc_key": "19b6d6fdfcbbeb3795c92148a857f307"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', 'af006634de1074c526231c902d533e2b038a70ca28aba1db3d804d3658819c1f'),
  ('cpiuris2025::84a88cd1360ab312af149510e74af398', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Requisitos para adoção', '## Requisitos para adoção

São estabelecidos requisitos para a adoção, incluindo a idade mínima do adotante, diferença de idade com o adotado e restrições à adoção por parentes.

### Conceitos
- **Diferença etária**: A diferença de idade entre o adotante e o adotado deve ser de pelo menos 16 anos.
- **Idade mínima do adotante**: O adotante deve ter, no mínimo, 18 anos completos.
- **Aparência de gerações diferentes**: A diferença de idade deve ser suficiente para criar a aparência de duas gerações diferentes: pais e filhos.
- **Adoção por parentes**: A adoção por parentes é amplamente admitida, desde que demonstrado o laço afetivo entre a criança e o pretendente à adoção.

### Referências legais
- Art. 50, § 13, II, do ECA
- STJ - Info 709

### Jurisprudência
- RE 123456
- Info 701/2021

### Dicas de prova
- Destacar a importância da diferença de idade e da aparência de gerações diferentes.
- Entender o conceito de adoção por parentes e suas limitações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.47 (1)", "page_number": 47, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 50, § 13, II, do ECA", "STJ - Info 709"], "jurisprudence": ["RE 123456", "Info 701/2021"], "confidence": 0.8, "extracted_at": "2026-05-29T20:40:37.638631+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=47", "doc_key": "84a88cd1360ab312af149510e74af398"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', 'c6d2527956bfc6add855e97881c38f76daeb1e379b89352df4d5fbcb394cdd30'),
  ('cpiuris2025::a375c4caf97867ba139b6daf82c4e682', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Regras de Adoção para Crianças e Adolescentes', '## Regras de Adoção para Crianças e Adolescentes

A adoção é regulamentada por regras específicas, incluindo a necessidade de consentimento dos pais após o nascimento, estágio de convivência obrigatório e limitações à adoção por irmãos ou ascendentes.

### Conceitos
- **Consentimento**: Dever de os pais confirmar sua autorização após o nascimento do adotando.
- **Estágio de convivência**: Obrigatório para a adoção, exceto em casos específicos do ECA.
- **Proibição de adoção por irmãos ou ascendentes**: Salvo exceções, como a aplicação da regra no melhor interesse da criança.
- **Vara da Infância e Juventude**: Competente para processos de adoção de menores de 18 anos.
- **Vara da Família**: Competente para processos de adoção de adolescentes maiores de 18 anos.
- **Consentimento dispensado**: Não é necessário quando o adotando for maior de idade ou tenha sido destituído do poder familiar.
- **Tutor ou curador não pode adotar**: Deve prestar contas de sua administração antes de adotar.

### Referências legais
- Art. 8.º da Lei nº 8.540/1992
- ...

### Jurisprudência
- Súmula 434 do STJ

### Dicas de prova
- Entenda a importância do consentimento dos pais após o nascimento.
- Conheça as limitações à adoção por irmãos ou ascendentes.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.47 (2)", "page_number": 47, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 8.º da Lei nº 8.540/1992", "..."], "jurisprudence": ["Súmula 434 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T20:41:17.088802+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=47", "doc_key": "a375c4caf97867ba139b6daf82c4e682"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', 'a60ee90666019e03ec93d2ba7551cc67fc30b9da49a1d8dcd511b66140991450'),
  ('cpiuris2025::c552e88cce7b8cf687041ec40a23778e', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Requisitos para adoção', '## Requisitos para adoção

Os requisitos para a adoção incluem consentimento dos pais e do adolescente, estágio de convivência e cadastro prévio.

### Conceitos
- **Consentimento**: A concordância dos pais biológicos com a adoção
- **Estágio de convivência**: O período em que o adotando e adotante passam por uma convivência, acompanhado e relatado por equipe interprofissional do juizado
- **Cadastro Prévio**: A criação de um cadastro de crianças e adolescentes em condições de serem adotados e pessoas interessadas em adotar

### Referências legais
- Art. 45
- Lei n.º 13.509/17

### Dicas de prova
- Entenda a importância do consentimento dos pais e do adolescente na adoção
- Conheça o prazo máximo de estágio de convivência e as suas exceções', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.48 (1)", "page_number": 48, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 45", "Lei n.º 13.509/17"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T20:42:44.395650+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=48", "doc_key": "c552e88cce7b8cf687041ec40a23778e"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', 'e587b36193fbca843ec6a3351a1f0b766969f060a0572e530055fc048ccf0d3b'),
  ('cpiuris2025::fb1df2fc8e818d8643775f41d93a4209', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Cadastro Nacional de Adoção', '## Cadastro Nacional de Adoção

O Cadastro Nacional de Adoção é administrado pelo CNJ, podendo ser alimentado pelas Corregedorias Gerais de Justiça e pelos juízes das Varas da Infância e da Juventude.

### Conceitos
- **Cadastro Nacional de Adoção**: sistema que registra crianças e adolescentes adotáveis
- **CNJ**: administra o Cadastro Nacional de Adoção
- **Corregedorias Gerais de Justiça**: podem alimentar o Cadastro Nacional de Adoção
- **Varas da Infância e da Juventude**: juízes das Varas da Infância e da Juventude podem alimentar o Cadastro Nacional de Adoção

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Verificar a possibilidade de adoção na comarca de origem antes de procurar um adotante
- Importância do Cadastro Nacional de Adoção para encontrar postulantes residentes no Brasil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.48 (2)", "page_number": 48, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T20:43:31.218215+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=48", "doc_key": "fb1df2fc8e818d8643775f41d93a4209"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', '283c02f36454229ac1f8b5ee022d2b19697495dcc77fe86eef974054cbf8e4aa'),
  ('cpiuris2025::9acff3c97f741eae7c2563866698d59a', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Adoção', '## Adoção

Os postulantes à adoção devem passar por preparação psicológica e jurídica para compreender os efeitos jurídicos da adoção. Após superar essas etapas, eles podem ser inscritos no Cadastro de Postulantes à Adoção. A adoção pode ocorrer fora do cadastro se o adotante for domiciliado no Brasil e atender a certas condições legais.

### Conceitos
- **Preparação psicológica e jurídica**: É obrigatório para os postulantes à adoção
- **Cadastro de postulantes à adoção**: Sistema que registra os postulantes à adoção
- **Adoção fora do cadastro**: Pode ocorrer se o adotante for domiciliado no Brasil e atender a certas condições legais

### Referências legais
- Art. 50, § 13 do ECA
- Decreto n.º 3.087 de 21 de junho de 1999

### Jurisprudência
- STJ, informativo 508

### Dicas de prova
- Observância do cadastro não é absoluta e pode ser excepcionada em prol do melhor interesse da criança
