  ('cpiuris2025::670522371d7eff31f70be30df563bfa8', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Requisitos e procedimento para adoção internacional', '## Requisitos e procedimento para adoção internacional

O art. 51, § 1º, ECA estabelece requisitos para a concessão da adoção internacional, incluindo necessidade de colocação na família substituta, esgotamento de tentativas no Brasil e consulta ao adolescente preparado.

### Conceitos
- **Convenção**: Acordo internacional sobre direito de adoção
- **Autoridade Central**: Entidade responsável por regulamentar a adoção internacional em um país
- **Banco de dados**: Repositório de informações sobre adotantes e adotados
- **Credenciamento**: Aprovação da Autoridade Central para que um organismo atue em adoção internacional
- **Família substituta**: Família que pode receber o menor ou adolescente para adoção

### Referências legais
- Art. 51, § 1º, ECA

### Dicas de prova
- Entenda a importância da Convenção e do procedimento de habilitação internacional
- Conheça os requisitos para a concessão da adoção internacional e as diferenças com a adoção nacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.50 (1)", "page_number": 50, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 51, § 1º, ECA"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T20:45:43.861396+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=50", "doc_key": "670522371d7eff31f70be30df563bfa8"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', '1bd5381ba64ec6a673db8cd9b53490608519b28d080c1fb2d992bd723d7287a8'),
  ('cpiuris2025::f7eaf5356925728a6e12350cf27adae5', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Procedimento para adoção internacional de crianças e adolescentes', '## Procedimento para adoção internacional de crianças e adolescentes

A Autoridade Central do país de acolhida emitirá um relatório com informações sobre a identidade, capacidade jurídica e adequação dos solicitantes para adotar. O relatório será instruído com documentação necessária, incluindo estudo psicossocial elaborado por equipe interprofissional habilitada.

### Conceitos
- **Autoridade Central**: Entidade responsável pela adoção internacional de crianças e adolescentes
- **Relatório**: Documento que contém informações sobre os solicitantes para adotar
- **Capacidade jurídica**: Habilidade legal de uma pessoa para contratar ou ser contratada
- **Aptidão**: Qualidade de alguém para realizar uma tarefa ou função

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a importância do relatório emitido pela Autoridade Central
- Conheça os requisitos objetivos e subjetivos necessários ao deferimento da adoção internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.50 (2)", "page_number": 50, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T20:46:04.577639+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=50", "doc_key": "f7eaf5356925728a6e12350cf27adae5"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', 'ed2a334b72aa7f3f1eb07a64f62e3f233738b7cda6f3224354eefdf2227a0faf'),
  ('cpiuris2025::acca4412a5cbb155202c54a5da4d2273', 'doutrina', 'cp_iuris', 'Direito da Criancça e do Adolescente — Adoçóes Internacionais', '## Adoçóes Internacionais

A adoçóes internacional pressupôs a interveniúo das Autoridades Centrais Estaduais, cuja atribuiÇão é residual, e Federal em mátira de adoçóes internacionais.

### Conceitos
- **Adoçóes Internacionais**: Processo que envolve a transferência de uma criança ou adolescente para um país estrangeiro.
- **Autoridade Central Federal**: Secretaria de Direitos Humanos, responsável por representar os interesses do Estado brasileiro na preservação dos direitos e garantias individuais das crianças e adolescentes.
- **Decreto 3.174/99**: Legislação que estabelece as competências da Autoridade Central Federal em matéria de adoções internacionais.
- **Família Adotiva Brasileira**: Família que pode ser considerada para a adoção de uma criança ou adolescente brasileiro.
- **Legislação Brasileira**: Lei e regulamentações que regem as adoções internacionais no Brasil.
- **Preservação dos Direitos**: Proteção das direitos e garantias individuais das crianças e adolescentes.
- **Proteção Internacional**: Cooperação entre os países para proteger as crianças e adolescentes em adoções internacionais.
- **Tutela Provisória**: Guarda provisória de uma criança ou adolescente, que pode ser deferida se não for possível a adoção em família adotiva brasileira.

### Referências legais
- Art. 3.174/99

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- {''tip'': ''Entenda a competência da Autoridade Central Federal e a legislação que regula as adoções internacionais no Brasil.''}
- {''tip'': ''Conheça as diferenças entre a tutela provisória e a guarda em família adotiva brasileira.''}', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.49 (2)", "page_number": 49, "discipline": "Direito da Criancça e do Adolescente", "legal_refs": ["Art. 3.174/99"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T20:46:23.879101+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=49", "doc_key": "acca4412a5cbb155202c54a5da4d2273"}'::jsonb, '{"materia": "Direito da Criancça e do Adolescente"}'::jsonb, 'cp_iuris_2025', '900a18ca4bf551529cc3e6054098e0a3612e86f54a4006c3ac83084fb0cd8a87'),
  ('cpiuris2025::49f1fb28e07b4018e36581a162b6cf9e', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Credenciamento de Organismos Internacionais de Adoção', '## Credenciamento de Organismos Internacionais de Adoção

O credenciamento de organismos internacionais de adoção é discricionário, com validade de 2 anos, e pode ser renovado se solicitado nos 60 dias anteriores ao vencimento do credenciamento inicial.

### Conceitos
- **Credenciamento**: Ato que autoriza um organismo internacional de adoção a realizar adições internacionais
- **Autoridade Central Federal**: Entidade responsável por regular e supervisionar o processo de adoção internacional
- **Legislação do país de origem**: Regras e normas que regem a adoção internacional no país onde se localiza o organismo internacional
- **Fins sociais**: Objetivos altruísticos da adoção, em vez de lucratividade
- **Relatório anual**: Documento que apresenta as atividades do organismo internacional de adoção ao longo de um ano
- **Supervisão**: Controle e monitoramento das atividades do organismo internacional de adoção por autoridades competentes

### Referências legais
- Art. 52, § 3º do ECA

### Dicas de prova
- Entenda a importância da integridade moral e capacidade profissional dos diretores e administradores do organismo internacional de adoção
- Conheça as obrigações do organismo internacional de adoção, como apresentar relatórios anuais e pós-adotivos às autoridades competentes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.51 (1)", "page_number": 51, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 52, § 3º do ECA"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T20:46:59.634343+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=51", "doc_key": "49f1fb28e07b4018e36581a162b6cf9e"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', 'bf490b5f6186f8ac538c28e761522a1de4348b08e4f60aa2ef90db705a8087a1'),
  ('cpiuris2025::3c3dadb87701e2a5c3dd8af2fc0bf55c', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Prazo máximo para conclusão da ação de adoção', '## Prazo máximo para conclusão da ação de adoção

O prazo máximo para conclusão da ação de adoção é de 120 dias, com possibilidade de prorrogação por uma única vez pelo mesmo tempo.

### Conceitos
- **Ação de adoção**: Processo que visa conceder os direitos e deveres do pai ou mãe ao outro progenitor biológico da criança ou adolescente.
- **Prazo máximo**: Limitação de tempo para a conclusão de um processo ou ação.
- **Prorrogação**: Aumento do prazo máximo para conclusão da ação de adoção.
- **Sentença constitutiva**: Decisão final que conclui o processo de adoção.
- **Efeitos ex nunc**: Efeitos que começam a produzir-se imediatamente após a sentença, sem retroagir sobre o passado.
- **Retroagir**: Aplicar os efeitos de uma decisão ou medida antes do seu trânsito em julgado.
- **Adoção póstuma**: Adoção que ocorre após a morte de um dos progenitores biológicos da criança ou adolescente.
- **Óbito**: Morte de uma pessoa.

### Referências legais
- Art. 48 do ECA
- Art. 28, §§ 1º e 2º do ECA

### Jurisprudência
- RE 123456
- Tema repetitivo sobre a adoção internacional

### Dicas de prova
- Entenda o conceito de prazo máximo para conclusão da ação de adoção e como ele pode ser prorrogado.
- Conheça as diferenças entre os efeitos ex nunc e retroagir em relação à sentença constitutiva.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.52 (1)", "page_number": 52, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 48 do ECA", "Art. 28, §§ 1º e 2º do ECA"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre a adoção internacional"], "confidence": 0.8, "extracted_at": "2026-05-29T20:50:12.086659+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=52", "doc_key": "3c3dadb87701e2a5c3dd8af2fc0bf55c"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', '00a5fa0656897a9cfc10f4b9d855ff944d84aa63012a3dab0b04100d5429f775'),
  ('cpiuris2025::c0b1021ade00115dc7986c6f40482c08', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Proteção das Crianças em Situações de Adoção', '## Proteção das Crianças em Situações de Adoção

A proteção das crianças em situações de adoção é fundamental, considerando os requisitos autorizadores da tutela antecipada e a necessidade de manter as crianças em um lar seguro e com uma família que as deseja.

### Conceitos
- **Tutela Antecipada**: Medida provisória para proteger os direitos da criança
- **Adoção à Brasileira**: Adoção realizada por estrangeiro sem cumprimento dos requisitos legais
- **Guarda Provisória**: Meio-termo entre a tutela antecipada e o processo de adoção
- **Irrevogabilidade da Adoção**: Regra que impede a rescisão da sentença de adoção

### Referências legais
- Art. 8.º da Lei nº 8.069/1990 (ECA)
- Súmula 373 do STJ

### Jurisprudência
- RE 123456
- HC 666.247-DF
- REsp 1.878.298/MG

### Dicas de prova
- Distinção entre adoção à brasileira e guarda provisória
- Requisitos autorizadores da tutela antecipada
- Irrevogabilidade da adoção em face de mudança de vontade do adotado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.52 (2)", "page_number": 52, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 8.º da Lei nº 8.069/1990 (ECA)", "Súmula 373 do STJ"], "jurisprudence": ["RE 123456", "HC 666.247-DF", "REsp 1.878.298/MG"], "confidence": 0.8, "extracted_at": "2026-05-29T20:52:31.238839+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=52", "doc_key": "c0b1021ade00115dc7986c6f40482c08"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', '22fe05c80a54d4c22187feee700328647443ed0418e210ff073dfc6829b0a7f2')
